begin;
    with j as (select * from jsonb_to_recordset($law7v022$[{"code_id":"NK_RF","article_number":"101.2","version_date":"2000-07-31","article_text":"1. В случае обжалования решения налогового органа о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения в апелляционном порядке такое решение вступает в силу в части, не отмененной вышестоящим налоговым органом, и в необжалованной части со дня принятия вышестоящим налоговым органом решения по апелляционной жалобе.\n\n2. В случае, если вышестоящий налоговый орган, рассматривающий апелляционную жалобу, отменит решение нижестоящего налогового органа и примет новое решение, такое решение вышестоящего налогового органа вступает в силу со дня его принятия.\n\n3. В случае, если вышестоящий налоговый орган оставит без рассмотрения апелляционную жалобу, решение нижестоящего налогового органа вступает в силу со дня принятия вышестоящим налоговым органом решения об оставлении апелляционной жалобы без рассмотрения, но не ранее истечения срока подачи апелляционной жалобы.\n\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 137-ФЗ) (В редакции Федерального закона от 02.07.2013 № 153-ФЗ)","article_title":"Статья 101.2. Вступление в силу решения налогового органа о привлечении к ответственности за совершение налогового правонарушения и решения об отказе в привлечении к ответственности за совершение налогового правонарушения при обжаловании в апелляционном порядке","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"72b5f1b7867958b95320ce2b5a7793b627ef1289292dca5c9e220fcf905da6db"},{"code_id":"NK_RF","article_number":"101.3","version_date":"2000-07-31","article_text":"1. Решение о привлечении к ответственности за совершение налогового правонарушения или решение об отказе в привлечении к ответственности за совершение налогового правонарушения подлежит исполнению со дня его вступления в силу.\n\n2. Обращение соответствующего решения к исполнению возлагается на налоговый орган, вынесший это решение. В случае рассмотрения жалобы вышестоящим налоговым органом в апелляционном порядке вступившее в силу соответствующее решение направляется в налоговый орган, вынесший первоначальное решение, в течение трех дней со дня вступления в силу соответствующего решения.\n\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 101.3. Исполнение решения налогового органа о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e3803a1a53cdc0ac1ebf152e0f4388f64a84eb0c23e3ff8ca97aa37d681d7fa"},{"code_id":"NK_RF","article_number":"101.4","version_date":"2000-07-31","article_text":"1. При обнаружении фактов, свидетельствующих о нарушениях законодательства о налогах и сборах, ответственность за которые установлена настоящим Кодексом (за исключением налоговых правонарушений, дела о выявлении которых рассматриваются в порядке, установленном статьей 101\n\nнастоящего Кодекса), должностным лицом налогового органа в течение 10 дней со дня выявления указанного нарушения должен быть составлен в установленной форме акт, подписываемый этим должностным лицом и лицом, совершившим такое нарушение. Об отказе лица, совершившего нарушение законодательства о налогах и сборах, подписать акт делается соответствующая запись в этом акте. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nПри рассмотрении акта могут оглашаться составленный акт, иные материалы мероприятий налогового контроля, а также письменные возражения лица, привлекаемого к ответственности за совершение налогового правонарушения. Отсутствие письменных возражений не лишает этого лица права давать свои объяснения на стадии рассмотрения акта.\n\nПри рассмотрении акта заслушиваются объяснения лица, привлекаемого к ответственности, исследуются иные доказательства. Не допускается использование доказательств, полученных с нарушением настоящего Кодекса, а также доказательств, полученных из специальной декларации, представленной в соответствии с Федеральным законом \"О добровольном декларировании физическими лицами активов и счетов (вкладов) в банках и о внесении изменений в отдельные законодательные акты Российской Федерации\", и (или) прилагаемых к ней документов и (или) сведений. Если документы (информация) были представлены лицом, привлекаемым к ответственности, в налоговый орган с нарушением установленных настоящим Кодексом сроков, то полученные документы (информация) не будут считаться полученными с нарушением настоящего Кодекса. (В редакции федеральных законов от 26.11.2008 № 224-ФЗ; от 08.06.2015 № 150-ФЗ)\n\nПри рассмотрении материалов налоговой проверки ведется протокол. (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\nВ ходе рассмотрения акта и других материалов мероприятий налогового контроля может быть принято решение о привлечении в случае необходимости к участию в этом рассмотрении свидетеля, эксперта, специалиста.\n\nВ ходе рассмотрения акта и других материалов руководитель (заместитель руководителя) налогового органа:\n\n1) устанавливает, допускало ли лицо, в отношении которого был составлен акт, нарушения законодательства о налогах и сборах;\n\n2) устанавливает, образуют ли выявленные нарушения состав налоговых правонарушений, содержащихся в настоящем Кодексе;\n\n3) устанавливает, имеются ли основания для привлечения лица, в отношении которого был составлен акт, к ответственности за совершение налогового правонарушения;\n\n4) выявляет обстоятельства, исключающие вину лица в совершении налогового правонарушения, или обстоятельства, смягчающие или отягчающие ответственность за совершение налогового правонарушения.\n\n1) о привлечении лица к ответственности за налоговое правонарушение;\n\n2) об отказе в привлечении лица к ответственности за налоговое правонарушение.\n\nВ решении о привлечении к ответственности за совершение налогового правонарушения указываются срок, в течение которого лицо, в отношении которого вынесено указанное решение, вправе обжаловать это решение, порядок обжалования решения в вышестоящий налоговый орган, а также указываются наименование органа, место его нахождения, другие необходимые сведения. (В редакции Федерального закона от 02.07.2013 № 153-ФЗ)\n\n12. Несоблюдение должностными лицами налоговых органов требований, установленных настоящим Кодексом, может являться основанием для отмены решения налогового органа вышестоящим налоговым органом или судом.\n\nНарушение существенных условий процедуры рассмотрения акта и иных материалов мероприятий налогового контроля является основанием для отмены решения налогового органа вышестоящим налоговым органом или судом. К таким существенным условиям относится обеспечение возможности лица, в отношении которого был составлен акт, участвовать в процессе рассмотрения материалов лично и (или) через своего представителя и обеспечение возможности этого лица представить объяснения.\n\nОснованиями для отмены решения налогового органа вышестоящим налоговым органом или судом могут являться иные нарушения процедуры рассмотрения материалов, если только такие нарушения привели или могли привести к принятию неправильного решения.\n\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 101.4. Производство по делу о предусмотренных настоящим Кодексом налоговых правонарушениях","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b4dc0bf258c06e61ba82295a000967a82c9d62dc5a588cbaa65aeb7e81902a7"},{"code_id":"NK_RF","article_number":"102","version_date":"2000-07-31","article_text":"1) являющихся общедоступными, в том числе ставших таковыми с согласия их обладателя - налогоплательщика (плательщика страховых взносов). Такое согласие представляется по выбору налогоплательщика (плательщика страховых взносов) в отношении всех сведений или их части, полученных налоговым органом, по форме, формату и в порядке, утверждаемым федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов; (В редакции федеральных законов от 01.05.2016 № 134-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n2) об идентификационном номере налогоплательщика;\n\n(Подпункт 3 исключен  - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\n3) о нарушениях законодательства о налогах и сборах (в том числе сумме задолженности при ее наличии) и мерах ответственности за эти нарушения;  (В редакции  федеральных законов от 09.07.1999 № 154-ФЗ, от 01.05.2016 № 134-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n4) предоставляемых налоговым (таможенным) или правоохранительным органам других государств в соответствии с международными договорами (соглашениями), одной из сторон которых является Российская Федерация, о взаимном сотрудничестве между налоговыми (таможенными) или правоохранительными органами (в части сведений, предоставленных этим органам), в том числе в рамках международного автоматического обмена информацией; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.11.2017 № 340-ФЗ)\n\n5) предоставляемых избирательным комиссиям в соответствии с законодательством о выборах по результатам проверок налоговым органом сведений о размере и об источниках доходов кандидата и его супруга, а также об имуществе, принадлежащем кандидату и его супругу на праве собственности; (Дополнение подпунктом - Федеральный закон от 26.04.2007 № 64-ФЗ)\n\n6) предоставляемых в Государственную информационную систему о государственных и муниципальных платежах, предусмотренную Федеральным законом от 27 июля 2010 года № 210-ФЗ \"Об организации предоставления государственных и муниципальных услуг\"; (Дополнение подпунктом - Федеральный закон от 27.06.2011 № 162-ФЗ)\n\n7) о специальных налоговых режимах, применяемых налогоплательщиками, а также об участии налогоплательщика в консолидированной группе налогоплательщиков; (Дополнение подпунктом - Федеральный закон от 30.09.2013 № 267-ФЗ)\n\n8) предоставляемых органам местного самоуправления (органам государственной власти городов федерального значения Москвы, Санкт-Петербурга и Севастополя, органам публичной власти федеральной территории \"Сириус\") в целях осуществления контроля за полнотой и достоверностью информации, представленной плательщиками местных сборов, для расчета сборов, а также о суммах задолженности плательщиков местных сборов; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 382-ФЗ)  (В редакции  федеральных законов от 01.05.2016 № 134-ФЗ, от 11.06.2021 № 199-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n9) о среднесписочной численности работников организации за календарный год, предшествующий году размещения указанных сведений в информационно-телекоммуникационной сети \"Интернет\" в соответствии с пунктом 11 настоящей статьи; (Дополнение подпунктом - Федеральный закон от 01.05.2016 № 134-ФЗ)\n\n10) перечисленных организацией в календарном году, предшествующем году размещения указанных сведений в информационно-телекоммуникационной сети \"Интернет\" в соответствии с пунктом 11 настоящей статьи, в качестве единого налогового платежа суммах денежных средств с указанием их принадлежности, определенной в соответствии с пунктами 7 - 9 статьи 45 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 01.05.2016 № 134-ФЗ) (В редакции  федеральных законов от 03.07.2016 № 243-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n11) о суммах доходов и расходов по данным бухгалтерской (финансовой) отчетности организации за год, предшествующий году размещения указанных сведений в информационно-телекоммуникационной сети \"Интернет\" в соответствии с пунктом 11 настоящей статьи; (Дополнение подпунктом - Федеральный закон от 01.05.2016 № 134-ФЗ)\n\n12) о постановке на учет в налоговых органах иностранных лиц (за исключением сведений о постановке на учет в налоговом органе по месту нахождения недвижимого имущества и (или) транспортных средств); (Дополнение подпунктом - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции  федеральных законов от 31.07.2023 № 389-ФЗ, от 29.05.2024 № 100-ФЗ)\n\n13) о постановке на учет в налоговых органах физических лиц в соответствии с пунктом 73 статьи 83 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n14) о принятых налоговым органом обеспечительных мерах и применении способов обеспечения исполнения обязанности по уплате налогов, сборов, страховых взносов, предусмотренных настоящим Кодексом; (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n15) предоставляемых по запросам Федерального казначейства, финансовых органов субъектов Российской Федерации, муниципальных образований и федеральной территории \"Сириус\" сведений о принадлежности денежных средств, перечисленных в качестве единого налогового платежа, определенной в соответствии с пунктами 7 - 9 статьи 45 настоящего Кодекса, к налогам, сборам, страховым взносам, являющимся источниками формирования доходов соответствующего бюджета; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n16) о номере записи федерального регистра сведений о населении. (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nСроки и период размещения сведений, указанных в абзаце первом настоящего пункта, порядок их формирования и размещения утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 01.05.2016 № 134-ФЗ)\n\nК разглашению налоговой тайны относится, в частности, использование или передача другому лицу информации, составляющей коммерческую тайну (секрет производства) налогоплательщика, плательщика страховых взносов и ставшей известной должностному лицу налогового органа, органа внутренних дел, следственного органа, органа государственного внебюджетного фонда или таможенного органа, привлеченному специалисту или эксперту при исполнении ими своих обязанностей. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 02.01.2000 № 13-ФЗ; от 30.06.2003 № 86-ФЗ; от 28.12.2010 № 404-ФЗ; от 11.07.2011 № 200-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nПо выбору налогоплательщика (плательщика страховых взносов) согласие, предусмотренное абзацем первым настоящего пункта, может быть представлено в отношении всех сведений, полученных налоговым органом, или их части. Указанное согласие направляется в налоговый орган в электронной форме. Формат и порядок направления указанного согласия, порядок представления налоговым органом сведений, составляющих налоговую тайну, иному лицу в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 01.05.2022 № 120-ФЗ)\n\nДоступ к сведениям, составляющим налоговую тайну, имеют должностные лица, определяемые соответственно федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, федеральным органом исполнительной власти, уполномоченным в области внутренних дел, федеральным государственным органом, осуществляющим полномочия в сфере уголовного судопроизводства, федеральным органом исполнительной власти, уполномоченным в области таможенного дела. (В редакции федеральных законов от 29.06.2004 № 58-ФЗ; от 26.06.2008 № 103-ФЗ; от 28.12.2010 № 404-ФЗ)\n\nержащих составляющие налоговую тайну сведения, либо разглашение таких сведений влечет ответственность, предусмотренную федеральными законами.\n\nДоступ к сведениям, составляющим налоговую тайну, в государственных органах, органах местного самоуправления или организациях, в которые такие сведения поступили в соответствии с законодательством Российской Федерации о противодействии коррупции, имеют должностные лица, определяемые руководителями этих государственных органов, органов местного самоуправления или организаций.\n\n(Дополнение пунктом - Федеральный закон от 21.11.2011 № 329-ФЗ) (В редакции Федерального закона от 03.12.2012 № 231-ФЗ)\n\nДоступ к указанным в настоящем пункте сведениям, составляющим налоговую тайну, в государственных органах, в которые такие сведения поступили в соответствии с нормативными правовыми актами Президента Российской Федерации, Правительства Российской Федерации, имеют должностные лица, определяемые руководителями этих государственных органов.\n\n(Дополнение пунктом - Федеральный закон от 28.06.2013 № 134-ФЗ)\n\n1) такие сведения признаются налоговой тайной без исключений, установленных подпунктами 1 - 3 и 5 - 8 пункта 1 настоящей статьи;\n\n2) разглашение таких сведений и утрата представленных специальных деклараций и (или) прилагаемых к ним документов и (или) сведений являются основанием для привлечения к уголовной ответственности за незаконное разглашение сведений, составляющих налоговую тайну, в соответствии с Уголовным кодексом Российской Федерации;\n\n3) должностное лицо налогового органа, которому такие сведения стали известны, не может быть привлечено к ответственности за отказ от дачи показаний по обстоятельствам, которые стали ему известны из сведений, указанных в абзаце первом настоящего пункта;\n\n4) такие сведения могут быть истребованы у налогового органа только по запросу самого декларанта, признаваемого таковым в соответствии с указанным в абзаце первом настоящего пункта Федеральным законом;\n\n5) в случае необходимости подтверждения факта представления в налоговый орган специальной декларации и документов и (или) сведений, прилагаемых к декларации, и достоверности содержащихся в них сведений должностное лицо органа государственной власти или банка, которому в качестве основания для предоставления гарантий, предусмотренных указанным в абзаце первом настоящего пункта Федеральным законом, была представлена копия специальной декларации с отметкой налогового органа о ее принятии, вправе направить ее в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, для сверки с оригиналом специальной декларации, находящейся на централизованном хранении. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в пятидневный срок после получения такой копии специальной декларации направляет ответное уведомление о том, соответствует либо не соответствует полученная копия специальной декларации оригиналу.\n\n(Дополнение пунктом - Федеральный закон от 08.06.2015 № 150-ФЗ)\n\nДоступ к указанным в настоящем пункте сведениям, составляющим налоговую тайну, в финансовых органах субъектов Российской Федерации имеют должностные лица, определяемые руководителями этих финансовых органов.\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 302-ФЗ)\n\nДоступ к указанным в настоящем пункте сведениям, составляющим налоговую тайну, в органах субъектов Российской Федерации, уполномоченных в сфере социальной защиты населения, в Фонде пенсионного и социального страхования Российской Федерации имеют должностные лица, определяемые руководителями указанных органов и фонда соответственно. (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 26.03.2020 № 68-ФЗ) (В редакции Федерального закона от 01.05.2022 № 120-ФЗ)\n\n11. Положения настоящей статьи в части запрета на разглашение сведений, составляющих налоговую тайну, требований к специальному режиму хранения указанных сведений и доступа к ним, ответственности за утрату документов, содержащих указанные сведения, или за разглашение указанных сведений распространяются на сведения о налогоплательщиках, плательщиках страховых взносов, поступившие от налоговых органов в федеральные органы государственной власти, органы государственной власти субъектов Российской Федерации, органы местного самоуправления для осуществления оценки налоговых расходов в соответствии со статьей 1743 Бюджетного кодекса Российской Федерации.\n\nДоступ к указанным в настоящем пункте сведениям, составляющим налоговую тайну, поступившим от налоговых органов в федеральные органы государственной власти, органы государственной власти субъектов Российской Федерации, органы местного самоуправления, имеют должностные лица, определяемые руководителями этих органов.\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nоб использовании (о неиспользовании) налогоплательщиком - физическим лицом права на получение налогового вычета, предусмотренного подпунктом 2 пункта 1 статьи 2191 настоящего Кодекса, в течение срока действия договора на ведение индивидуального инвестиционного счета и иных договоров, прекращенных с переводом активов на этот индивидуальный инвестиционный счет в порядке, предусмотренном пунктом 91 статьи 2261 настоящего Кодекса;\n\nо наличии (об отсутствии) у налогоплательщика в течение срока действия договора на ведение индивидуального инвестиционного счета других договоров на ведение индивидуального инвестиционного счета, за исключением случаев прекращения договора с переводом всех активов, учитываемых на индивидуальном инвестиционном счете, на другой индивидуальный инвестиционный счет, открытый тому же физическому лицу.\n\nДоступ к указанным в настоящем пункте сведениям, составляющим налоговую тайну, у налоговых агентов имеют работники, определяемые руководителями (заместителями руководителей) таких организаций.\n\n(Дополнение пунктом - Федеральный закон от 20.04.2021 № 100-ФЗ)\n\n13. Положения настоящей статьи в части запрета на разглашение сведений, составляющих налоговую тайну, требований к специальному режиму хранения указанных сведений и доступа к ним, ответственности за утрату документов, содержащих указанные сведения, или за разглашение указанных сведений распространяются на сведения о снятии с учета в налоговых органах физических лиц в связи со смертью, поступившие от налоговых органов в банки в целях, установленных Федеральным законом \"О банках и банковской деятельности\".\n\nДоступ к указанным в настоящем пункте сведениям, составляющим налоговую тайну, в банках имеют должностные лица, определяемые руководителями таких банков.\n\n(Дополнение пунктом - Федеральный закон от 19.12.2022 № 552-ФЗ)\n\n14. Положения настоящей статьи в части запрета на разглашение сведений, составляющих налоговую тайну, требований к специальному режиму хранения указанных сведений и доступа к ним, ответственности за утрату документов, содержащих указанные сведения, за разглашение указанных сведений распространяются на сведения, указанные в абзаце шестом подпункта 2 и абзаце пятом подпункта 4 пункта 1 статьи 213, абзаце восьмом пункта 2 статьи 2131 настоящего Кодекса, поступившие от налогового органа страховым организациям и негосударственным пенсионным фондам в рамках обмена информацией в соответствии с правилами обмена информацией о подтверждении неполучения налогоплательщиком социального налогового вычета либо подтверждении факта получения налогоплательщиком суммы предоставленного социального налогового вычета, предусмотренного подпунктом 4 пункта 1 статьи 219 настоящего Кодекса.\n\nДоступ к указанным в настоящем пункте сведениям, составляющим налоговую тайну, в страховых организациях и негосударственных пенсионных фондах имеют работники, определяемые руководителями (заместителями руководителей) таких страховых организаций и негосударственных пенсионных фондов.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n15. Положения настоящей статьи в части запрета на разглашение сведений, составляющих налоговую тайну, требований к специальному режиму хранения указанных сведений и доступа к ним, ответственности за утрату документов, содержащих указанные сведения, или за разглашение указанных сведений распространяются на сведения, составляющие налоговую тайну, передаваемые налоговыми органами в соответствии с Федеральным законом от 12 декабря 2023 года № 565-ФЗ \"О занятости населения в Российской Федерации\" в межведомственные комиссии субъектов Российской Федерации по противодействию нелегальной занятости, федеральный орган исполнительной власти, осуществляющий функции по федеральному государственному контролю (надзору) в сфере труда, занятости, альтернативной гражданской службы, его территориальные органы.\n\nДоступ к предусмотренным настоящим пунктом сведениям, составляющим налоговую тайну, в указанных комиссиях и органах имеют должностные лица, определяемые руководителями указанных комиссий и органов соответственно.\n\n(Дополнение пунктом - Федеральный закон от 30.09.2024 № 335-ФЗ)","article_title":"Статья 102. Налоговая тайна","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1ff67677a8187330a305e0efa1788dfc436a9650ed67848c59760509de4ed230"},{"code_id":"NK_RF","article_number":"103.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 04.11.2005 № 137-ФЗ) (Утратила силу - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 103.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3f74ad90aaaec781813e1a001803c07c5531d9525d6f363baa8c564e1bc4e4a7"},{"code_id":"NK_RF","article_number":"104","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 29.11.2010 № 324-ФЗ)\n\nДо обращения в суд налоговый орган обязан предложить лицу, привлекаемому к ответственности за совершение налогового правонарушения, добровольно уплатить соответствующую сумму налоговой санкции. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2006 № 137-ФЗ)\n\nВ случае, если лицо, привлекаемое к ответственности за совершение налогового правонарушения, отказалось добровольно уплатить сумму налоговой санкции, налоговый орган обращается в суд с заявлением о взыскании с данного лица налоговой санкции, установленной настоящим Кодексом, за совершение данного налогового правонарушения.  (В редакции  федеральных законов от 09.07.1999 № 154-ФЗ, от 27.07.2006 № 137-ФЗ, от 29.11.2010 № 324-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nК заявлению прилагаются решение налогового органа и другие материалы дела, полученные в процессе налоговой проверки. (В редакции Федерального закона от 29.11.2010 № 324-ФЗ)","article_title":"Статья 104. Заявление о взыскании налоговой санкции","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27943e861dd594af193d93f47228f9d3540e170813d9773273dfece0fe50ff2e"},{"code_id":"NK_RF","article_number":"105","version_date":"2000-07-31","article_text":"Исполнение вступивших в законную силу решений судов о взыскании налоговых санкций с организаций, которым открыты лицевые счета, производится в порядке, установленном бюджетным законодательством Российской Федерации. (Дополнение абзацем - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nЗАВИСИМЫМИ ЛИЦАМИ. СОГЛАШЕНИЕ О ЦЕНООБРАЗОВАНИИ. ДОКУМЕНТАЦИЯ ПО МЕЖДУНАРОДНЫМ ГРУППАМ КОМПАНИЙ\n\n(Наименование в редакции Федерального закона от 27.11.2017 № 340-ФЗ)\n\n(Дополнение разделом - Федеральный закон от 18.07.2011 № 227-ФЗ)","article_title":"Статья 105. Рассмотрение дел и исполнение решений о взыскании налоговых санкций","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6711137332c18611b1ee0a1cfbfd0a47a76f44ecc44b4f97795a5ca4cd99ef24"},{"code_id":"NK_RF","article_number":"105.1","version_date":"2000-07-31","article_text":"1. Если особенности отношений между лицами могут оказывать влияние на условия и (или) результаты сделок, совершаемых этими лицами, и (или) экономические результаты деятельности этих лиц или деятельности представляемых ими лиц, указанные в настоящем пункте лица признаются взаимозависимыми для целей налогообложения (далее - взаимозависимые лица).\n\nДля признания взаимной зависимости лиц учитывается влияние, которое может оказываться в силу участия одного лица в капитале других лиц, в соответствии с заключенным между ними соглашением либо при наличии иной возможности одного лица определять решения, принимаемые другими лицами. При этом такое влияние учитывается независимо от того, может ли оно оказываться одним лицом непосредственно и самостоятельно или совместно с его взаимозависимыми лицами, признаваемыми таковыми в соответствии с настоящей статьей.\n\n2. С учетом пункта 1 настоящей статьи в целях настоящего Кодекса взаимозависимыми лицами признаются:\n\n1) организации в случае, если одна организация прямо и (или) косвенно участвует в другой организации и доля такого участия составляет более 25 процентов;\n\n2) физическое лицо и организация в случае, если такое физическое лицо прямо и (или) косвенно участвует в такой организации и доля такого участия составляет более 25 процентов;\n\n3) организации в случае, если одно и то же лицо прямо и (или) косвенно участвует в этих организациях и доля такого участия в каждой организации составляет более 25 процентов;\n\n4) организация и лицо (в том числе физическое лицо совместно с его взаимозависимыми лицами, указанными в подпункте 11 настоящего пункта), имеющее полномочия по назначению (избранию) единоличного исполнительного органа этой организации или по назначению (избранию) не менее 50 процентов состава коллегиального исполнительного органа или совета директоров (наблюдательного совета) этой организации;\n\n5) организации, единоличные исполнительные органы которых либо не менее 50 процентов состава коллегиального исполнительного органа или совета директоров (наблюдательного совета) которых назначены или избраны по решению одного и того же лица (физического лица совместно с его взаимозависимыми лицами, указанными в подпункте 11 настоящего пункта);\n\n6) организации, в которых более 50 процентов состава коллегиального исполнительного органа или совета директоров (наблюдательного совета) составляют одни и те же физические лица совместно с взаимозависимыми лицами, указанными в подпункте 11 настоящего пункта;\n\n7) организация и лицо, осуществляющее полномочия ее единоличного исполнительного органа;\n\n8) организации, в которых полномочия единоличного исполнительного органа осуществляет одно и то же лицо;\n\n9) организации и (или) физические лица в случае, если доля прямого участия каждого предыдущего лица в каждой последующей организации составляет более 50 процентов;\n\n10) физические лица в случае, если одно физическое лицо подчиняется другому физическому лицу по должностному положению;\n\n11) физическое лицо, его супруг (супруга), родители (в том числе усыновители), дети (в том числе усыновленные), полнородные и неполнородные братья и сестры, опекун (попечитель) и подопечный;\n\n12) организации в случае, если физическое лицо, имеющее в одной из таких организаций долю прямого и (или) косвенного участия более 25 процентов и (или) полномочия по назначению (избранию) единоличного исполнительного органа организации или по назначению (избранию) не менее 50 процентов состава коллегиального исполнительного органа или совета директоров (наблюдательного совета) организации, и физическое лицо, имеющее в другой из таких организаций указанную долю участия и (или) указанные полномочия, признаются взаимозависимыми лицами в соответствии с подпунктом 11 настоящего пункта. В целях настоящего подпункта наличие полномочий по назначению (избранию) единоличного исполнительного органа организации или по назначению (избранию) не менее 50 процентов состава коллегиального исполнительного органа или совета директоров (наблюдательного совета) организации определяется для физического лица совместно с его взаимозависимыми лицами, указанными в подпункте 11 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n13) лицо и организация, которые в соответствии со статьей 2513 настоящего Кодекса признаются в целях настоящего Кодекса соответственно контролирующим лицом и контролируемой иностранной компанией; (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n14) организации, которые в соответствии со статьей 2513 настоящего Кодекса признаются в целях настоящего Кодекса контролируемыми иностранными компаниями и контролирующим лицом которых является одно и то же лицо. (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\nУказанные в настоящем пункте организации могут быть признаны взаимозависимыми по иным основаниям, предусмотренным настоящей статьей.","article_title":"Статья 105.1. Взаимозависимые лица","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"74c663d5209f0de091ab0959f9f9f1c83ace922d1c0876d4bba1a55e26056964"},{"code_id":"NK_RF","article_number":"105.10","version_date":"2000-07-31","article_text":"1. Метод цены последующей реализации является методом определения соответствия цены в анализируемой сделке рыночной цене на основании сопоставления валовой рентабельности, полученной лицом, совершившим анализируемую сделку, при последующей реализации (перепродаже) им товара, приобретенного им в этой анализируемой сделке (группе однородных сделок), с рыночным интервалом валовой рентабельности, определенным в порядке, предусмотренном статьей 1058 настоящего Кодекса.\n\n2. Использование метода цены последующей реализации является приоритетным по сравнению с другими методами для определения соответствия рыночным ценам цен, по которым товар приобретается в рамках анализируемой сделки и перепродается без переработки в рамках сделки, сторонами которой являются лица, не признаваемые взаимозависимыми. Указанный метод используется в случае, если лицо, осуществляющее перепродажу, не владеет объектами нематериальных активов, оказывающими существенное влияние на уровень его валовой рентабельности. Метод цены последующей реализации может быть использован также в случаях, когда при перепродаже товара осуществляются следующие операции:\n\n1) подготовка товара к перепродаже и транспортировке (деление товаров на партии, формирование отправок, сортировка, переупаковка);\n\n2) смешивание товаров, если характеристики конечной продукции (полуфабрикатов) существенно не отличаются от характеристик смешиваемых товаров.\n\n3. В случае, если последующая реализация товара в сделках, совершенных в сопоставимых коммерческих и (или) финансовых условиях между лицом, осуществляющим перепродажу, и лицами (лицом), не являющимися (не являющимся) его взаимозависимыми лицами, осуществляется по разным ценам, при определении интервала рентабельности в качестве цены последующей реализации товара используется средневзвешенная цена этого товара по всем таким сделкам.\n\n4. В случае, если валовая рентабельность лица, осуществляющего перепродажу, находится в пределах интервала рентабельности, определенного в порядке, предусмотренном статьей 1058 настоящего Кодекса, для целей налогообложения признается, что цена, по которой товар приобретен в контролируемой сделке, соответствует рыночной цене.\n\n5. В случае, если валовая рентабельность лица, осуществляющего перепродажу, меньше минимального значения интервала рентабельности, определенного в порядке, предусмотренном статьей 1058 настоящего Кодекса, или превышает максимальное значение интервала рентабельности, определенного в порядке, предусмотренном статьей 1058 настоящего Кодекса, для целей налогообложения принимается цена, примененная в контролируемой сделке, определяемая исходя из фактической цены последующей реа\n\nлизации товара и валовой рентабельности, которая соответствует медианному значению интервала рентабельности. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)","article_title":"Статья 105.10. Метод цены последующей реализации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"09f85b4ac687c194f68711fda545d2147c678c6ccba44bc082cc1d65e3321bc1"},{"code_id":"NK_RF","article_number":"105.11","version_date":"2000-07-31","article_text":"1. Затратный метод является методом определения соответствия цены в анализируемой сделке рыночной цене на основании сопоставления валовой рентабельности затрат лица, являющегося стороной анализируемой сделки (группы анализируемых однородных сделок), с рыночным интервалом валовой рентабельности затрат в сопоставимых сделках, определенным в порядке, предусмотренном статьей 1058 настоящего Кодекса.\n\n2. Затратный метод может применяться, в частности, в следующих случаях:\n\n1) при выполнении работ (оказании услуг) лицами, являющимися взаимозависимыми с продавцом (за исключением случаев, когда при выполнении работ (оказании услуг) используются нематериальные активы, оказывающие существенное влияние на уровень рентабельности затрат продавца);\n\n2) при оказании услуг по управлению денежными средствами, включая осуществление торговых операций на рынке ценных бумаг и (или) валютном рынке;\n\n3) при оказании услуг по исполнению функций единоличного исполнительного органа организации;\n\n4) при продаже сырья или полуфабрикатов лицам, являющимся взаимозависимыми с продавцом;\n\n5) при реализации товаров (работ, услуг) по долгосрочным договорам между взаимозависимыми лицами.\n\n3. В случае, если валовая рентабельность затрат продавца, являющегося стороной анализируемой сделки, по указанной сделке находится в пределах интервала рентабельности, определенного в порядке, предусмотренном статьей 1058 настоящего Кодекса, для целей налогообложения признается, что цена, примененная в анализируемой сделке, соответствует рыночным ценам.","article_title":"Статья 105.11. Затратный метод","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"23978a0ccc268b8f8a01536f1e5599db070dde77aac7b0796a86998a992a4e3a"},{"code_id":"NK_RF","article_number":"105.12","version_date":"2000-07-31","article_text":"1. Метод сопоставимой рентабельности заключается в сопоставлении операционной рентабельности, сложившейся у лица, являющегося стороной анализируемой сделки, с рыночным интервалом операционной рентабельности в сопоставимых сделках, определенным в порядке, предусмотренном статьей 1058 настоящего Кодекса.\n\n2. Метод сопоставимой рентабельности может использоваться, в частности, в случае отсутствия или недостаточности информации, на основании которой можно обоснованно сделать вывод о наличии необходимой степени сопоставимости коммерческих и (или) финансовых условий сопоставляемых сделок и использовать методы, указанные в подпунктах 2 и 3 пункта 1 статьи 1057 настоящего Кодекса.\n\n3. Для целей настоящей статьи могут использоваться следующие показатели операционной рентабельности, определяемые в соответствии с пунктом 1 статьи 1058 настоящего Кодекса:\n\n1) рентабельность продаж;\n\n2) рентабельность затрат;\n\n3) рентабельность коммерческих и управленческих расходов;\n\n4) рентабельность активов;\n\n5) иной показатель рентабельности, отражающий взаимосвязь между осуществляемыми функциями, используемыми активами и принимаемыми экономическими (коммерческими) рисками и уровнем вознаграждения.\n\n4. При выборе конкретного показателя рентабельности учитываются вид деятельности, осуществляемый лицом, являющимся стороной анализируемой сделки, осуществляемые им функции, используемые активы и принимаемые экономические (коммерческие) риски, полнота, достоверность и сопоставимость данных, используемых для расчета соответствующей рентабельности, а также экономическая обоснованность такого показателя.\n\n5. Для целей применения настоящей статьи показатели рентабельности используются с учетом следующих особенностей:\n\n1) рентабельность продаж используется при последующей перепродаже товаров, приобретенных у лиц, являющихся взаимозависимыми с лицом, осуществляющим перепродажу, лицам, которые не являются взаимозависимыми с ним, а также при последующей перепродаже товаров, приобретенных у лиц, не являющихся взаимозависимыми с лицом, осуществляющим перепродажу, лицам, которые являются взаимозависимыми с ним;\n\n2) валовая рентабельность коммерческих и управленческих расходов используется в случаях, указанных в подпункте 1 настоящего пункта, если лицо, осуществляющее перепродажу, несет незначительные экономические (коммерческие) риски при приобретении и последующей перепродаже товаров в непродолжительный период и при этом существует прямая взаимосвязь между величиной валовой прибыли от продаж лица, осуществляющего перепродажу, и величиной осуществленных им коммерческих и управленческих расходов;\n\n3) рентабельность затрат используется при выполнении работ, оказании услуг, а также при производстве товаров;\n\n4) рентабельность активов используется при производстве товаров (в частности, если анализируемые сделки совершаются лицами, которые осуществляют капиталоемкую деятельность).\n\n6. При использовании метода сопоставимой рентабельности с рыночным интервалом рентабельности сопоставляется рентабельность той стороны анализируемой сделки, которая отвечает следующим требованиям:\n\n1) сторона анализируемой сделки осуществляет функции, вклад которых в полученную прибыль по сделкам, последовательно совершенным с одним и тем же товаром, меньше, чем вклад другой стороны анализируемой сделки;\n\n2) сторона анализируемой сделки принимает меньшие экономические (коммерческие) риски, чем другая сторона анализируемой сделки;\n\n3) сторона анализируемой сделки не владеет объектами нематериальных активов, оказывающими существенное влияние на уровень рентабельности.\n\n7. В случае, если сторона анализируемой сделки не отвечает требованиям, предусмотренным подпунктами 1 - 3 пункта 6 настоящей статьи, для сопоставления с рыночным интервалом рентабельности выбирается та сторона анализируемой сделки, которая в наибольшей степени отвечает указанным требованиям.\n\n8. В случае, если рентабельность по контролируемой сделке находится в пределах интервала рентабельности, определенного в порядке, предусмотренном статьей 1058 настоящего Кодекса, для целей налогообложения признается, что цена, примененная в этой сделке, соответствует рыночным ценам.\n\n9. В случае, если рентабельность по контролируемой сделке меньше минимального значения интервала рентабельности, определенного в порядке, предусмотренном статьей 1058 настоящего Кодекса, или превышает максимальное значение интервала рентабельности, определенного в порядке, предусмотренном статьей 1058 настоящего Кодекса, для целей налогообложения учитывается медианное значение интервала рентабельности.\n\nНа основании учитываемого в соответствии с настоящим пунктом медианного значения интервала рентабельности осуществляется корректировка прибыли (дохода, выручки) по контролируемой сделке в целях налогообложения.\n\n(Пункт в редакции  Федерального закона от 27.11.2023 № 539-ФЗ)","article_title":"Статья 105.12. Метод сопоставимой рентабельности","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bc8e9a92607fa7a104dcaac277f967c8e56157de7c0473e22495b608231b9ee5"},{"code_id":"NK_RF","article_number":"105.13","version_date":"2000-07-31","article_text":"1. Метод распределения прибыли заключается в сопоставлении фактического распределения между сторонами сделки совокупной прибыли, полученной всеми сторонами этой сделки, с распределением прибыли между сторонами сопоставимых сделок.\n\n2. В случае, если стороны анализируемой сделки (группы однородных анализируемых сделок) одновременно являются сторонами однородных сделок с участием их взаимозависимых лиц и оценка цен по указанным однородным сделкам в целях налогообложения осуществляется в совокупности с анализируемой сделкой, для целей налогообложения совокупная прибыль по анализируемой сделке и указанным однородным сделкам подлежит распределению в порядке, аналогичном порядку распределения прибыли по анализируемой сделке.\n\n1) при невозможности использования методов, предусмотренных подпунктами 1 - 4 пункта 1 статьи 1057 настоящего Кодекса, и при наличии существенной взаимосвязи деятельности, осуществляемой сторонами анализируемой сделки (группы однородных анализируемых сделок);\n\n2) при наличии в собственности (пользовании) сторон анализируемой сделки прав на объекты нематериальных активов, оказывающие существенное влияние на уровень рентабельности (при отсутствии однородных сделок, предметом которых являются объекты нематериальных активов, совершенных с лицами, не являющимися взаимозависимыми), или в случае осуществления стороной анализируемой сделки контроля за использованием таких нематериальных активов. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n1) пропорционально вкладу в совокупную прибыль по анализируемой сделке функций, осуществляемых сторонами анализируемой сделки, используемых ими активов и принимаемых экономических (коммерческих) рисков;\n\n2) пропорционально распределению между сторонами анализируемой сделки доходности, полученной на вложенный капитал, используемый в анализируемой сделке;\n\n3) пропорционально распределению прибыли между сторонами сопоставимой сделки.\n\n1) на основе методов, указанных в подпунктах 1 - 4 пункта 1 статьи 1057 настоящего Кодекса, для каждого лица, являющегося стороной анализируемой сделки (группы однородных анализируемых сделок), на основании рыночного интервала цены для этой стороны определяется расчетная прибыль (убыток), которая (который) рассчитывается с учетом осуществляемых этим лицом функций, используемых им активов, принимаемых экономических и коммерческих рисков;\n\n2) остаточная прибыль (убыток) по анализируемой сделке определяется как разница между совокупной прибылью (убытком), полученной (полученным) по анализируемой сделке, и суммой расчетной прибыли (убытка) от продаж для всех сторон анализируемой сделки.\n\n1) размер затрат, понесенных лицом, являющимся стороной анализируемой сделки, на создание нематериальных активов, использование которых оказывает влияние на величину фактически полученной прибыли (убытка) по анализируемой сделке;\n\n2) характеристики персонала, занятого у лица, являющегося стороной анализируемой сделки, включая его численность и квалификацию (затраченное персоналом время, величина расходов на оплату труда), оказывающие влияние на величину фактически полученной прибыли (убытка) от продаж по анализируемой сделке;\n\n3) рыночная стоимость активов, находящихся в пользовании (распоряжении) лица, являющегося стороной анализируемой сделки, использование которых влияет на величину фактически полученной прибыли (убытка) от продаж по анализируемой сделке;\n\n4) другие показатели, отражающие взаимосвязь между осуществляемыми функциями, используемыми активами и принимаемыми экономическими (коммерческими) рисками и величиной фактически полученной прибыли (убытка) от продаж по анализируемой сделке.\n\n1) данные бухгалтерского учета сторон анализируемой сделки должны быть сопоставимы с данными бухгалтерского учета сторон сопоставимых сделок либо приведены к сопоставимому виду путем осуществления необходимых корректировок;\n\n2) совокупная рентабельность активов сторон анализируемой сделки не должна существенно отличаться от совокупной рентабельности активов сторон сопоставимых сделок либо должна быть приведена к сопоставимому виду путем осуществления необходимых корректировок.\n\nВ случае, если убыток, понесенный налогоплательщиком, являющимся стороной анализируемой сделки, превышает убыток, рассчитанный для этой стороны в соответствии с методом распределения прибыли, для целей налогообложения принимается убыток, рассчитанный для него в соответствии с методом распределения прибыли.\n\nНа основании сопоставления прибыли или убытка, учтенных в целях налогообложения в соответствии с\n\nнастоящим пунктом, с фактически полученной налогоплательщиком прибылью или фактически понесенным убытком осуществляется корректировка прибыли налогоплательщика в целях налогообложения налогом на прибыль организаций.","article_title":"Статья 105.13. Метод распределения прибыли","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"60d9bfb85c8d2a9840384db4c5574e10d68fb56c5d04ac463ac15f39da28cc5e"},{"code_id":"NK_RF","article_number":"105.14","version_date":"2000-07-31","article_text":"1. В целях настоящего Кодекса контролируемыми сделками признаются сделки между взаимозависимыми лицами (с учетом особенностей, предусмотренных настоящей статьей). К сделкам между взаимозависимыми лицами в целях настоящего Кодекса приравниваются следующие сделки:\n\n1) совокупность сделок по реализации (перепродаже) товаров (выполнению работ, оказанию услуг), совершаемых с участием (при посредничестве) лиц, не являющихся взаимозависимыми (с учетом особенностей, предусмотренных настоящим подпунктом). Указанная в настоящем подпункте совокупность сделок приравнивается к сделке между взаимозависимыми лицами, не принимая во внимание наличие третьих лиц, с участием (при посредничестве) которых совершается такая совокупность сделок, при условии, что такие третьи лица, не признаваемые взаимозависимыми и принимающие участие в указанной совокупности сделок:\n\nне выполняют в этой совокупности сделок никаких дополнительных функций, за исключением организации реализации (перепродажи) товаров (выполнения работ, оказания услуг) одним лицом другому лицу, признаваемому взаимозависимым с этим лицом;\n\nне принимают на себя никаких рисков и не используют никаких активов для организации реализации (перепродажи) товаров (выполнения работ, оказания услуг) одним лицом другому лицу, признаваемому взаимозависимым с этим лицом;\n\n2) сделки в области внешней торговли товарами, которые входят в состав одной или нескольких товарных групп, предусмотренных пунктом 5 настоящей статьи; (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\n3) сделки, одной из сторон которых является физическое лицо, организация или иностранная структура без образования юридического лица, если местом жительства, либо местом регистрации, либо местом налогового резидентства соответствующего лица, иностранной структуры без образования юридического лица или одного из участников (пайщиков, доверителей, иных лиц) либо иных бенефициаров, в интересах которых иностранная структура без образования юридического лица осуществляет свою деятельность, является государство или территория, включенные в утверждаемый Министерством финансов Российской Федерации перечень государств и территорий, предоставляющих льготный налоговый режим налогообложения и (или) не предусматривающих раскрытия и предоставления информации при проведении финансовых операций (офшорные зоны). В целях настоящего подпункта, если деятельность российской организации образует постоянное представительство в государстве или на территории, включенных в перечень, указанный в настоящем подпункте, и анализируемая сделка связана с этой деятельностью, в части этой анализируемой сделки такая организация рассматривается как лицо, местом регистрации которого является государство или территория, включенные в указанный перечень. (В редакции  федеральных законов от 27.11.2023 № 539-ФЗ, от 19.12.2023 № 595-ФЗ)\n\n1) стороны сделки применяют разные ставки по налогу на прибыль организаций (за исключением ставок, предусмотренных пунктами 2 - 4 статьи 284 настоящего Кодекса) к прибыли от деятельности, в рамках которой заключена указанная сделка; (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n2) одна из сторон сделки является налогоплательщиком налога на добычу полезных ископаемых, исчисляемого по налоговой ставке, установленной в процентах, и предметом сделки является добытое полезное ископаемое, признаваемое для указанной стороны сделки объектом налогообложения налогом на добычу полезных ископаемых, при добыче которого налогообложение производится по налоговой ставке, установленной в процентах;\n\n3) хотя бы одна из сторон сделки является налогоплательщиком, применяющим систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог) (если соответствующая сделка заключена в рамках такой деятельности), при этом в числе других лиц, являющихся сторонами указанной сделки, есть лицо, не применяющее указанный специальный налоговый режим; (В редакции Федерального закона от 02.07.2021 № 305-ФЗ)\n\n4) одна из сторон сделки освобождена от обязанностей налогоплательщика налога на прибыль организаций; (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n5) (Подпункт утратил силу - Федеральный закон от 03.08.2018 № 302-ФЗ)\n\n6) сделка удовлетворяет одновременно следующим условиям:\n\nодна из сторон сделки является налогоплательщиком, указанным в пункте 1 статьи 2752 настоящего Кодекса, и учитывает доходы (расходы) по такой сделке при определении налоговой базы по налогу на прибыль организаций в соответствии со статьей 2752 настоящего Кодекса;\n\nлюбая другая сторона сделки не является налогоплательщиком, указанным в пункте 1 статьи 2752 настоящего Кодекса, либо является налогоплательщиком, указанным в пункте 1 статьи 2752 настоящего Кодекса, но не учитывает доходы (расходы) по такой сделке при определении налоговой базы по налогу на прибыль организаций в соответствии со статьей 2752 настоящего Кодекса;\n\n(Дополнение подпунктом - Федеральный закон от 30.09.2013 № 268-ФЗ)\n\n7) (Дополнение подпунктом - Федеральный закон от 30.09.2013 № 267-ФЗ) (Утратил силу - Федеральный закон от 03.08.2018 № 302-ФЗ)\n\n8) хотя бы одна из сторон сделки является исследовательским корпоративным центром, указанным в Федеральном законе \"Об инновационном центре \"Сколково\" (далее в настоящем Кодексе - исследовательский корпоративный центр), либо участником проекта в соответствии с Федеральным законом от 29 июля 2017 года № 216-ФЗ \"Об инновационных научно-технологических центрах и о внесении изменений в отдельные законодательные акты Российской Федерации\", применяющими освобождение от исполнения обязанностей налогоплательщика налога на добавленную стоимость в соответствии со статьей 1451 настоящего Кодекса, либо участником Военного инновационного технополиса \"Эра\" Министерства обороны Российской Федерации в соответствии с Федеральным законом от 14 июля 2022 года № 253-ФЗ \"О Военном инновационном технополисе \"Эра\" Министерства обороны Российской Федерации и о внесении изменений в отдельные законодательные акты Российской Федерации\", применяющим освобождение от исполнения обязанностей налогоплательщика налога на добавленную стоимость в соответствии со статьей 1452 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 28.12.2016 № 475-ФЗ) (В редакции  федеральных законов от 30.10.2018 № 373-ФЗ, от 23.11.2024 № 399-ФЗ)\n\n9) хотя бы одна из сторон сделки применяет в течение налогового периода инвестиционный налоговый вычет по налогу на прибыль организаций, предусмотренный статьей 2861 настоящего Кодекса. Положения настоящего подпункта не применяются к сделкам, доходы и (или) расходы по которым признаются в соответствии с главой 25 настоящего Кодекса с 1 января 2022 года по 31 декабря 2024 года, вне зависимости от даты заключения соответствующего договора; (Дополнение подпунктом - Федеральный закон от 27.11.2017 № 335-ФЗ) (В редакции Федерального закона от 26.03.2022 № 67-ФЗ)\n\n10) хотя бы одна из сторон сделки является налогоплательщиком налога на дополнительный доход от добычи углеводородного сырья и доходы (расходы) по такой сделке учитываются при определении налоговой базы по налогу на дополнительный доход от добычи углеводородного сырья. (Дополнение подпунктом - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nСделки, предусмотренные пунктом 2 настоящей статьи, признаются контролируемыми, если сумма доходов по таким сделкам между указанными лицами за соответствующий календарный год превышает 1 миллиард рублей. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n(Пункт в редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n1) сторонами которых являются участники одной и той же консолидированной группы налогоплательщиков, образованной в соответствии с настоящим Кодексом (за исключением сделок, предметом которых является добытое полезное ископаемое, признаваемое объектом налогообложения налогом на добычу полезных ископаемых, при добыче которого налогообложение производится по налоговой ставке, установленной в процентах, а также сделок, доходы (расходы) по которым учитываются при определении налоговой базы по налогу на дополнительный доход от добычи углеводородного сырья); (В редакции федеральных законов от 16.11.2011 № 321-ФЗ; от 19.07.2018 № 199-ФЗ)\n\n2) сторонами которых являются лица, удовлетворяющие одновременно следующим требованиям:\n\nуказанные лица зарегистрированы в одном субъекте Российской Федерации;\n\nуказанные лица не имеют обособленных подразделений на территориях других субъектов Российской Федерации, а также за пределами Российской Федерации;\n\nуказанные лица не уплачивают налог на прибыль организаций в бюджеты других субъектов Российской Федерации;\n\nуказанные лица не имеют убытков (включая убытки прошлых периодов, переносимые на будущие налоговые периоды), принимаемых при исчислении налога на прибыль организаций;\n\nотсутствуют обстоятельства для признания совершаемых такими лицами сделок контролируемыми в соответствии с подпунктами 2 - 7 пункта 2 настоящей статьи; (В редакции Федерального закона от 30.09.2013 № 267-ФЗ)\n\n3) сделки между налогоплательщиками, указанными в пункте 1 статьи 2752 настоящего Кодекса, совершаемые ими при осуществлении деятельности, связанной с добычей углеводородного сырья на новом морском месторождении углеводородного сырья, в отношении одного и того же месторождения (участка недр - до выделения на соответствующем участке недр первого нового морского месторождения углеводородного сырья); (Дополнение подпунктом - Федеральный закон от 30.09.2013 № 268-ФЗ) (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\n4) межбанковские кредиты (депозиты) со сроком до семи календарных дней (включительно); (Дополнение подпунктом - Федеральный закон от 28.12.2013 № 420-ФЗ)\n\n5) в области военно-технического сотрудничества Российской Федерации с иностранными государствами, осуществляемого в соответствии с Федеральным законом от 19 июля 1998 года № 114-ФЗ \"О военно-техническом сотрудничестве Российской Федерации с иностранными государствами\"; (Дополнение подпунктом - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\n6) сделки по предоставлению поручительств (гарантий) в случае, если все стороны такой сделки являются российскими организациями, не являющимися банками; (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n7) сделки по предоставлению беспроцентных займов между взаимозависимыми лицами, местом регистрации либо местом жительства всех сторон и выгодоприобретателей по которым является Российская Федерация; (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n8) сделки по уступке налогоплательщиком-банком прав (требований) в случае, если такая уступка прав (требований) осуществляется в рамках реализации мероприятий, предусмотренных планом участия Банка России в осуществлении мер по предупреждению банкротства банка, или в случае, если уступка прав (требований) осуществляется в соответствии с порядком, определенным частью 1 статьи 5 Федерального закона от 29 июля 2018 года № 263-ФЗ \"О внесении изменений в отдельные законодательные акты Российской Федерации\"; (Дополнение подпунктом - Федеральный закон от 06.06.2019 № 125-ФЗ)\n\n9) сделки, одной из сторон которых является организация, удовлетворяющая одновременно следующим требованиям:\n\nместом регистрации либо местом налогового резидентства указанной организации является иностранное государство (территория), с которым заключен договор (соглашение, конвенция) об избежании двойного налогообложения, действие которого приостановлено в соответствии с указом Президента Российской Федерации о приостановлении Российской Федерацией действия отдельных положений международных договоров Российской Федерации по вопросам налогообложения;\n\nуказанная организация в соответствии со своим личным законом является экспортно-кредитным агентством и (или) банком;\n\nуказанная организация и иные участники таких сделок не признаются в соответствии со статьей 1051 настоящего Кодекса взаимозависимыми лицами;\n\nотсутствуют обстоятельства для признания таких сделок контролируемыми в соответствии с подпунктами 1 и 2 пункта 1 настоящей статьи;\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n10) сделки, в результате которых у налогоплательщика возникли долговые обязательства, указанные в подпункте 8 пункта 2 статьи 310 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n11) сделки, одной из сторон которых является организация, местом регистрации либо местом налогового резидентства которой является иностранное государство (территория), с которым заключен договор (соглашение, конвенция) об избежании двойного налогообложения, действие которого приостановлено в соответствии с указом Президента Российской Федерации о приостановлении Российской Федерацией действия отдельных положений международных договоров Российской Федерации по вопросам налогообложения, при условии, что договоры (соглашения), на основании которых совершены указанные сделки, заключены до 1 марта 2022 года, порядок определения цен и (или) методик (формул) ценообразования, применяемый в указанных сделках, не изменялся после 1 марта 2022 года и указанные сделки не соответствуют действовавшим по состоянию на 1 марта 2022 года условиям признания сделок контролируемыми сделками в соответствии с пунктами 1 и 3 настоящей статьи. (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n1) нефть и товары, выработанные из нефти;\n\n2) черные металлы;\n\n3) цветные металлы;\n\n4) минеральные удобрения;\n\n5) драгоценные металлы и драгоценные камни.\n\nВ случае совершения сделок между взаимозависимыми лицами или приравненных к ним сделок с участием комиссионера (агента), действующего от своего имени, но по поручению комитента (принципала), для целей настоящей статьи доходы по сделкам между комитентом (принципалом) и лицом, с которым комиссионером (агентом) заключена сделка, учитываются в соответствии с порядком, установленным главой 25 настоящего Кодекса, с применением метода начисления. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n10. По заявлению федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, суд может признать сделку контролируемой при наличии достаточных оснований полагать, что указанная сделка является частью группы однородных сделок, совершенных в целях создания условий, при которых такая сделка не отвечала бы признакам контролируемой сделки, установленным настоящей статьей.\n\n11. Признание сделок контролируемыми производится с учетом положений пункта 13 статьи 1053 настоящего Кодекса.","article_title":"Статья 105.14. Контролируемые сделки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"95ba1bf87e309b8315797292669dad93ff4136c3c21449a73e03e5c0ac0b5344"},{"code_id":"NK_RF","article_number":"105.15","version_date":"2000-07-31","article_text":"1) о деятельности налогоплательщика (лиц), совершившего контролируемую сделку (группу однородных сделок), связанной с этой сделкой:\n\nперечень лиц (с указанием государств и территорий, налоговыми резидентами которых они являются), с которыми совершена контролируемая сделка, описание контролируемой сделки, ее коммерческих и (или) финансовых условий и прочую информацию о сделке;\n\nсведения о функциях лиц, являющихся сторонами сделки, об используемых ими активах, связанных с этой контролируемой сделкой, и о принимаемых ими экономических (коммерческих) рисках, которые налогоплательщик учитывал при ее заключении, с приложением подтверждающих документов;\n\nсведения о доходах и расходах, численности сотру\n\nдников, сумме прибыли (убытка), стоимости основных средств и нематериальных активов иностранного лица (иностранной структуры без образования юридического лица), являющегося стороной контролируемой сделки, за отчетный период, в котором совершена контролируемая сделка, с приложением подтверждающих документов, в том числе финансовой отчетности, если составление финансовой отчетности предусмотрено личным законом указанного лица (иностранной структуры без образования юридического лица) (в случае невозможности представления финансовой отчетности одновременно с документацией она представляется в срок не позднее двенадцати месяцев с даты окончания финансового года, в котором совершена контролируемая сделка). Положения настоящего абзаца применяются в случае, если контролируемая сделка совершена между лицами, признаваемыми взаимозависимыми лицами в соответствии со статьей 1051 настоящего Кодекса;\n\nдокументы, содержащие регистрационные данные иностранного лица (иностранной структуры без образования юридического лица), являющегося стороной контролируемой сделки, и сведения о лицах, выступающих от имени указанного лица (иностранной структуры без образования юридического лица), предоставленные налогоплательщику при заключении контролируемой сделки;\n\n(Подпункт в редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n2) об использованных методах, предусмотренных главой 143 настоящего Кодекса:\n\nанализ коммерческих и (или) финансовых условий контролируемой сделки, осуществленный налогоплательщиком в соответствии со статьей 1055 настоящего Кодекса;\n\nобоснование причин выбора и способа применения метода (комбинации методов), предусмотренного статьей 1057 настоящего Кодекса;\n\nописание корректировок для обеспечения необходимой степени сопоставимости финансовых и (или) коммерческих условий контролируемой сделки и сопоставляемых сделок (организаций);\n\nуказание на источники информации, используемые налогоплательщиком в соответствии со статьей 1056 настоящего Кодекса, в рамках применения метода (комбинации методов), предусмотренного статьей 1057 настоящего Кодекса;\n\nрасчет интервала рыночных цен (интервала рентабельности) по контролируемой сделке в соответствии с методом (комбинацией методов), предусмотренным статьей 1057 настоящего Кодекса, с описанием подхода, используемого для выбора сопоставимых сделок (организаций), и указанием минимального и максимального значений;\n\nсумма полученных доходов (прибыли) и (или) сумма произведенных расходов (понесенных убытков) в результате совершения контролируемой сделки, полученной рентабельности;\n\nсведения об экономической выгоде, получаемой от контролируемой сделки лицом, которым совершена эта сделка, в результате приобретения информации, прав на результаты интеллектуальной деятельности, прав на обозначения, индивидуализирующие предприятие, его продукцию, работы и услуги (фирменное наименование, товарные знаки, знаки обслуживания), и других исключительных прав (при наличии соответствующих обстоятельств);\n\nсведения о прочих факторах, которые оказали влияние на цену (рентабельность), примененную в контролируемой сделке, в том числе сведения о рыночной стратегии лица, совершившего контролируемую сделку, если эта рыночная стратегия оказала влияние на цену (рентабельность), примененную в этой контролируемой сделке (при наличии соответствующих обстоятельств);\n\nсведения о произведенных налогоплательщиком корректировках налоговой базы и сумм налога (убытка) в соответствии с пунктом 6 статьи 1053 настоящего Кодекса (в случае их осуществления);\n\n(Подпункт в редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n3) в случае совершения налогоплательщиком, являющимся участником международной группы компаний, общая сумма дохода (выручки) которой не удовлетворяет условию, предусмотренному подпунктом 3 пункта 6 статьи 10516-3 настоящего Кодекса, контролируемой сделки (группы однородных сделок), одной из сторон и (или) выгодоприобретателем которой является другой участник такой международной группы компаний, местом регистрации, либо местом жительства, либо местом налогового резидентства которого не является Российская Федерация, следующие сведения в дополнение к сведениям, указанным в подпунктах 1 и 2 настоящего пункта:\n\nсведения о структуре органов управления налогоплательщика и идентификационные сведения о лицах, которым подлежит представлению управленческая отчетность, и государствах (территориях), в которых такие лица осуществляют свою основную деятельность;\n\nсведения о деятельности налогоплательщика и его рыночной стратегии, информация о проведенной реструктуризации деятельности налогоплательщика в рамках международной группы компаний (при ее проведении в налоговом периоде совершения сделки или предшествующем налоговом периоде) и передаче (получении) нематериальных активов (в налоговом периоде совершения сделки или предшествующем налоговом периоде), а также пояснения о том, как такая сделка (сделки) повлияла на деятельность налогоплательщика;\n\nсведения об основных конкурентах налогоплательщика;\n\nописание причин, на основании которых сделан вывод о том, что цена, примененная в контролируемой сделке (группе однородных сделок), соответствует рыночной цене;\n\nописание корректировок, производимых для обеспечения сопоставимости условий сделок (при наличии);\n\nкопии существенных соглашений между участниками международной группы компаний, оказывающих влияние на ценообразование в контролируемой сделке (группе однородных сделок);\n\nкопии соглашений о ценообразовании, налоговых разъяснений компетентных органов иностранных государств (территорий), применяемых в сделках между участниками международной группы компаний, которые имеют отношение к анализируемой контролируемой сделке (группе однородных сделок) и в подготовке которых не участвовал федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов;\n\nаудиторское заключение в отношении бухгалтерской (финансовой) отчетности налогоплательщика за последний отчетный период (если налогоплательщик подлежит обязательному аудиту или проводил добровольный аудит).\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2017 № 340-ФЗ)\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, вправе направить налогоплательщику в порядке, предусмотренном пунктами 1, 2 и 5 статьи 93 или пунктом 2 статьи 931 настоящего Кодекса, требование о представлении документации, предусмотренной пунктом 1 настоящей статьи, в отношении сделки (группы однородных сделок). Истребуемая в соответствии с настоящим пунктом документация представляется налогоплательщиком в течение 30 дней со дня получения соответствующего требования. (Дополнение абзацем - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n1) если цены применяются в сделках в соответствии с предписаниями антимонопольных органов в соответствии с пунктом 8 статьи 1053 настоящего Кодекса либо цена является регулируемой и применяется в соответствии со статьей 1054 настоящего Кодекса;\n\n2) при осуществлении налогоплательщиком сделок с лицами, с которыми он не является взаимозависимым, за исключением сделок, приравненных в целях настоящего Кодекса к сделкам между взаимозависимыми лицами в соответствии с подпунктами 1 - 3 пункта 1 статьи 10514 настоящего Кодекса; (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n3) при сделках с ценными бумагами и производными финансовыми инструментами, обращающимися на организованном рынке ценных бумаг (с учетом положений главы 25 настоящего Кодекса); (В редакции Федерального закона  от 03.07.2016 № 242-ФЗ)\n\n4) при осуществлении сделок, в отношении которых в соответствии с главой 146 настоящего Кодекса заключено соглашение о ценообразовании для целей налогообложения.","article_title":"Статья 105.15. Подготовка и представление документации в целях налогового контроля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c49b71785d23fcc0dbe9ecd4db489806702c59bce5e3b52c6645cb16a5695440"},{"code_id":"NK_RF","article_number":"105.16","version_date":"2000-07-31","article_text":"1. Налогоплательщики обязаны уведомлять налоговые органы о совершенных ими в календарном году контролируемых сделках, указанных в статье 10514 настоящего Кодекса.\n\nНалогоплательщики - физические лица вправе представить указанные уведомления на бумажном носителе. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\nФорма (форматы) уведомления о контролируемых сделках, а также порядок заполнения формы и порядок представления уведомления о контролируемых сделках в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по согласованию с Министерством финансов Российской Федерации. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nВ случае обнаружения неполноты сведений, неточностей либо ошибок в заполнении представленного уведомления о контролируемых сделках налогоплательщик вправе направить уточненное уведомление.\n\nВ случае подачи уточненного уведомления до момента, когда налогоплательщик узнал об установлении налоговым органом факта отражения в уведомлении недостоверных сведений о контролируемых сделках, налогоплательщик освобождается от ответственности, предусмотренной статьей 1294 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\n1) календарный год, за который представляются сведения о совершенных налогоплательщиком контролируемых сделках;\n\n2) предметы сделок;\n\n3) сведения об участниках сделок:\n\nполное наименование организации, а также идентификационный номер налогоплательщика (в случае, если организация состоит на учете в налоговых органах в Российской Федерации);\n\nфамилия, имя, отчество индивидуального предпринимателя и его идентификационный номер налогоплательщика;\n\nфамилия, имя, отчество и гражданство физического лица, не являющегося индивидуальным предпринимателем;\n\n4) сумма полученных доходов и (или) сумма произведенных расходов (понесенных убытков) по контролируемым сделкам с выделением сумм доходов (расходов) по сделкам, цены которых подлежат регулированию;\n\n5) сведения об условиях совершения сделки, а в отношении сделки, предметом которой являются товары, также сведения об условиях и о базисе поставки товаров, дате отгрузки товаров (дате перехода права собственности на товары, дате признания дохода (расхода) по сделке); (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n6) сведения об использованных методах, предусмотренных главой 143 настоящего Кодекса, и источниках информации о сопоставимых сделках; (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n7) в отношении сделок, которые в целях настоящего Кодекса признаются контролируемыми сделками в соответствии с пунктом 1 статьи 10514 настоящего Кодекса и предметом которых являются товары, входящие в состав одной или нескольких товарных групп, указанных в пункте 5 статьи 10514 настоящего Кодекса (за исключением сделок между взаимозависимыми лицами, местом регистрации, местом жительства либо местом налогового резидентства всех сторон и выгодоприобретателей по которым является Российская Федерация), между лицами, признаваемыми взаимозависимыми в соответствии со статьей 1051 настоящего Кодекса, также сведения о сделках последующей реализации и (или) предшествующей покупки товаров, в том числе сведения о конечном покупателе и (или) происхождении товаров, ценах, коммерческих и (или) финансовых условиях таких сделок (далее - сведения о цепочке создания стоимости). (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\nО направлении в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, извещения и соответствующих сведений налоговый орган обязан уведомить налогоплательщика не позднее 10 дней со дня направления извещения. (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\nФорма извещения и порядок его направления утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение главой - Федеральный закон от 27.11.2017 № 340-ФЗ)","article_title":"Статья 105.16. Уведомление о контролируемых сделках","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"19ba9c5cf7c5b4d327fcdb77eb5374718d1e959712b7bd8f1309c4248ff13c0f"},{"code_id":"NK_RF","article_number":"105.16-1","version_date":"2000-07-31","article_text":"1. В целях настоящего Кодекса международной группой компаний признается совокупность организаций и (или) иностранных структур без образования юридического лица, связанных между собой посредством участия в капитале и (или) осуществления контроля, для которых соблюдаются все следующие условия:\n\n1) в отношении совокупности организаций и (или) иностранных структур без образования юридического лица, указанной в абзаце первом настоящего пункта, составляется консолидированная финансовая отчетность в соответствии с требованиями законодательства Российской Федерации о бухгалтерском учете либо требованиями фондовых бирж, в том числе иностранных фондовых бирж, при принятии решения о допуске к торгам ценных бумаг любой из указанных организаций и (или) иностранных структур без образования юридического лица или такая отчетность должна была бы составляться, если бы ценные бумаги любой из указанных организаций и (или) иностранных структур без образования юридического лица были допущены к торгам на фондовой бирже, в том числе на иностранной фондовой бирже; (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n2) в состав совокупности организаций и (или) иностранных структур без образования юридического лица, указанной в абзаце первом настоящего пункта, входит хотя бы одна организация (иностранная структура без образования юридического лица), которая признается налоговым резидентом Российской Федерации, либо организация или иностранная структура без образования юридического лица, не признаваемая налоговым резидентом Российской Федерации, которая подлежит налогообложению в отношении предпринимательской деятельности, осуществляемой на территории Российской Федерации через постоянное представительство, и хотя бы одна организация (иностранная структура без образования юридического лица), которая не признается налоговым резидентом Российской Федерации, либо организация или иностранная структура без образования юридического лица, признаваемая налоговым резидентом Российской Федерации, которая подлежит налогообложению в отношении предпринимательской деятельности, осуществляемой на территории иностранного государства (территории) через постоянное представительство.\n\n2. Участником международной группы компаний в целях настоящего Кодекса признаются:\n\n1) лицо, входящее в совокупность организаций и (или) иностранных структур без образования юридического лица, признаваемых международной группой компаний;\n\n2) лицо, относящееся на конец финансового года к организациям и (или) иностранным структурам без образования юридического лица, указанным в пункте 1 настоящей с\n\nтатьи, финансовая отчетность по которому не учитывается при составлении консолидированной финансовой отчетности указанной группы исключительно в силу размера или несущественности данных о таком лице;\n\n3) постоянные представительства лиц, указанных в подпунктах 1 и 2 настоящего пункта.\n\n1) уведомление об участии в международной группе компаний;\n\n2) страновые сведения по международной группе компаний, участником которой является налогоплательщик.\n\n1) глобальная документация по международной группе компаний (далее - глобальная документация);\n\n2) национальная документация участника международной группы компаний (далее - национальная документация);\n\n3) страновой отчет международной группы компаний по государствам (территориям), налоговыми резидентами которых являются участники международной группы компаний (далее - страновой отчет).\n\n1) материнская компания международной группы компаний - участник международной группы компаний, который прямо и (или) косвенно участвует в остальных участниках этой международной группы или иным способом осуществляет контроль над ними и доля участия (наличие контроля) которого является достаточной для того, чтобы финансовая отчетность других участников подлежала включению в консолидированную финансовую отчетность такого участника международной группы компаний либо подлежала бы включению в такую консолидированную финансовую отчетность, если бы ценные бумаги такого участника были бы допущены к торгам на фондовой бирже, в том числе на иностранной фондовой бирже (за исключением случаев, если финансовая отчетность такого участника подлежит включению в консолидированную финансовую отчетность другого участника этой международной группы);\n\n2) уполномоченный участник международной группы компаний - участник международной группы компаний, на которого материнской компанией международной группы компаний возложена обязанность по представлению от имени такой международной группы компаний странового отчета в компетентные органы иностранного государства (территории), налоговым резидентом которого является этот участник либо в котором его деятельность приводит к образованию постоянного представительства;\n\n3) финансовый год - период, за который составляется или должна была бы составляться консолидированная финансовая отчетность международной группы компаний;\n\n4) отчетный период - финансовый год, следующий за финансовым годом, в котором общая сумма дохода (выручки) международной группы компаний в соответствии с консолидированной финансовой отчетностью превышает общую сумму дохода (выручки), указанную в подпункте 3 пункта 6 статьи 10516-3 настоящего Кодекса;\n\n5) консолидированная финансовая отчетность - финансовая отчетность международной группы компаний, составляемая в соответствии с законодательством Российской Федерации, Международными стандартами финансовой отчетности или иными международно признанными стандартами составления финансовой отчетности, принимаемыми фондовыми биржами, в том числе иностранными фондовыми биржами, для принятия решения о допуске ее ценных бумаг к торгам, в которой активы, обязательства, капитал, доход, расходы и денежные потоки материнской компании международной группы компаний и участников международной группы компаний представлены как активы, обязательства, капитал, доход, расходы и денежные потоки единого субъекта экономической деятельности.","article_title":"Статья 105.16-1. Общие положения о документации по международным группам компаний","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d1729de8a0442928f89eac2797ba47b76d5b58e5fbd6968ff04cd3d6cda22e1"},{"code_id":"NK_RF","article_number":"105.16-2","version_date":"2000-07-31","article_text":"1. Налогоплательщики (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса), являющиеся участниками международной группы компаний, в случаях, порядке и сроки, которые установлены настоящей статьей, представляют в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, уведомления об участии в международной группе компаний.\n\n2. Налогоплательщики, являющиеся участниками международной группы компаний, освобождаются от обязанности представления уведомления об участии в международной группе компаний в следующих случаях:\n\n1) материнская компания международной группы компаний или уполномоченный участник международной группы компаний является российской организацией либо иностранной организацией (иностранной структурой без образования юридического лица), добровольно признавшей себя налоговым резидентом Российской Федерации, представили уведомление об участии в международной группе компаний с отражением информации обо всех участниках этой группы, признаваемых налогоплательщиками в соответствии с настоящим Кодексом (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса);\n\n2) уведомление об участии в международной группе компаний представлено участником международной группы компаний, являющимся российской организацией или иностранной организацией (иностранной структурой без образования юридического лица), добровольно признавшей себя налоговым резидентом Российской Федерации, на которого материнской компанией или уполномоченным участником такой международной группы компаний, не являющимися налоговыми резидентами Российской Федерации, возложена обязанность представить уведомление об участии в международной группе компаний с отражением информации обо всех участниках этой международной группы компаний, признаваемых налогоплательщиками в соответствии с настоящим Кодексом (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса).\n\n3. Освобождение от обязанности, предусмотренное пунктом 2 настоящей статьи, применяется в отношении налогоплательщиков, являющихся участниками международной группы компаний, информация о которых представлена в соответствующем уведомлении об участии в международной группе компаний в установленный срок.\n\n4. Уведомление об участии в международной группе компаний представляется по установленному формату только в электронной форме в срок не позднее восьми месяцев с даты окончания отчетного периода для материнской компании такой международной группы компаний.\n\nФормат уведомления об участии в международной группе компаний, порядок его заполнения и представления в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n5. Уведомление об участии в международной группе компаний должно содержать следующие сведения на дату окончания отчетного периода:\n\n1) наименование, основной государственный регистрационный номер, идентификационный номер каждого налогоплательщика, являющегося участником международной группы компаний, код причины постановки его на учет;\n\n2) информация о том, является ли налогоплательщик, представляющий уведомление, материнской компанией международной группы компаний или уполномоченным участником международной группы компаний;\n\n3) информация о включении (невключении) налогоплательщика, представляющего уведомление, в перечень стратегических предприятий и стратегических акционерных обществ либо о том, является ли налогоплательщик дочерним хозяйственным обществом предприятия или акционерного общества, включенных в такой перечень;\n\n4) информация о федеральном органе исполнительной власти либо государственной корпорации, осуществляющих выдачу предварительного согласия, предусмотренного абзацем вторым пункта 5 статьи 10516-3 настоящего Кодекса; (В редакции Федерального закона от 06.06.2019 № 125-ФЗ)\n\n5) наименование участника, являющегося материнской компанией международной группы компаний, государство (территория) ее налогового резидентства, регистрационный номер (номера), присвоенный материнской компании международной группы компаний в государстве (на территории) ее регистрации (инкорпорации), код (коды) материнской компании международной группы компаний в качестве налогоплательщика в государстве (на территории) ее регистрации (инкорпорации) (или их аналоги), адрес в государстве (на территории) регистрации (инкорпорации) материнской компании международной группы компаний (при наличии);\n\n6) наименование участника, являющегося уполномоченным участником международной группы компаний (при наличии), государство (территория) его налогового резидентства, регистрационный номер (номера), присвоенный уполномоченному участнику международной группы компаний в государстве (на территории) его регистрации (инкорпорации), код (коды) уполномоченного участника международной группы компаний в качестве налогоплательщика в государстве (на территории) его регистрации (инкорпорации) (или их аналоги), адрес в государстве (на территории) регистрации (инкорпорации) уполномоченного участника международной группы компаний (при наличии);\n\n7) основания, подтверждающие право участника международной группы компаний на представление странового отчета и (или) уведомления об участии в международной группе компаний в отношении всех участников этой группы, признаваемых налогоплательщиками в соответствии с настоящим Кодексом (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса);\n\n8) дата, являющаяся последним днем отчетного периода.\n\n6. При обнаружении налогоплательщиком в уведомлении об участии в международной группе компаний неполноты сведений, неточностей либо ошибок в его заполнении налогоплательщик вправе представить уточненное уведомление об участии в международной группе компаний.\n\nВ случае представления указанного уточненного уведомления до момента, когда налогоплательщик узнал об установлении федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, или территориальным налоговым органом факта отражения в уведомлении недостоверных сведений, такой налогоплательщик освобождается от ответственности, предусмотренной статьей 1299 настоящего Кодекса.\n\n7. Положения настоящей статьи не распространяются на налогоплательщиков, являющихся участниками международной группы компаний, общая сумма дохода (выручки) которой удовлетворяет условию, предусмотренному подпунктом 3 пункта 6 статьи 10516-3 настоящего Кодекса.","article_title":"Статья 105.16-2. Представление уведомлений об участии в международной группе компаний","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7da17fbf84aa1ef8c83c3ecd3069558d4e3083de18cc44df873ba82353be73bd"},{"code_id":"NK_RF","article_number":"105.16-3","version_date":"2000-07-31","article_text":"1. Налогоплательщики (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса), являющиеся участниками международной группы компаний, представляют страновые сведения в случаях, порядке и сроки, которые установлены настоящим Кодексом.\n\n2. Страновой отчет представляется материнской компанией международной группы компаний или уполномоченным участником международной группы компаний, если материнская компания международной группы компаний или уполномоченный участник международной группы компаний является российской организацией или иностранной организацией (иностранной структурой без образования юридического лица), добровольно признавшей себя налоговым резидентом Российской Федерации.\n\nСтрановой отчет представляется участником международной группы компаний, который является налогоплательщиком в соответствии с настоящим Кодексом (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса), по требованию федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, за исключением случаев, предусмотренных пунктом 6 настоящей статьи, в срок, установленный федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, который не может составлять менее трех месяцев со дня получения налогоплательщиком указанного требования. (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\nСтрановой отчет представляется материнской компанией международной группы компаний или уполномоченным участником международной группы компаний в срок не позднее двенадцати месяцев с даты окончания отчетного периода.\n\n3. Глобальная документация и национальная документация представляются участником международной группы компаний, который является налогоплательщиком в соответствии с настоящим Кодексом (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса).\n\nГлобальная документация представляется по требованию федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, в течение трех месяцев со дня получения такого требования. Глобальная документация может быть истребована у участника международной группы компаний, который является налогоплательщиком в соответствии с настоящим Кодексом (за исключением иностранных организаций, получающих только доходы, указанные в статье 309 настоящего Кодекса), не ранее чем по истечении двенадцати месяцев и не позднее чем по истечении тридцати шести месяцев с даты окончания отчетного периода, указанного в требовании. В случае, если указанное требование направляется в связи с запросом компетентного органа иностранного государства (территории), поступившим в соответствии с настоящим Кодексом и положениями международных договоров Российской Федерации, к нему прилагается копия такого запроса.\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, не вправе истребовать у налогоплательщика, являющегося участником международной группы компаний, глобальную документацию, ранее представленную по требованию федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, иным участником такой международной группы компаний за соответствующий отчетный период. Указанное ограничение не распространяется на случаи, если глобальная документация, представленная налогоплательщиком, была утрачена вследствие обстоятельств непреодолимой силы.\n\nНациональная документация представляется по требованию федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, в порядке и сроки, которые установлены статьями 10515 и 10517 настоящего Кодекса.\n\n4. Страновой отчет представляется по установленному формату только в электронной форме.\n\nФормат странового отчета, порядок его заполнения и представления в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nСтрановые сведения представляются на русском языке с отражением показателей в валюте Российской Федерации, если иное не предусмотрено настоящим пунктом. При этом у налогоплательщика остается право одновременно представить страновые сведения на иностранном языке.\n\nСтрановой отчет в отношении финансового года, в котором материнская компания международной группы компаний, по которой представляются страновые сведения, не признавалась налоговым резидентом Российской Федерации, может быть представлен на иностранном языке.\n\nЗначения стоимостных показателей глобальной документации и странового отчета могут указываться в валюте, в которой материнская компания международной группы компаний составляет консолидированную финансовую отчетность.\n\nЗначения стоимостных показателей контролируемых сделок, в отношении которых составляется национальная документация, могут указываться в валюте, в которой выражены такие сделки.\n\nДля целей исчисления значений стоимостных показателей глобальной документации и странового отчета пересчет валюты отчетности участников международной группы компаний, отличной от валюты отчетности материнской компании международной группы компаний, может осуществляться по правилам составления консолидированной финансовой отчетности материнской компании такой международной группы компаний. Информация об используемом курсе валюты приводится в пояснениях к глобальной документации и страновому отчету.\n\n5. Страновой отчет и глобальная документация, содержащие информацию, составляющую государственную тайну, и (или) информацию, прямо и (или) косвенно свидетельствующую о военно-техническом сотрудничестве с иностранными государствами, осуществляемом в соответствии с Федеральным законом от 19 июля 1998 года № 114-ФЗ \"О военно-техническом сотрудничестве Российской Федерации с иностранными государствами\", представляются в части, не содержащей информации, составляющей государственную тайну, и (или) информации, прямо и (или) косвенно свидетельствующей о военно-техническом сотрудничестве с иностранными государствами.\n\nВ случае, если страновой отчет содержит сведения в отношении участников международной группы компаний, включенных в соответствии с законодательством Российской Федерации в перечень стратегических предприятий и стратегических акционерных обществ, а также в отношении их дочерних хозяйственных обществ, информация, касающаяся деятельности таких участников, подлежит передаче компетентным органам иностранных государств (территорий) в соответствии со статьей 1425 настоящего Кодекса только при условии представления налогоплательщиком, представляющим страновой отчет, в отношении таких участников соответствующего предварительного согласия на передачу такой информации, выданного уполномоченным Правительством Российской Федерации федеральным органом исполнительной власти либо государственной корпорацией, осуществляющей полномочия по осуществлению прав собственника имущества указанных участников. (В редакции Федерального закона от 06.06.2019 № 125-ФЗ)\n\n6. Налогоплательщик, являющийся участником международной группы компаний и представивший (в отношении которого представлено) в соответствии с настоящим Кодексом в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, уведомление об участии в этой группе, вправе не представлять страновой отчет в следующих случаях:\n\n1) налогоплательщик является участником международной группы компаний, материнская компания международной группы компаний или уполномоченный участник международной группы компаний которой представляет страновой отчет в соответствии с пунктом 2 настоящей статьи;\n\n2) налогоплательщик является участником международной группы компаний, материнская компания международной группы компаний или уполномоченный участник международной группы компаний которой признается налоговым резидентом иностранного государства (территории), в отношении которого соблюдаются все следующие условия:\n\nзаконодательством такого государства (территории) установлена обязанность представлять в компет\n\nентные органы страновой отчет, содержащий информацию, аналогичную информации, предусмотренной пунктом 1 статьи 10516-6 настоящего Кодекса;\n\nтакое государство (территория) является участником международного договора Российской Федерации по международному автоматическому обмену страновыми отчетами на конец периода, указанного в абзаце третьем пункта 2 настоящей статьи для представления странового отчета за соответствующий отчетный период;\n\nтакое государство (территория) не включено в перечень государств (территорий), допускающих систематическое неисполнение обязательств по автоматическому обмену страновыми отчетами, утверждаемый федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов;\n\nтакое государство (территория) уведомлено соответствующим участником международной группы компаний об участнике международной группы компаний, на которого возложена обязанность по представлению странового отчета (при наличии в законодательстве такого государства (территории) требования о соответствующем уведомлении);\n\n3) налогоплательщик является участником международной группы компаний, общая сумма дохода (выручки) которой в соответствии с консолидированной финансовой отчетностью за финансовый год, составляющий двенадцать последовательных календарных месяцев, непосредственно предшествующих отчетному периоду, составляет или может составлять (в случае, если бы составлялась консолидированная финансовая отчетность):\n\nменее 50 миллиардов рублей - в случае, если материнская компания международной группы компаний признается налоговым резидентом Российской Федерации;\n\nменее величины общей суммы дохода (выручки), установленной законодательством иностранного государства (территории) для возникновения обязанности представления в компетентный орган такого иностранного государства (территории) странового отчета, содержащего информацию, аналогичную информации, предусмотренной пунктом 1 статьи 10516-6 настоящего Кодекса, - в случае, если материнская компания такой международной группы компаний признается налоговым резидентом соответствующего иностранного государства (территории). В случае, если материнская компания международной группы компаний или уполномоченный участник международной группы компаний составляет консолидированную финансовую отчетность в валюте, отличной от валюты Российской Федерации, соответствие условию величины общей суммы дохода (выручки), указанной в настоящем подпункте, определяется с применением среднего курса валюты при составлении консолидированной финансовой отчетности к рублю Российской Федерации, установленного Центральным банком Российской Федерации, за финансовый год, непосредственно предшествующий отчетному периоду.\n\n7. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, направляет налогоплательщику, являющемуся участником международной группы компаний, указанному в подпункте 2 пункта 6 настоящей статьи, требование о предоставлении странового отчета в срок, установленный федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, который не может составлять менее трех месяцев с даты получения налогоплательщиком указанного требования, в следующих случаях:\n\n1) при наличии у федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, информации, полученной от компетентных органов иностранных государств (территорий), о неисполнении материнской компанией международной группы компаний или уполномоченным участником международной группы компаний обязанности по представлению в компетентный орган странового отчета, установленной законодательством иностранного государства (территории);\n\n2) государство (территория), налоговым резидентом которого является материнская компания международной группы компаний или уполномоченный участник международной группы компаний, включено в перечень государств (территорий), допускающих систематическое неисполнение обязательств по автоматическому обмену страновыми отчетами, утверждаемый федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n8. Государство (территория) включается в перечень государств (территорий), допускающих систематическое неисполнение обязательств по автоматическому обмену страновыми отчетами, в случае неисполнения (приостановления исполнения) компетентным органом такого государства (территории) обязательств, предусмотренных международным договором Российской Федерации по автоматическому обмену страновыми отчетами, или по иным причинам необеспечения автоматического обмена страновыми отчетами с Российской Федерацией.\n\n9. Налогоплательщик, являющийся участником международной группы компаний, у которого обязанность по представлению странового отчета возникла на основании требования федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, направляемого в соответствии с пунктом 7 настоящей статьи, освобождается от ответственности, предусмотренной статьей 12910 настоящего Кодекса, за непредставление странового отчета в срок, установленный пунктом 3 настоящей статьи, в случае представления странового отчета в срок, установленный федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.","article_title":"Статья 105.16-3. Общие положения о представлении страновых сведений","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c03f5b0cc3aa2bbd8d244bf3a31c4793bfeb3af884a45c6ff7eaa19e1362ee17"},{"code_id":"NK_RF","article_number":"105.16-4","version_date":"2000-07-31","article_text":"1. Глобальная документация за отчетный период составляется в произвольной форме и должна содержать:\n\n1) информацию о структуре участия в капитале и об осуществлении контроля международной группы компаний, а также информацию о рынках товаров (работ, услуг), на которых участники международной группы компаний осуществляют свою основную деятельность (в виде схем);\n\n2) информацию о деятельности международной группы компаний:\n\nописание основных факторов, влияющих на финансовый результат международной группы компаний;\n\nописание последовательности движения поставок в отношении крупнейших по показателю дохода (выручки) международной группы компаний пяти товаров (работ, услуг), а также последовательности движения поставок иных товаров (работ, услуг) и другой деятельности, которые формируют более 5 процентов дохода (выручки) международной группы компаний за отчетный период, и основных географических мест расположения рынков товаров (работ, услуг), на которых реализуются (выполняются, оказываются) указанные товары (работы, услуги);\n\nперечень и краткое описание существенных договоров оказания услуг, заключенных между участниками международной группы компаний (за исключением договоров на осуществление научно-исследовательских и опытно-конструкторских работ), включая описание функциональных возможностей основных участников международной группы компаний, вовлеченных в оказание данных услуг, и подходов к ценообразованию в рамках оказываемых услуг внутри международной группы компаний;\n\nкраткий функциональный анализ участников международной группы компаний, оказывающих влияние на финансовый результат этой группы, в том числе описание основных выполняемых функций, используемых активов, принимаемых экономических (коммерческих) рисков;\n\nинформацию о существенных сделках, связанных с реструктуризацией деятельности в рамках международной группы компаний, приобретении и отчуждении активов в отчетном периоде;\n\n3) информацию о нематериальных активах международной группы компаний:\n\nописание стратегии развития международной группы компаний в отношении разработки, владения и использования нематериальных активов, в том числе размещения основных научно-исследовательских центров и расположения органов управления ими;\n\nописание нематериальных активов (групп нематериальных активов), оказывающих существенное влияние на методику ценообразования в сделках (операциях) между участниками международной группы компаний, и перечень участников международной группы компаний, владеющих такими активами;\n\nперечень существенных договоров, связанных с нематериальными активами, заключенных между участниками международной группы компаний;\n\nобщее описание методик ценообразования по сделкам между участниками международной группы компаний, связанным с разработкой, владением и использованием нематериальных активов;\n\nобщее описание сделок (операций) по передаче прав на нематериальные активы между участниками международной группы компаний в отчетном периоде с указанием таких участников и уровня вознаграждения, связанного с такой передачей;\n\n4) информацию о финансовой деятельности в международной группе компаний:\n\nкраткую информацию о системе финансирования международной группы компаний (включая информацию о финансировании, привлеченном от лиц, не являющихся участниками международной группы компаний);\n\nуказание участников международной группы компаний, которые выполняют основные функции финансирования в международной группе компаний, в том числе государств (территорий), являющихся местом регистрации таких участников и (или) местом их управления;\n\nобщее описание методик ценообразования между участниками международной группы компаний по сделкам, связанным с финансированием участников международной группы компаний;\n\n5) иную информацию:\n\nконсолидированную финансовую отчетность за последний отчетный период или при ее отсутствии иную консолидированную отчетность за последний отчетный период, подготовленную для управленческих, налоговых и иных целей;\n\nперечень и краткое описание соглашений о ценообразовании, налоговых разъяснений компетентных органов иностранных государств (территорий), в подготовке которых не участвовал федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, применяемых в сделках между участниками международной группы компаний и связанных с распределением доходов между государствами (территориями).\n\n2. При обнаружении налогоплательщиком в представленной глобальной документации неполноты сведений, неточностей либо ошибок в ее заполнении налогоплательщик вправе представить уточненную глобальную документацию.\n\n3. Положения настоящей статьи не распространяются на налогоплательщиков, являющихся участниками международной группы компаний, общая сумма дохода (выручки) которой удовлетворяет условию, предусмотренному подпунктом 3 пункта 6 статьи 10516-3 настоящего Кодекса.","article_title":"Статья 105.16-4. Глобальная документация","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0e048f1c7cec9264e8a2d4a8895b2b3c94bf7a3912cd955a4bbcdc4a3be9a539"},{"code_id":"NK_RF","article_number":"105.16-5","version_date":"2000-07-31","article_text":"1. Национальной документацией признается документация, составленная в произвольной форме участником международной группы компаний в отношении контролируемой сделки (группы однородных сделок), одной из сторон и (или) выгодоприобретателем которой является другой участник такой международной группы компаний, местом регистрации, либо местом жительства, либо местом налогового резидентства которого не является Российская Федерация, и содержащая информацию, предусмотренную пунктом 1 статьи 10515 настоящего Кодекса.\n\n2. В случае, если национальная документация предполагает раскрытие информации, представленной в отношении того же отчетного периода в соответствии со статьей 10516-4 настоящего Кодекса в составе глобальной документации, повторное представление информации не требуется при условии наличия в национальной документации указания на пункты глобальной документации, содержащие необходимую информацию.\n\n3. Налогоплательщик вправе представить иную информацию, подтверждающую, что коммерческие и (или) финансовые условия контролируемых сделок соответствуют тем, которые имели место в сопоставимых сделках, с учетом произведенных корректировок для обеспечения сопоставимости коммерческих и (или) финансовых условий сопоставляемых сделок, сторонами которых являются лица, не признаваемые взаимозависимыми, с условиями контролируемой сделки.\n\n4. При обнаружении налогоплательщиком в представленной национальной документации неполноты сведений, неточностей либо ошибок в ее заполнении налогоплательщик вправе представить уточненную национальную документацию.\n\n5. Положения настоящей статьи не распространяются на налогоплательщиков, являющихся участниками международной группы компаний, общая сумма дохода (выручки) которой удовлетворяет условию, предусмотренному подпунктом 3 пункта 6 статьи 10516-3 настоящего Кодекса.","article_title":"Статья 105.16-5. Национальная документация","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"72bdbbb39293480e7f19c527ea55c9e5fbeab28a5548071861331e141a36b74d"},{"code_id":"NK_RF","article_number":"105.16-6","version_date":"2000-07-31","article_text":"1. Страновой отчет должен содержать информацию:\n\n1) об общей сумме доходов (выручки) по сделкам за отчетный период, в том числе с разбивкой на сумму доходов (выручки) по сделкам с участниками этой международной группы компаний и сумму доходов (выручки) по сделкам с другими лицами, в том числе ассоциированными организациями;\n\n2) о сумме прибыли (убытка) до налогообложения за отчетный период;\n\n3) о сумме исчисленного налога на прибыль организаций (налога с дохода (прибыли) или его аналога) за отчетный период;\n\n4) о сумме уплаченного налога на прибыль организаций (налога с дохода (прибыли) или его аналога) в отчетном периоде;\n\n5) о размере капитала на дату окончания отчетного периода;\n\n6) о сумме накопленной прибыли на дату окончания отчетного периода;\n\n7) о численности работников за отчетный период;\n\n8) о величине материальных активов на дату окончания отчетного периода;\n\n9) идентификационные сведения о каждом участнике международной группы, в том числе с указанием государства (территории), в соответствии с правом которого такой участник учрежден, государства (территории) налогового резидентства и основных видов деятельности каждого участника международной группы компаний.\n\n2. Требования к составу информации, предусмотренной пунктом 1 настоящей статьи, определяются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в порядке заполнения странового отчета, предусмотренном пунктом 4 статьи 10516-3 настоящего Кодекса.\n\n3. Информация, предусмотренная подпунктами 1 - 8 пункта 1 настоящей статьи, отражается в обобщенном виде в отношении деятельности участников международной группы компаний, являющихся налоговыми резидентами и (или) постоянными представительствами в одном государстве (территории), без разделения информации по отдельным участникам международной группы компаний.\n\nИнформация, предусмотренная подпунктами 1 - 8 пункта 1 настоящей статьи, отражается на основании данных консолидированной финансовой отчетности, составляемой материнской компанией международной группы компаний в соответствии с Международными стандартами финансовой отчетности или иными международно признанными стандартами составления финансовой отчетности, либо на основании данных бухгалтерского и (или) налогового учета, формируемых исходя из правил, принятых в государстве (территории) налогового резидентства соответствующего участника международной группы компаний, либо на основании иной информации, обеспечивающей полноту и достоверность сведений странового отчета. При этом налогоплательщик также обеспечивает ежегодное последовательное использование одних и тех же источников информации для заполнения соответствующих показателей, а при их изменении раскрытие причин такого изменения.\n\nНалогоплательщик, являющийся участником международной группы компаний, вправе раскрыть методологию и принципы составления странового отчета, а также представить иную дополнительную информацию, которая содержит детальные сведения в отношении информации, представленной в обязательном порядке в соответствии с пунктом 1 настоящей статьи.\n\n4. При обнаружении налогоплательщиком в страновом отчете неполноты сведений, неточностей либо ошибок в его заполнении налогоплательщик вправе представить уточненный страновой отчет.\n\nВ случае представления уточненного странового отчета до момента, когда налогоплательщик узнал об установлении федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, или территориальным налоговым органом факта отражения в страновом отчете недостоверных сведений, такой налогоплательщик освобождается от ответственности, предусмотренной статьей 12910 настоящего Кодекса.","article_title":"Статья 105.16-6. Страновой отчет","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9e9514ef053b2be28d10df3817c7f17116cf6505148f3f34c4756e0282c38fc0"},{"code_id":"NK_RF","article_number":"105.16-7","version_date":"2000-07-31","article_text":"1. В случае, если хотя бы один участник международной группы компаний, более 50 процентов активов которой по состоянию на последнюю отчетную дату, предшествующую году совершения таким участником контролируемых сделок, находится на территории Российской Федерации, совершил сделки в области внешней торговли, которые признаются контролируемыми и предметом которых являются товары, входящие в состав одной или нескольких товарных групп, указанных в пункте 5 статьи 10514 настоящего Кодекса, материнская компания такой международной группы компаний или уполномоченный участник такой международной группы компаний, которые являются российской организацией либо иностранной организацией (иностранной структурой без образования юридического лица), добровольно признавшей себя налоговым резидентом Российской Федерации, обязаны представить в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, сведения из консолидированной финансовой отчетности такой международной группы компаний, финансовой отчетности участников такой международной группы компаний, совершивших такие сделки и (или) сделки по последующей реализации указанных товаров и (или) обеспечивавших совершение указанных сделок (в том числе путем оказания услуг по перевозке, хранению, упаковке, страхованию, финансированию, маркетингу), в порядке и сроки, которые установлены настоящей статьей.\n\n2. Сведения из консолидированной финансовой отчетности международной группы компаний, финансовой отчетности участников международной группы компаний, указанные в пункте 1 настоящей статьи, представляются в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в электронной форме по установленным форматам в срок не позднее двенадцати месяцев с даты окончания финансового года, в котором были совершены сделки, указанные в пункте 1 настоящей статьи.\n\n3. Форматы представления сведений из консолидированной финансовой отчетности международной группы компаний, финансовой отчетности участников международной группы компаний в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n4. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, вправе в порядке, определенном пунктом 2 статьи 931 настоящего Кодекса, истребовать у материнской компании международной группы компаний или уполномоченного участника международной группы компаний, которые являются российской организацией либо иностранной организацией (иностранной структурой без образования юридического лица), добровольно признавшей себя налоговым резидентом Российской Федерации, документы и (или) информацию о сделках, указанных в пункте 1 настоящей статьи, об участниках международной группы компаний, обеспечивавших совершение указанных сделок (в том числе путем оказания услуг по перевозке, хранению, упаковке, страхованию, финансированию, маркетингу).\n\n(Дополнение статьей - Федеральный закон от 27.11.2023 № 539-ФЗ)","article_title":"Статья 105.16-7. Обязанность по представлению сведений из консолидированной финансовой отчетности международной группы компаний и финансовой отчетности участников международной группы компаний","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"38ab9280ebac187e05682bbe8a2da9aed3f1d9ebf139b716bbe7a519337d4b94"},{"code_id":"NK_RF","article_number":"105.17","version_date":"2000-07-31","article_text":"1. Проверка полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами (далее в настоящей главе - п\n\nроверка) проводится федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по месту его нахождения.\n\nПроверка проводится на основании уведомления о контролируемых сделках или извещения территориального налогового органа, направленных в соответствии со статьей 10516 настоящего Кодекса, а также при выявлении контролируемой сделки в результате проведения федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, повторной выездной налоговой проверки в порядке контроля за деятельностью налогового органа, проводившего налоговую проверку, налоговый мониторинг. (В редакции федеральных законов от 04.11.2014 № 348-ФЗ, от 17.02.2021 № 6-ФЗ)\n\nРешение о проведении проверки не может быть принято в отношении совершенной налогоплательщиком в календарном году контролируемой сделки, по которой такой налогоплательщик обратился в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, с заявлением о заключении соглашения о ценообразовании для целей налогообложения за тот же календарный год в порядке, предусмотренном главой 146 настоящего Кодекса, в случае, если федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, не принято ни одно из решений, предусмотренных подпунктами 1 и 2 пункта 5 статьи 10522 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nПри проведении проверок федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, вправе проводить мероприятия налогового контроля, установленные статьями 95 - 97 настоящего Кодекса. При этом контроль соответствия цен, примененных в контролируемых сделках, рыночным ценам не может быть предметом выездных и камеральных проверок.\n\nВ случае представления налогоплательщиком уточненной налоговой декларации, в которой сумма налога, исчисленная в соответствии с пунктом 6 статьи 1053 настоящего Кодекса, отражена в меньшем размере (сумма убытка в большем размере), чем ранее заявленная, решение о проведении проверки может быть вынесено не позднее двух лет со дня представления указанной уточненной налоговой декларации. При этом проверка проводится только в отношении контролируемой сделки, по которой произведена корректировка в соответствии с пунктом 6 статьи 1053 настоящего Кодекса.\n\nВ случае представления налогоплательщиком заявления о заключении соглашения о ценообразовании для целей налогообложения в соответствии с пунктом 1 статьи 10519 настоящего Кодекса, по результатам рассмотрения которого федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, принято решение, предусмотренное подпунктом 2 пункта 5 статьи 10522 настоящего Кодекса, решение о проведении проверки в отношении контролируемой сделки, которая являлась предметом рассмотрения заявления налогоплательщика о заключении соглашения о ценообразовании для целей налогообложения, может быть вынесено не позднее двух лет со дня принятия решения, предусмотренного подпунктом 2 пункта 5 статьи 10522 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nТечение срока, предусмотренного абзацем третьим настоящего пункта, приостанавливается при получении федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, информации об обжаловании в судебном порядке решения, предусмотренного подпунктом 2 пункта 5 статьи 10522 настоящего Кодекса. Такое приостановление действует до дня вступления в законную силу соответствующего судебного акта. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, не вправе проводить две и более проверки в отношении одной контролируемой сделки (группы однородных сделок) за один и тот же календарный год, если иное не предусмотрено настоящим пунктом.\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, вправе проводить в отношении одной контролируемой сделки (группы однородных сделок) повторные проверки в случае представления налогоплательщиком уточненной налоговой декларации, в которой отражена сумма налога в меньшем размере (сумма убытка в большем размере), чем ранее заявленная в налоговой декларации, представленной в соответствии с пунктом 6 статьи 1053 настоящего Кодекса.\n\nВ случае, если у налогоплательщика, являющегося стороной контролируемой сделки (группы однородных сделок), в отношении указанной сделки (группы однородных сделок) за календарный год была осуществлена проверка в соответствии с настоящей статьей и по результатам такой проверки было установлено соответствие условий контролируемой сделки (группы однородных сделок) условиям сделок между лицами, не являющимися взаимозависимыми, в отношении указанной сделки (группы однородных сделок) не могут быть осуществлены проверки у налогоплательщиков, являющихся другими сторонами указанной сделки (группы однородных сделок).\n\nПри этом проведение проверки в отношении сделки, совершенной в налоговый период, не препятствует проведению выездных и (или) камеральных налоговых проверок, налогового мониторинга за этот же налоговый период.\n\n(Пункт в редакции Федерального закона от 08.06.2015 № 150-ФЗ)\n\nО принятии указанного решения федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, уведомляет налогоплательщика в течение трех дней со дня его принятия.\n\nОснования и порядок продления срока проведения проверки устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае необходимости получения информации от иностранных государственных органов, проведения экспертиз и (или) перевода на русский язык документов, представленных налогоплательщиком на иностранном языке, срок проведения проверки может быть продлен дополнительно на срок, не превышающий шесть месяцев, а в случае, если проверка была продлена для получения информации от иностранных государственных органов и в течение шести месяцев федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, не смог получить запрашиваемую информацию, срок продления указанной проверки может быть увеличен на три месяца.\n\nКопия решения о продлении срока проведения проверки направляется налогоплательщику в течение трех дней со дня его принятия.\n\nЕсли для определения сопоставимости коммерческих и (или) финансовых условий контролируемых сделок с условиями сопоставляемых сделок между лицами, не являющимися взаимозависимыми, налогоплательщик применил методы, указанные в пункте 1 статьи 1057 настоящего Кодекса, или их комбинацию, федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, при осуществлении налогового контроля в связи с осуществлением сделок между взаимозависимыми лицами применяет метод (комбинацию методов), примененный (примененную) налогоплательщиком.\n\nПрименение иного метода (комбинации методов) возможно в том случае, если федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, докажет, что метод (комбинация методов), примененный (примененная) налогоплательщиком, исходя из условий совершения контролируемой сделки не позволяет определить сопоставимость коммерческих и (или) финансовых условий контролируемой сделки с условиями сопоставляемых сделок между лицами, не являющимися взаимозависимыми.\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, не вправе применять в ходе налогового контроля в связи с совершением сделок иные методы, не предусмотренные настоящим разделом.\n\nНалогоплательщик, обратившийся в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, с заявлением о заключении соглашения о ценообразовании для целей налогообложения в отношении внешнеторговой сделки, хотя бы одна сторона которой является налоговым резидентом иностранного государства, с которым заключен договор (соглашение) об избежании двойного налогообложения, обязан обеспечивать в течение 10 лет сохранность данных бухгалтерского и налогового учета и других документов, необходимых для исчисления и уплаты налогов, указанных в пункте 4 статьи 1053 настоящего Кодекса, при исчислении которых учитывались доходы (расходы) по соответствующей сделке.\n\n(Дополнение пунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nИстребование документов в соответствии с настоящим пунктом производится в порядке, аналогичном порядку истребования документов, установленному статьей 931 настоящего Кодекса, и в сроки, установленные настоящим пунктом. (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\nИстребуемые в соответствии с настоящим пунктом документы (информация) представляются лицами, указанными в абзаце первом настоящего пункта, в течение 10 дней со дня получения соответствующего требования. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nЕсли истребуемые документы (информация) не могут быть представлены в установленный настоящим пунктом срок, федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, при получении от лица, у которого истребованы документы (информация), уведомления о невозможности представления в установленный срок документов (информации) и о сроке (при необходимости), в течение которого эти документы (информация) могут быть представлены, вправе продлить срок представления этих документов (информации). Указанное уведомление представляется в порядке, предусмотренном пунктом 3 статьи 93 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nСправка о проведенной проверке вручается лицу, в отношении которого проводилась такая проверка, или его представителю под расписку или передается иным способом, свидетельствующим о дате ее получения.\n\nВ случае, если налогоплательщик (его представитель) уклоняется от получения справки о проведенной проверке, указанная справка направляется налогоплательщику по почте заказным письмом.\n\nВ случае направления справки о проведенной проверке по почте заказным письмом датой ее вручения считается шестой день считая с даты отправки заказного письма.\n\nФорма акта проверки и требования к его составлению устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n10. Акт проверки подписывается должностными лицами, проводившими проверку, и лицом, в отношении которого проводилась такая проверка, или его представителем.\n\nОб отказе лица, в отношении которого проводилась проверка, или его представителя подписать акт проверки в этом акте делается соответствующая запись.\n\n12. Акт проверки в течение пяти дней с даты этого акта должен быть вручен лицу, в отношении которого проводилась проверка, или его представителю под расписку или передан иным способом, свидетельствующим о дате его получения указанным лицом (его представителем).\n\nВ случае, если лицо, в отношении которого проводилась проверка, или его представитель уклоняются от получения акта проверки, этот факт отражается в акте проверки и акт проверки направляется по почте заказным письмом по месту нахождения организации или месту жительства физического лица.\n\nВ случае направления акта проверки по почте заказным письмом датой вручения этого акта считается шестой день считая с даты отправки заказного письма.\n\n13. Лицо, в отношении которого проводилась проверка, или его представитель в случае несогласия с фактами, изложенными в акте проверки, а также с выводами и предложениями проверяющих вправе в течение 20 дней со дня получения акта представить в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, письменные возражения по указанному акту в целом или по его отдельным положениям. При этом указанное лицо вправе приложить к письменным возражениям или в согласованный срок передать в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, документы (их заверенные копии), подтверждающие обоснованность возражений.\n\n14. Рассмотрение акта, других материалов проверки и письменных возражений по акту, которые представлены налогоплательщиком, а также принятие решения по результатам проверки осуществляется в порядке, аналогичном порядку рассмотрения материалов налоговой проверки, предусмотренному статьей 101 настоящего Кодекса.\n\n15. Материалы и сведения, полученные федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, при осуществлении мероприятий налогового контроля в связи с совершением сделки между взаимозависимыми лицами, могут быть использованы при проведении проверки иных лиц, являющихся участниками этой же контролируемой сделки.","article_title":"Статья 105.17. Проверка федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a21f74519fa6e93f84f7f0ced54c657be7ab4f0df6bc174e112e6dd41c3e6ffc"},{"code_id":"NK_RF","article_number":"105.18","version_date":"2000-07-31","article_text":"1. Российскими организациями - налогоплательщиками, являющимися другими сторонами контролируемой сделки (далее - другая сторона сделки), при исчислении налогов, указанных в пункте 4 статьи 1053 настоящего Кодекса, могут быть применены цены, на основании которых федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, осуществлена корректировка налоговой базы и суммы налога (в случае доначисления налога по итогам проверки федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами исходя из оценки результатов сделки с учетом рыночных цен) либо на основании которых налогоплательщиками осуществлена корректировка налоговой базы и суммы налога (убытка) (в случае, предусмотренном пунктом 6 статьи 1053 настоящего Кодекса).\n\nПрименение таких цен в целях настоящего Кодекса признается симметричной корректировкой.\n\nСимметричные корректировки осуществляются в порядке, установленном настоящей статьей.\n\n2. Другая сторона сделки вправе применять симметричную корректировку в случае:\n\n1) если решение федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, о привлечении (об отказе в привлечении) к ответственности за совершение налогового правонарушения, предусматривающее доначисление налога или уменьшение суммы убытка, исполнено налогоплательщиком, в отношении которого было вынесено такое решение. Право на симметричные корректировки в указанном случае возникает со дня получения уведомления о возможности симметричных корректировок, выдача (направление) которого осуществляется федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в порядке, предусмотренном пунктами 5 - 9 настоящей статьи;\n\n2) если налогоплател\n\nьщик, самостоятельно осуществивший корректировку налоговой базы и суммы налога (убытка) в соответствии с пунктом 6 статьи 1053 настоящего Кодекса, представил налоговую декларацию, в которой отражена соответствующая корректировка, и погасил сумму недоимки, возникшей в результате такой корректировки (при ее наличии).\n\n3. Для целей применения симметричных корректировок не осуществляются корректировки регистров налогового учета и первичных документов. Симметричные корректировки отражаются:\n\n1) в случае, если право на такие корректировки возникло у другой стороны сделки в соответствии с подпунктом 1 пункта 2 настоящей статьи, - в налоговых декларациях по налогам, указанным в пункте 4 статьи 1053 настоящего Кодекса, представленных по итогам налогового периода, в котором другой стороной сделки получено уведомление о возможности симметричных корректировок;\n\n2) в случае, если право на такие корректировки возникло у другой стороны сделки в соответствии с подпунктом 2 пункта 2 настоящей статьи, - в налоговых декларациях по налогам, указанным в пункте 4 статьи 1053 настоящего Кодекса, представленных по итогам налогового периода, за который налогоплательщик самостоятельно осуществил корректировку налоговой базы и суммы налога (убытка) в соответствии с пунктом 6 статьи 1053 настоящего Кодекса.\n\nФорма уведомления о возможности симметричных корректировок и порядок его выдачи утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае принятия федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по итогам проверки полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами решения о привлечении (об отказе в привлечении) к ответственности за совершение налогового правонарушения, предусматривающего доначисление налога или уменьшение суммы убытка, он уведомляет другую сторону сделки о возможности симметричных корректировок путем выдачи или направления по почте заказным письмом либо в электронной форме по телекоммуникационным каналам связи соответствующего уведомления в течение одного месяца со дня исполнения такого решения.\n\nТечение срока выдачи или направления другой стороне сделки уведомления о возможности симметричных корректировок приостанавливается при получении федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, информации об обжаловании в судебном порядке решения о привлечении (об отказе в привлечении) к ответственности за совершение налогового правонарушения, предусматривающего доначисление налога или уменьшение суммы убытка, на основе которого проводятся симметричные корректировки. Такое приостановление действует до дня вступления в силу соответствующего судебного акта.\n\nВ случае нарушения федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, срока выдачи или направления другой стороне сделки уведомления о возможности симметричных корректировок, предусмотренного настоящим пунктом, на сумму налога, подлежащую возврату налогоплательщику по результатам симметричной корректировки, начисляются проценты, подлежащие уплате указанному налогоплательщику за каждый календарный день начиная со дня окончания срока, установленного настоящим пунктом для выдачи или направления налогоплательщику соответствующего уведомления. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nПроцентная ставка принимается равной ставке рефинансирования Центрального банка Российской Федерации, действовавшей в период нарушения срока направления соответствующего уведомления федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nК заявлению о выдаче уведомления о возможности симметричных корректировок должны быть приложены копии документов, подтверждающих информацию о вынесенном в отношении налогоплательщика решении о привлечении (об отказе в привлечении) к ответственности за совершение налогового правонарушения, предусматривающем доначисление налога или уменьшение суммы убытка, и его исполнении.\n\n1) выдать уведомление о возможности симметричных корректировок;\n\n2) отказать в выдаче уведомления о возможности симметричных корректировок;\n\n3) информировать о приостановлении срока выдачи уведомления о возможности симметричных корректировок в случае обжалования решения о привлечении (об отказе в привлечении) к ответственности за совершение налогового правонарушения, предусматривающего доначисление налога или уменьшение суммы убытка, на основании которого проводятся симметричные корректировки.\n\n1) несоблюдения порядка подачи заявления о выдаче уведомления о возможности симметричных корректировок;\n\n2) неподтверждения указанной в заявлении информации;\n\n3) представления налогоплательщиком в период рассмотрения заявления о выдаче уведомления о возможности симметричных корректировок уточненной налоговой декларации, в которой изменены налоговая база и сумма налога (убытка).\n\nО принятии решения, предусмотренного подпунктом 2 или 3 пункта 7 настоящей статьи, другой стороне сделки, обратившейся с заявлением о выдаче уведомления о возможности симметричных корректировок, сообщается не позднее одного дня со дня принятия соответствующего решения.\n\nФорма решений, указанных в пункте 7 настоящей статьи, и порядок их принятия утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nВ случае, если другой стороной сделки не представлены документы (сведения), указанные в настоящем пункте (либо представлены документы, содержащие недостоверные сведения), и (или) не выполнены условия, указанные в подпункте 2 пункта 2 настоящей статьи, сумма налога (убытка) подлежит восстановлению, при этом сумма налога подлежит уплате в бюджет в установленном порядке с взысканием с другой стороны сделки соответствующих сумм налоговых санкций и пеней.\n\nВеличина, на которую изменен размер налоговой базы (убытка) в результате симметричной корректировки, произведенной по основаниям, предусмотренным подпунктами 1 и 2 пункта 2 настоящей статьи, должна соответствовать величине, на которую изменен размер налоговой базы (убытка) в случаях, предусмотренных пунктами 5 и 6 статьи 1053 настоящего Кодекса.\n\nВ случае, если налогоплательщик, являющийся другой стороной контролируемой сделки, осуществил корректировку в соответствии с налоговой декларацией, представленной налогоплательщиком в соответствии с пунктом 6 статьи 1053 настоящего Кодекса, а впоследствии этим налогоплательщиком была представлена уточненная налоговая декларация с уменьшением налоговой базы и (или) суммы налога, налогоплательщик, являющийся другой стороной контролируемой сделки, должен произвести соответствующую обратную корректировку.\n\nОбратные корректировки производятся другой стороной сделки на основании уведомления о необходимости обратных корректировок, полученного от налогового органа по месту учета другой стороны сделки, в течение одного месяца с даты получения указанного уведомления. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nФорма уведомления о необходимости обратных корректировок и порядок его выдачи утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nК уведомлению о необходимости обратных корректировок в связи с изменением (отменой) или признанием недействительным решения о привлечении (об отказе в привлечении) к ответственности за совершение налогового правонарушения, предусматривающего доначисление налога или уменьшение суммы убытка, прилагается расчет обратных корректировок, составленный в произвольной форме, а также копия соответствующего судебного акта, отменяющего (изменяющего) или признающего недействительным такое решение или соответствующие судебные акты.\n\nК уведомлению о необходимости обратных корректировок в связи с проведением налогоплательщиком самостоятельно корректировок в соответствии с пунктом 6 статьи 1053 настоящего Кодекса прилагается расчет обратных корректировок, составленный в произвольной форме. В уведомлении указывается дата подачи уточненной налоговой декларации.\n\nНалоговый орган производит возврат суммы денежных средств налогоплательщику, который является стороной контролируемой сделки и в отношении которого было вынесено решение о привлечении (об отказе в привлечении) к ответственности за совершение налогового правонарушения, предусматривающее доначисление налога или уменьшение суммы убытка, или который осуществил самостоятельно корректировку в соответствии с пунктом 6 статьи 1053 настоящего Кодекса, только после проведения обратных корректировок и уплаты налога налогоплательщиком, являющимся другой стороной контролируемой сделки. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Статья в редакции Федерального закона от 08.06.2015 № 150-ФЗ)","article_title":"Статья 105.18. Симметричные корректировки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a50cddedf2a50be856f0e634ec4eeaa2bdf1105b6ccd885984efeb59843e9a53"},{"code_id":"NK_RF","article_number":"105.18-1","version_date":"2000-07-31","article_text":"1. Для целей применения корректировок по результатам взаимосогласительной процедуры в соответствии с международным договором Российской Федерации по вопросам налогообложения не осуществляются корректировки регистров налогового учета и первичных документов.\n\nТакие корректировки отражаются в налоговых декларациях по налогам, указанным в подпунктах 1 и 2 пункта 4 статьи 1053 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 29.09.2019 № 325-ФЗ)","article_title":"Статья 105.18-1. Корректировки по результатам взаимосогласительной процедуры в соответствии с международным договором Российской Федерации по вопросам налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f0a7f54ac7d44b7d87cd9e5efcc97e4ef8fef2472946bf28b89add78f6554396"},{"code_id":"NK_RF","article_number":"105.19","version_date":"2000-07-31","article_text":"1) виды и (или) перечни контролируемых сделок и товаров (работ, услуг), в отношении которых заключается соглашение;\n\n2) порядок определения цен и (или) описание и порядок применения методик (формул) ценообразования для целей налогообложения;\n\n3) перечень источников информации, используемых при определении соответствия цен, примененных в сделках, условиям соглашения;\n\n4) срок действия соглашения;\n\n5) перечень, порядок и сроки представления документов, подтверждающих исполнение условий соглашения о ценообразовании.","article_title":"Статья 105.19. Общие положения о соглашении о ценообразовании для целей налогообложения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b09490b44b98f9e0ac497723518bc78aaec2d0e46fc2d56c29061a4f961468bf"},{"code_id":"NK_RF","article_number":"105.2","version_date":"2000-07-31","article_text":"1. В целях настоящего Кодекса доля участия лица в организации определяется в виде суммы выраженных в процентах долей прямого и косвенного участия этого лица в организации.\n\n2. Долей прямого участия лица в организации признается непосредственно принадлежащая такому лицу доля голосующих акций этой организации или непосредственно принадлежащая такому лицу доля в уставном (складочном) капитале (фонде) этой организации, а в случае невозможности определения таких долей - непосредственно принадлежащая такому лицу, являющемуся участником этой организации, доля, определяемая пропорционально общему количеству участников этой организации.\n\nВ случае, если акции (доли в уставном (складочном) капитале (фонде) организации входят в состав активов инвестиционного фонда или негосударственного пенсионного фонда, созданных в соответствии с законодательством Российской Федерации, доля прямого участия в такой организации определяется пропорционально доле участия (доле вносимого имущества во вклад) лиц в таком инвестиционном фонде (негосударственном пенсионном фонде), а в случае невозможности определения такой доли - пропорционально количеству лиц.\n\n3. Долей косвенного участия лица в другой организации признается доля, определяемая в следующем порядке:\n\n1) определяются все последовательности участия лица в организации через прямое участие каждой предыдущей организации (иного лица) в каждой последующей организации соответствующей последовательности;\n\n2) определяются доли прямого участия каждой предыдущей организации (иного лица) в каждой последующей организации соответствующей последовательности;\n\n3) определяются доли косвенного участия одной организации (иного лица) в другой организации каждой последовательности, при этом доля косвенного участия определяется как произведение долей прямого участия первых двух организаций (иных лиц) в последовательности, а при наличии последующего участия путем умножения получившегося произведения на долю следующего прямого участия в последовательности и каждого следующего получившегося произведения на каждую долю следующего прямого участия до последней организации в последовательности;\n\n4) при наличии нескольких последовательностей участия суммируются все доли косвенного участия лица в организации, определенные в соответствии с подпунктом 3 настоящего пункта.\n\n4. При определении доли участия лица в организации не учитывается участие, реализованное посредством владения ценными бумагами, приобретенными в рамках договора репо, заключенного в соответствии с Федеральным законом \"О рынке ценных бумаг\", или операции, признаваемой операцией РЕПО в соответствии с законодательством иностранного государства. При этом в целях определения доли прямого и (или) косвенного участия такие ценные бумаги учитываются у лица, которое является продавцом ценных бумаг по первой части РЕПО, за исключением случаев, когда ценные бумаги, проданные продавцом по первой части РЕПО, были им получены по другой операции РЕПО или операции займа ценными бумагами.\n\nВ случае неисполнения или исполнения не в полном объеме второй части РЕПО определение доли участия лица в организации осуществляется без учета особенностей, установленных настоящим пунктом.\n\n5. При определении доли участия лица в организации не учитывается участие, реализованное посредством владения ценными бумагами, полученными в рамках договора займа ценными бумагами, заключенного в соответствии с законодательством Российской Федерации или законодательством иностранного государства. При этом в целях определения доли прямого и (или) косвенного участия такие ценные бумаги учитываются у лица, которое является кредитором (представляет ценные бумаги в заем), за исключением случаев, когда ценные бумаги, переданные в рамках договора займа ценными бумагами, были получены кредитором по другой операции займа ценными бумагами или операции РЕПО.\n\nВ случае неисполнения или исполнения не в полном объеме обязательств по возврату ценных бумаг по операциям займа ценными бумагами определение доли участия лица в организации осуществляется без учета особенностей, установленных настоящим пунктом.\n\n6. При определении доли участия лица в организации учитывается также участие, осуществляемое с использованием иностранной структуры без образования юридического лица, в случае, если такое лицо признается контролирующим лицом этой структуры. При этом доля такого участия с использованием иностранной структуры без образования юридического лица определяется в порядке, аналогичном порядку определения доли косвенного участия лица в организации, осуществляемого с использованием другой организации, установленному пунктом 3 настоящей статьи, с учетом особенностей, установленных абзацем вторым настоящего пункта.\n\nДля определения доли косвенного участия лица в организации при наличии более одного контролирующего лица иностранной структуры без образования юридического лица доля каждого из контролирующих лиц в такой организации определяется пропорционально вкладу каждого контролирующего лица в имущество, переданное этой структуре. В случае невозможности определения размера вклада в имущество, переданное такой структуре, доли всех контролирующих лиц в целях определения доли их участия в организации признаются равными, а их размер определяется исходя из количества контролирующих лиц такой структуры.\n\nПравила, предусмотренные настоящим пунктом, применяются также при определении доли участия в организации, осуществляемого с использованием иностранного юридического лица, для которого в соответствии с его личным законом не предусмотрено участие (отсутствует уставный капитал или фонд).\n\n7. Дополнительные обстоятельства при определении доли участия лица в организации учитываются в судебном порядке.\n\n(Статья в редакции Федерального закона от 15.02.2016 № 32-ФЗ)","article_title":"Статья 105.2. Порядок определения доли участия лица в организации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4e2ddf4f2ceb776100a0fc68878a3639a6ee96bf1243d908736930e3c53f96f1"},{"code_id":"NK_RF","article_number":"105.20","version_date":"2000-07-31","article_text":"1. Сторонами соглашения о ценообразовании являются налогоплательщик и федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в лице его руководителя (заместителя руководителя), если иное не предусмотрено пунктом 2 настоящей статьи.\n\nПредусмотренное настоящим пунктом соглашение о ценообразовании основывается на взаимном соглашении федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, и уполномоченного органа исполнительной власти иностранного государства, достигнутом по результатам проведенной с учетом положений главы 203 настоящего Кодекса взаимосогласительной процедуры, предусмотренной международным договором Российской Федерации по вопросам налогообложения. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nПри заключении соглашения о ценообразовании, изменении условий и проведении проверки исполнения условий соглашения о ценообразовании в порядке, установленном соответственно статьями 10522, 10523 настоящего Кодекса, общие интересы группы налогоплательщиков может представлять одна организация из группы налогоплательщиков, полномочия которой подтверждаются доверенностями, выданными в порядке, установленном законодательством Российской Федерации.","article_title":"Статья 105.20. Стороны соглашения о ценообразовании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b44a225990c0d59c39b73b696010a6277a7ab9c94ef0dcda68c1056edbc601cc"},{"code_id":"NK_RF","article_number":"105.21","version_date":"2000-07-31","article_text":"1. Соглашение о ценообразовании может быть заключено по одной либо нескольким сделкам (группе однородных сделок), имеющим один и тот же предмет, в отношении следующих периодов или их совокупности:\n\n1) в отношении календарного года, в котором впервые представлено заявление о заключении соглашения о ценообразовании;\n\n2) в отношении двух календарных лет, предшествующих периоду, указанному в подпункте 1 настоящего пункта;\n\n3) в отношении двух календарных лет, следующих за периодом, указанным в подпункте 1 настоящего пункта.\n\n(Пункт в редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n2. Налогоплательщик при соблюд\n\nении им всех условий соглашения о ценообразовании вправе обратиться в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, с заявлением о продлении срока действия соглашения о ценообразовании.\n\n3. Соглашение о ценообразовании может быть продлено по соглашению сторон не более чем на два года в порядке, предусмотренном статьей 10522 настоящего Кодекса.\n\n4. Соглашение о ценообразовании вступает в силу с 1 января календарного года, следующего за годом, в котором оно было подписано, если иное не предусмотрено непосредственно указанным соглашением.","article_title":"Статья 105.21. Срок действия соглашения о ценообразовании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f7ffb4e714e503c5c0abba7944e0e3f4fce18afe63437e38a2ec3ea48b8301c2"},{"code_id":"NK_RF","article_number":"105.22","version_date":"2000-07-31","article_text":"1. К заявлению налогоплательщика о заключении соглашения о ценообразовании, представленному налогоплательщиком в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, прилагаются:\n\n1) проект соглашения о ценообразовании;\n\n2) документы о деятельности налогоплательщика, связанной с контролируемыми сделками, а также о контролируемых сделках, в отношении которых налогоплательщиком предлагается заключить соглашение о ценообразовании;\n\n3) копии учредительных документов налогоплательщика;\n\n4) (Подпункт утратил силу - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n5) (Подпункт утратил силу - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n6) бухгалтерская (финансовая) отчетность налогоплательщика за последний отчетный период; (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n61) документы, подтверждающие совершение налогоплательщиком сделок, которые признаются контролируемыми сделками в соответствии с пунктом 1 статьи 10514 настоящего Кодекса и предметом которых являются товары, входящие в состав одной или нескольких товарных групп, указанных в пункте 5 статьи 10514 настоящего Кодекса, и сумма доходов (расходов) по которым за календарный год составляет не менее 2 миллиардов рублей. Положения настоящего подпункта не распространяются на налогоплательщиков, отнесенных в соответствии со статьей 83 настоящего Кодекса к категории крупнейших налогоплательщиков; (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n7) документ, подтверждающий уплату заявителем государственной пошлины за рассмотрение федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, заявления о заключении соглашения о ценообразовании;\n\n8) иные документы, содержащие информацию, имеющую значение при заключении соглашения о ценообразовании.\n\n2. Документы, перечисленные в пункте 1 настоящей статьи, представляются в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в произвольной форме, если иная форма не установлена законодательством Российской Федерации.\n\n3. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, вправе запрашивать у налогоплательщика другие, не предусмотренные пунктом 1 настоящей статьи документы, необходимые для целей соглашения о ценообразовании.\n\nУказанные документы должны быть представлены налогоплательщиком в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в течение 10 дней со дня получения соответствующего запроса федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nЕсли запрашиваемые документы не могут быть представлены в установленный настоящим пунктом срок, федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, при получении от налогоплательщика, у которого запрошены документы, уведомления о невозможности представления в установленный срок документов и о сроке (при необходимости), в течение которого эти документы могут быть представлены, вправе продлить срок представления этих документов. Указанное уведомление представляется в порядке, предусмотренном пунктом 3 статьи 93 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n31. Налогоплательщик вместе с заявлением о заключении соглашения о ценообразовании, представляемым в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в соответствии с пунктом 2 статьи 10520 настоящего Кодекса, представляет сведения о подаче контрагентом налогоплательщика в уполномоченный орган исполнительной власти иностранного государства, налоговым резидентом которого он является, аналогичного заявления в целях заключения такого соглашения, если иное не предусмотрено настоящим пунктом.\n\nВ случае, если на дату представления налогоплательщиком в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, заявления о заключении соглашения о ценообразовании в соответствии с пунктом 2 статьи 10520 настоящего Кодекса в уполномоченный орган исполнительной власти иностранного государства, налоговым резидентом которого является контрагент налогоплательщика, не подано аналогичное заявление в целях заключения соглашения о ценообразовании, после подачи контрагентом налогоплательщика указанного заявления налогоплательщик должен в письменной форме сообщить в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, о подаче контрагентом налогоплательщика указанного заявления. Соответствующие сведения представляются налогоплательщиком в срок не позднее шести месяцев со дня представления им заявления о заключении соглашения о ценообразовании в соответствии с пунктом 2 статьи 10520 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n4. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, рассматривает заявление и другие документы, представленные налогоплательщиком в соответствии с пунктами 1 - 3 настоящей статьи, в срок не более шести месяцев со дня получения заявления, если иное не предусмотрено настоящим пунктом.\n\nЗаявление и другие документы, представленные налогоплательщиком в целях заключения соглашения о ценообразовании в соответствии с пунктом 2 статьи 10520 настоящего Кодекса, рассматриваются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в срок не более 24 месяцев со дня получения заявления, а в предусмотренном пунктом 31 настоящей статьи случае - со дня получения от налогоплательщика сведений о подаче его контрагентом заявления в уполномоченный орган исполнительной власти иностранного государства, налоговым резидентом которого он является, в целях заключения такого соглашения о ценообразовании.\n\nСрок рассмотрения заявления и других документов, представленных налогоплательщиком в соответствии с пунктом 1 настоящей статьи в целях заключения соглашения о ценообразовании, предусмотренного пунктом 2 статьи 10520 настоящего Кодекса, приостанавливается на период представления уполномоченным органом исполнительной власти иностранного государства документов и (или) информации в соответствии с запросом, направленным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в рамках проведения с учетом положений главы 203 настоящего Кодекса взаимосогласительной процедуры, предусмотренной международным договором Российской Федерации по вопросам налогообложения.\n\nСрок рассмотрения представленных налогоплательщиком документов может быть продлен до девяти месяцев в случае, указанном в абзаце первом настоящего пункта, а в случае, предусмотренном абзацем вторым настоящего пункта, - до 27 месяцев.\n\nОснования и порядок продления срока рассмотрения представленных налогоплательщиком документов устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Пункт в редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\n5. По результатам рассмотрения документов, представленных налогоплательщиком в соответствии с пунктами 1 - 3 настоящей статьи, федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, принимается одно из следующих решений:\n\n1) решение о заключении соглашения о ценообразовании;\n\n2) мотивированное решение об отказе от заключения такого соглашения;\n\n3) решение о необходимости доработки проекта соглашения, в котором федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, предлагает налогоплательщику доработать в соответствии с требованиями настоящего Кодекса и повторно представить проект соглашения о ценообразовании и документы, указанные в подпункте 2 пункта 1 настоящей статьи.\n\n1) государственная пошлина, предусмотренная подпунктом 133 пункта 1 статьи 33333 настоящего Кодекса, не взимается; (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\n2) федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, решение принимается в течение трех месяцев.\n\n1) непредставление или представление не в полном объеме документов, предусмотренных пунктом 1 настоящей статьи;\n\n2) неуплата или неполная уплата государственной пошлины;\n\n3) мотивированный вывод о том, что в результате применения предложенного налогоплательщиком в проекте соглашения о ценообразовании порядка определения цен и (или) методов ценообразования не будет обеспечиваться исполнение положений пункта 1 статьи 1053 настоящего Кодекса;\n\n4) недостижение взаимного соглашения с уполномоченным органом исполнительной власти иностранного государства в целях заключения предусмотренного пунктом 2 статьи 10520 настоящего Кодекса соглашения о ценообразовании; (Дополнение подпунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n5) непредставление документов (сведений), предусмотренных пунктами 3 и 31 настоящей статьи, в порядке и сроки, которые установлены настоящей статьей; (Дополнение подпунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n6) несогласие налогоплательщика с решением о необходимости доработки проекта соглашения о ценообразовании (в том числе в форме непредставления доработанного проекта соглашения о ценообразовании в срок, установленный пунктом 61 настоящей статьи); (Дополнение подпунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n7) несогласие налогоплательщика с решением о заключении соглашения о ценообразовании, которое выразилось в отказе налогоплательщика от подписания соглашения о ценообразовании (в том числе в форме неявки налогоплательщика (его представителя) для подписания соглашения о ценообразовании в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов). (Дополнение подпунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)","article_title":"Статья 105.22. Порядок заключения соглашения о ценообразовании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9417a72edb8ff8a40e0e5a718d1954c6c09ecf112555c1e7812fad62532a5437"},{"code_id":"NK_RF","article_number":"105.23","version_date":"2000-07-31","article_text":"1. Проверка исполнения налогоплательщиком соглашения о ценообразовании осуществляется федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, в соответствии с порядком, предусмотренным главой 145 настоящего Кодекса.","article_title":"Статья 105.23. Проверка исполнения соглашения о ценообразовании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d772f8f0ac88e113ef0261f0bec312d2c0a9846368e32d3c49ea60996409464f"},{"code_id":"NK_RF","article_number":"105.24","version_date":"2000-07-31","article_text":"1. Соглашение о ценообразовании прекращается по истечении срока его действия либо может быть прекращено до истечения такого срока в случаях, предусмотренных настоящей статьей.\n\n2. Действие соглашения о ценообразовании прекращается досрочно по решению руководителя (заместителя руководителя) федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, при нарушении налогоплательщиком соглашения о ценообразовании в течение срока его действия, повлекшем за собой неполную уплату налогов и выявленном в ходе проведения проверки в порядке, предусмотренном главой 145 настоящего Кодекса.\n\nСоглашение о ценообразовании также может быть расторгнуто досрочно по соглашению сторон или по решению суда.\n\n3. Решение федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, о прекращении соглашения о ценообразовании, вручается налогоплательщику (его представителю) под расписку или передается иным способом, свидетельствующим о дате его получения налогоплательщиком (его представителем), либо направляется налогоплательщику по почте заказным письмом в течение пяти дней со дня принятия соответствующего решения.\n\nРешение о прекращении соглашения о ценообразовании, направленное налогоплательщику по почте заказным письмом, считается полученным по истечении шести дней со дня направления такого заказного письма.\n\nКопия указанного решения в те же сроки направляется в налоговый орган по месту учета этого налогоплательщика в качестве крупнейшего налогоплательщика.\n\n4. Решение федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, о прекращении соглашения о ценообразовании может быть обжаловано налогоплательщиком в арбитражный суд в порядке, установленном арбитражным процессуальным законодательством Российской Федерации.\n\n5. Уплата суммы налога, пеней и штрафа осуществляется только в случае, если прекращение соглашения о ценообразовании вследствие неисполнения (нарушения) его условий повлекло занижение суммы налога.","article_title":"Статья 105.24. Порядок прекращения соглашения о ценообразовании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8591c6a3e4b35f65b057332fb487abbc98142beea3f56c69138e4b8b79c5a122"},{"code_id":"NK_RF","article_number":"105.25","version_date":"2000-07-31","article_text":"1. Условия соглашения о ценообразовании остаются неизменными в случае изменения законодательства о налогах и сборах в части регулирования отношений, возникающих при заключении соглашения о ценообразовании, внесении в него изменений и прекращении его действия.\n\n2. В случае иных изменений законодательства Российской Федерации о налогах и сборах и законодательства Российской Федерации о таможенном деле, влияющих на деятельность налогоплательщика, стороны соглашения имеют право внести в текст соглашения о ценообразовании соответствующие изменения.\n\n(Дополнение разделом - Федеральный закон от 04.11.2014 № 348-ФЗ)","article_title":"Статья 105.25. Стабильность условий соглашения о ценообразовании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2fe66a028c16fb3ff376d044cf4411ab89d8bb01f93de952d387ea24496bf8cf"},{"code_id":"NK_RF","article_number":"105.26","version_date":"2000-07-31","article_text":"1. Предметом налогового мониторинга являются правильность исчисления (удержания), полнота и своевременность уплаты (перечисления) налогов, сборов, страховых взносов, обязанность по уплате (перечислению) которых в соответствии с настоящим Кодексом возложена на налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) - организацию (далее в настоящем разделе - организация).\n\nПредметом налогового мониторинга в отношении участника консолидированной группы налогоплательщиков также является правильность определения полученных им доходов и осуществленных расходов для целей исчисления и уплаты налога на прибыль организаций по консолидированной группе налогоплательщиков.\n\nПри этом не является предметом налогового мониторинга в отношении ответственного участника консолидированной группы налогоплательщиков правильность определения другими участниками консолидированной группы налогоплательщиков полученных доходов и осуществленных расходов для целей исчисления и уплаты налога на прибыль организаций по консолидированной группе налогоплательщиков.\n\nПредметом налогового мониторинга в отношении организации, признаваемой налогоплательщиком - участником соглашения о защите и поощрении капиталовложений, также является проверка фактических затрат, по которым Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\" предусмотрено предоставление мер государственной поддержки. (Дополнение абзацем -\n\nФедеральный закон от 28.06.2022 № 225-ФЗ)\n\n(Пункт в редакции Федерального закона от 03.07.2016 № 240-ФЗ)\n\n2. Налоговый мониторинг проводится налоговым органом на основании решения о проведении налогового мониторинга.\n\n1) совокупная сумма налога на добавленную стоимость, акцизов, налога на доходы физических лиц, налога на прибыль организаций, налога на добычу полезных ископаемых и страховых взносов, подлежащих уплате (перечислению) в бюджетную систему Российской Федерации за календарный год, предшествующий году, в котором представляется заявление о проведении налогового мониторинга, без учета налогов, подлежащих уплате в связи с перемещением товаров через таможенную границу Евразийского экономического союза, составляет не менее 80 миллионов рублей. (В редакции  федеральных законов от 03.07.2016 № 240-ФЗ, от 29.12.2020 № 470-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nПри определении совокупной суммы налогов, указанных в настоящем подпункте, учитываются налоги, обязанность по уплате (перечислению) которых возложена на организацию как на налогоплательщика и налогового агента. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 240-ФЗ) (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\nАбзац; (Дополнение абзацем - Федеральный закон от 03.07.2016 № 240-ФЗ) (Утратил силу - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\n2) суммарный объем полученных доходов по данным годовой бухгалтерской (финансовой) отчетности организации за календарный год, предшествующий году, в котором представляется заявление о проведении налогового мониторинга, составляет не менее 800 миллионов рублей; (В редакции  федеральных законов от 29.12.2020 № 470-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n3) совокупная стоимость активов по данным бухгалтерской (финансовой) отчетности организации на 31 декабря календарного года, предшествующего году, в котором представляется заявление о проведении налогового мониторинга, составляет не менее 800 миллионов рублей. (В редакции  федеральных законов от 29.12.2020 № 470-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 01.05.2016 № 130-ФЗ) (Утратил силу  - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 28.06.2022 № 225-ФЗ) (Утратил силу  - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 18.03.2023 № 64-ФЗ) (Утратил силу  - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nДля организации - резидента особой экономической зоны выполнение условий, установленных настоящим пунктом, не является обязательным. (Дополнение абзацем - Федеральный закон от 02.11.2023 № 522-ФЗ)\n\n31. Выполнение условий, установленных пунктом 3 настоящей статьи, не является обязательным для следующих организаций:\n\n1) организации, в отношении которых проводится налоговый мониторинг;\n\n2) организации, имеющие статус резидентов территории опережающего развития в соответствии с Федеральным законом от 29 декабря 2014 года № 473-ФЗ \"О территориях опережающего развития в Российской Федерации\", свободного порта Владивосток в соответствии с Федеральным законом от 13 июля 2015 года № 212-ФЗ \"О свободном порте Владивосток\", Арктической зоны Российской Федерации в соответствии с Федеральным законом от 13 июля 2020 года № 193-ФЗ \"О государственной поддержке предпринимательской деятельности в Арктической зоне Российской Федерации\";\n\n3) организации, признаваемые налогоплательщиками - участниками соглашения о защите и поощрении капиталовложений;\n\n4) организации, являющиеся участниками промышленного кластера, соответствующего требованиям к промышленным кластерам, установленным Правительством Российской Федерации;\n\n5) организации - резиденты особой экономической зоны;\n\n6) организации - бывшие участники консолидированной группы налогоплательщиков;\n\n7) организации, если одна из таких организаций прямо и (или) косвенно участвует в другой организации и доля такого участия составляет 50 процентов и более и если эти организации вместе отвечают следующим критериям:\n\nсовокупная сумма налога на добавленную стоимость, акцизов, налога на доходы физических лиц, налога на прибыль организаций, налога на добычу полезных ископаемых и страховых взносов, подлежащих уплате (перечислению) в бюджетную систему Российской Федерации всеми этими организациями за календарный год, предшествующий году, в котором представляется заявление о проведении налогового мониторинга, без учета налогов, подлежащих уплате в связи с перемещением товаров через таможенную границу Евразийского экономического союза, составляет не менее 1 миллиарда рублей. При определении указанной совокупной суммы налогов учитываются налоги, обязанность по уплате (перечислению) которых возложена на организацию как на налогоплательщика и налогового агента;\n\nсуммарный объем полученных доходов по данным годовых бухгалтерских (финансовых) отчетностей этих организаций за календарный год, предшествующий году, в котором представляется заявление о проведении налогового мониторинга, составляет не менее 10 миллиардов рублей;\n\nсовокупная стоимость активов по данным бухгалтерских (финансовых) отчетностей этих организаций на 31 декабря календарного года, предшествующего году, в котором представляется заявление о проведении налогового мониторинга, составляет не менее 10 миллиардов рублей;\n\n8) организации, являющиеся операторами лотерей в соответствии с Федеральным законом от 11 ноября 2003 года № 138-ФЗ \"О лотереях\";\n\n9) организации, признаваемые государственным или муниципальным учреждением.\n\n(Дополнение пунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nВ случае представления в календарном году, за который налоговый мониторинг не проводится, менее чем за три месяца до окончания срока проведения налогового мониторинга уточненной налоговой декларации (уточненного расчета) за налоговый (отчетный) период года, за который проводится или проведен налоговый мониторинг, срок проведения налогового мониторинга по решению руководителя (заместителя руководителя) налогового органа продлевается не более чем на три месяца. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\nВ случае представления в календарном году, за который налоговый мониторинг не проводится, менее чем за шесть месяцев до окончания срока проведения налогового мониторинга уточненной налоговой декларации по налогу на добавленную стоимость (акцизу), в которой сумма налога заявлена к возмещению, за налоговый период года, за который проводится или проведен налоговый мониторинг, срок проведения налогового мониторинга по решению руководителя (заместителя руководителя) налогового органа продлевается не более чем на шесть месяцев. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\nРешение о продлении срока проведения налогового мониторинга принимается руководителем (заместителем руководителя) налогового органа до окончания срока, указанного в абзаце первом настоящего пункта. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\nВ случае продления срока проведения налогового мониторинга налоговый орган направляет организации решение о продлении срока проведения налогового мониторинга в течение пяти дней со дня принятия такого решения. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\nВ случае представления налоговой декларации (расчета) или уточненной налоговой декларации (уточненного расчета) за налоговый (отчетный) период года, за который проводится (проведен) налоговый мониторинг, такие налоговая декларация (расчет) или уточненная налоговая декларация (уточненный расчет) проверяется в рамках проведения налогового мониторинга, дата окончания проведения которого наступает не ранее чем через три месяца со дня представления соответствующей налоговой декларации (расчета). (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\n1) сроки и порядок представления налоговому органу документов (информации), связанных с исчислением (удержанием), уплатой (перечислением) налогов, сборов, страховых взносов, в электронной форме по телекоммуникационным каналам связи и (или) порядок предоставления доступа к таким документам (информации) через информационные системы организации по выбору такой организации;\n\n2) порядок ознакомления должностных лиц налогового органа с подлинниками документов, указанных в подпункте 1 настоящего пункта;\n\n3) время доступа к указанным в подпункте 1 настоящего пункта документам (информации) в течение срока проведения налогового мониторинга за соответствующий период и следующих трех лет со дня окончания срока его проведения (в случае предоставления доступа к таким документам (информации) налоговому органу через информационные системы организации). (В редакции  Федерального закона от 28.06.2022 № 225-ФЗ)\n\nОрганизация, признаваемая налогоплательщиком - участником соглашения о защите и поощрении капиталовложений, в течение срока проведения в отношении указанной организации налогового мониторинга представляет налоговому органу документы (информацию) в электронной форме по телекоммуникационным каналам связи или через свои информационные системы предоставляет доступ к документам (информации), относящимся к фактическому осуществлению затрат, по которым Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\" предусмотрено предоставление мер государственной поддержки. При этом документы (информация) или доступ к документам (информации), относящиеся к осуществлению таких затрат за период со дня заключения соглашения о защите и поощрении капиталовложений до 1 января года, на который приходится первый период, за который проводится налоговый мониторинг, представляются в течение срока проведения налогового мониторинга за первый период, за который проводится налоговый мониторинг; (Дополнение абзацем - Федеральный закон от 28.06.2022 № 225-ФЗ)\n\n4) состав и структура раскрытия показателей регистров бухгалтерского и налогового учета, используемых в информационных системах организации, а также сведения о системе внутреннего контроля организации за совершаемыми фактами хозяйственной жизни и правильностью исчисления (удержания), полнотой и своевременностью уплаты (перечисления) налогов, сборов, страховых взносов.\n\nФорма и требования к регламенту информационного взаимодействия, порядок внесения изменений (дополнений) в регламент информационного взаимодействия, требования к информационным системам организации, в том числе к порядку получения и обработки документов, используемых налоговыми органами при реализации своих полномочий в отношениях, регулируемых законодательством о налогах и сборах, формат документов, к которым предоставляется доступ налоговому органу, и порядок получения доступа к таким информационным системам утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Пункт в редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\nПрименяемая организацией система внутреннего контроля должна соответствовать требованиям к организации системы внутреннего контроля, установленным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 03.07.2016 № 240-ФЗ)","article_title":"Статья 105.26. Общие положения о налоговом мониторинге","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8973bd27f788543bdb6da9c5104e57c821b4f4b0bc8661c43c8fa06fce9f5ef8"},{"code_id":"NK_RF","article_number":"105.27","version_date":"2000-07-31","article_text":"Организация, в соответствии со статьей 83 настоящего Кодекса отнесенная к категории крупнейших налогоплательщиков, представляет заявление о проведении налогового мониторинга в налоговый орган по месту ее учета в качестве крупнейшего налогоплательщика.\n\nФорма заявления о проведении налогового мониторинга утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n1) регламент информационного взаимодействия; (В редакции Федерального закона от 03.07.2016 № 240-ФЗ)\n\n2) информация об организациях, о физических лицах, которые прямо и (или) косвенно участвуют в организации, представляющей заявление о проведении налогового мониторинга, и при этом доля такого участия составляет более 25 процентов;\n\n3) учетная политика для целей налогообложения организации, действующая в календарном году, в котором представлено заявление о проведении налогового мониторинга, включающая информацию о порядке отражения организацией в регистрах бухгалтерского и налогового учета доходов и расходов, объектов налогообложения и налоговой базы, сведения о регистрах бухгалтерского учета, об аналитических регистрах налогового учета; (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\n4) внутренние документы, регламентирующие систему внутреннего контроля организации. (Дополнение подпунктом - Федеральный закон от 03.07.2016 № 240-ФЗ)\n\nВ случае отзыва заявления о проведении налогового мониторинга такое заявление не считается поданным.\n\n1) решение о проведении налогового мониторинга;\n\n2) решение об отказе в проведении налогового мониторинга.\n\n1) непредставление или представление не в полном объеме организацией документов (информации) в соответствии с пунктом 2 настоящей статьи;\n\n2) несоблюдение организацией условий, предусмотренных пунктом 3 статьи 10526 настоящего Кодекса;\n\n3) несоответствие регламента информационного взаимодействия установленным форме и требованиям к регламенту информационного взаимодействия;\n\n4) несоответствие применяемой организацией системы внутреннего контроля установленным требованиям к организации системы внутреннего контроля. (Дополнение подпунктом - Федеральный закон от 03.07.2016 № 240-ФЗ)","article_title":"Статья 105.27. Порядок представления заявления о проведении налогового мониторинга, принятия решения о проведении (об отказе в проведении) налогового мониторинга","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"035b0b94d04b7dd72f45053d9f006b4c8a371979ff4ddcda697becd8d8582a21"},{"code_id":"NK_RF","article_number":"105.28","version_date":"2000-07-31","article_text":"1. Налоговый мониторинг прекращается досрочно в следующих случаях:\n\n1) неисполнение организацией регламента информационного взаимодействия, которое стало препятствием для проведения налогового мониторинга;\n\n2) выявление налоговым органом факта представления организацией недостоверной информации в ходе проведения налогового мониторинга;\n\n3) систематическое (два раза и более) непредставление или несвоевременное представление налоговому органу в ходе проведения налогового мониторинга документов (информации), пояснений в порядке, предусмотренном статьей 10529 настоящего Кодекса; (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\n4) государственная регистрация прекращения организации в результате ликвидации, реорганизации или исключения из единого государственного реестра юридических лиц. (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\n11. Налоговый орган уведомляет в электронной форме организацию о наличии основания для досрочного прекращения налогового мониторинга в течение десяти дней со дня установления обстоятельств,\n\nпредусмотренных пунктом 1 настоящей статьи.\n\nВ случае возможности устранения обстоятельств, являющихся основанием для досрочного прекращения налогового мониторинга, организация в течение десяти дней со дня получения уведомления, указанного в абзаце первом настоящего пункта, принимает меры по устранению указанных обстоятельств и уведомляет налоговый орган об этом либо представляет пояснения и документы (при наличии), подтверждающие отсутствие оснований для досрочного прекращения налогового мониторинга. Пояснения и прилагаемые к ним документы (при наличии) представляются в налоговый орган в электронной форме по телекоммуникационным каналам связи и (или) посредством предоставления доступа к таким документам через информационные системы организации в случае получения к ним доступа налогового органа.\n\n(Дополнение пунктом - Федеральный закон от 29.12.2020 № 470-ФЗ)","article_title":"Статья 105.28. Порядок досрочного прекращения налогового мониторинга","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"19594ad3946900fb071e093be340d1ac93ae61e218886036f83b2131e4487b07"},{"code_id":"NK_RF","article_number":"105.29","version_date":"2000-07-31","article_text":"1. Налоговый мониторинг проводится уполномоченными должностными лицами налогового органа в соответствии с их служебными обязанностями по месту нахождения налогового органа.\n\nВ случае, если после рассмотрения представленных организацией пояснений либо при их отсутствии налоговый орган установит факт, свидетельствующий о неправильном исчислении (удержании), неполной или несвоевременной уплате (перечислении) налогов, сборов, страховых взносов, налоговый орган обязан составить мотивированное мнение в порядке, предусмотренном статьей 10530 настоящего Кодекса, с учетом положений настоящей статьи.  (В редакции федеральных законов от 03.07.2016 № 243-ФЗ, от 29.12.2020 № 470-ФЗ)\n\nВ случае, если после рассмотрения представленных организацией, признаваемой налогоплательщиком - участником соглашения о защите и поощрении капиталовложений, пояснений либо в случае их отсутствия налоговый орган установит факт, свидетельствующий об искажении размеров фактических затрат, по которым Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\" предусмотрено предоставление мер государственной поддержки, налоговый орган обязан составить мотивированное мнение в порядке, предусмотренном статьей 10530 настоящего Кодекса, с учетом положений настоящей статьи. (Дополнение абзацем - Федеральный закон от 28.06.2022 № 225-ФЗ)\n\n21. В случае установления налоговым органом факта, свидетельствующего о неправильном исчислении (удержании), неполной и (или) несвоевременной уплате (перечислении) налогов, сборов, страховых взносов, налоговый орган в течение десяти дней направляет организации в электронной форме уведомление о наличии оснований для составления мотивированного мнения в порядке, предусмотренном статьей 10530 настоящего Кодекса.\n\nПри проведении налогового мониторинга в отношении организации, признаваемой налогоплательщиком - участником соглашения о защите и поощрении капиталовложений, в случае установления налоговым органом факта, свидетельствующего о неправильном определении размеров фактических затрат, по которым Федеральным законом от 1 апреля 2020 года № 69-ФЗ \"О защите и поощрении капиталовложений в Российской Федерации\" предусмотрено предоставление мер государственной поддержки, налоговый орган также в течение десяти дней направляет организации в электронной форме уведомление о наличии оснований для составления мотивированного мнения в порядке, предусмотренном статьей 10530 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nВ уведомлении о наличии оснований для составления мотивированного мнения указываются документально подтвержденные факты, свидетельствующие о неправильном исчислении (удержании), неполной или несвоевременной уплате (перечислении) организацией налогов, сборов, страховых взносов или об искажении организацией, признаваемой налогоплательщиком - участником соглашения о защите и поощрении капиталовложений, размеров фактических затрат, по которым Федеральным законом от 1 апреля 2020 года № 69-ФЗ \"О защите и поощрении капиталовложений в Российской Федерации\" предусмотрено предоставление мер государственной поддержки, выявленные в ходе налогового мониторинга, а также выводы и предложения налогового органа по устранению выявленных нарушений. (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nОрганизация в течение пятнадцати дней со дня получения уведомления о наличии оснований для составления мотивированного мнения по инициативе налогового органа вправе представить в налоговый орган необходимые пояснения или внести соответствующие исправления, сообщив об этом налоговому органу в электронной форме по телекоммуникационным каналам связи и (или) через информационные системы организации, к которым предоставлен доступ налоговому органу.\n\nЕсли выявленные налоговым органом факты с учетом представленных организацией пояснений (сообщения) либо при отсутствии пояснений (сообщения) организации свидетельствуют о неправильном исчислении (удержании), неполной или несвоевременной уплате (перечислении) налогов, сборов, страховых взносов, налоговый орган обязан составить мотивированное мнение в порядке, предусмотренном статьей 10530 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\nПри проведении налогового мониторинга в отношении организации, признаваемой налогоплательщиком - участником соглашения о защите и поощрении капиталовложений, налоговый орган также вправе истребовать у организации необходимые документы (информацию), пояснения, связанные с фактическим осуществлением затрат, по которым Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\" предусмотрено предоставление мер государственной поддержки, в том числе в течение срока проведения налогового мониторинга за первый период, за который проводится налоговый мониторинг, в части затрат, осуществленных со дня заключения соглашения о защите и поощрении капиталовложений до 1 января года, на который приходится первый период, за который проводится налоговый мониторинг. (Дополнение абзацем - Федеральный закон от 28.06.2022 № 225-ФЗ)\n\nПредставление документов на бумажном носителе производится в виде заверенных организацией копий. Не допускается требование нотариального удостоверения копий документов, представляемых в налоговый орган (должностному лицу), если иное не предусмотрено законодательством Российской Федерации.\n\nВ случае, если истребуемые у организации документы составлены в электронной форме по установленным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, форматам, организация вправе направить их в налоговый орган в электронной форме по телекоммуникационным каналам связи или через информационные системы организации, к которым предоставлен доступ налоговому органу. При этом такие документы должны быть заверены усиленной квалифицированной электронной подписью организации (ее представителя). (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\nПорядок направления требования о представлении документов (информации), пояснений и представления документов (информации), пояснений по требованию налогового органа в электронной форме по телекоммуникационным каналам связи или через информационные системы организации, к которым предоставлен доступ налоговому органу, устанавливается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\nИстребуемые документы, составленные на бумажном носителе, могут быть представлены в налоговый орган в электронной форме в виде электронных образов документов (документов на бумажном носителе, преобразованных в электронную форму путем сканирования с сохранением их реквизитов). Истребуемые информация или пояснения могут быть представлены в налоговый орган в электронной форме в виде электронных образов документов. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\nЭлектронные образы документов представляются в налоговый орган по форматам, утвержденным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по телекоммуникационным каналам связи либо через информационные системы организации, к которым предоставлен доступ налоговому органу, и должны быть заверены усиленной квалифицированной электронной подписью организации (ее представителя). (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\nВ случае, если организация не имеет возможности представить истребуемые документы (информацию), пояснения в течение установленного настоящим пунктом срока, эта организация в течение дня, следующего за днем получения требования о представлении документов (информации), пояснений, уведомляет в электронной форме должностных лиц налогового органа, проводящих налоговый мониторинг, о невозможности представления в указанный срок документов (информации), пояснений с указанием причин, по которым истребуемые документы (информация), пояснения не могут быть представлены в установленный срок, и о сроках, в течение которых организация может представить истребуемые документы (информацию), пояснения. (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\nУказанное в абзаце втором настоящего пункта уведомление представляется в электронной форме по телекоммуникационным каналам связи либо через информационные системы организации, к которым предоставлен доступ налоговому органу. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 240-ФЗ) (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\nРуководитель (заместитель руководителя) налогового органа вправе на основании указанного уведомления в течение двух дней со дня его получения продлить сроки представления организацией документов (информации), пояснений или отказать в продлении сроков, о чем выносится отдельное решение.","article_title":"Статья 105.29. Порядок проведения налогового мониторинга","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"000844ecc4ce48ad1d5664e68fe7a2257335a6bc4666c3d8d4c81c1b7abde3e9"},{"code_id":"NK_RF","article_number":"105.3","version_date":"2000-07-31","article_text":"1. В случае, если в сделках между взаимозависимыми лицами создаются или устанавливаются коммерческие или финансовые условия, отличные от тех, которые имели бы место в сделках, признаваемых в соответствии с настоящим разделом сопоставимыми, между лицами, не являющимися взаимозависимыми, то любые доходы (прибыль, выручка), которые могли бы быть получены одним из этих лиц, но вследствие указанного отличия не были им получены, учитываются для целей налогообложения у этого лица.\n\nУчет для целей налогообложения доходов (прибыли, выручки) в соответствии с настоящим пунктом производится в случае, если это не приводит к уменьшению суммы налога, подлежащего уплате в бюджетную систему Российской Федерации, или увеличению суммы убытка, определяемого в соответствии с главой 25 настоящего Кодекса. Положения настоящего абзаца не применяются в случаях, если налогоплательщик применяет симметричную корректировку в соответствии с настоящим разделом, в случаях, предусмотренных соглашением о ценообразовании для целей налогообложения, заключенным в соответствии с пунктом 2 или абзацем первым пункта 3 статьи 10520 настоящего Кодекса, или по результатам взаимосогласительной процедуры в соответствии с международным договором Российской Федерации по вопросам налогообложения. (В редакции федеральных законов от 08.06.2015 № 150-ФЗ, от 28.12.2017 № 436-ФЗ, от 29.09.2019 № 325-ФЗ)\n\nДля целей настоящего Кодекса цены, применяемые в сделках, сторонами которых являются лица, не признаваемые взаимозависимыми, а также доходы (прибыль, выручка), получаемые лицами, являющимися сторонами таких сделок, признаются рыночными.\n\n2. Определение в целях налогообложения доходов (прибыли, выручки) взаимозависимых лиц, являющихся сторонами сделки, которые могли бы быть получены этими лицами, но не были получены вследствие отличия коммерческих и (или) финансовых условий указанной сделки от коммерческих и (или) финансовых условий такой же сделки, сторонами которой являются лица, не признаваемые взаимозависимыми, производится федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, с применением методов, установленных главой 143 настоящего Кодекса.\n\nНалогоплательщик вправе самостоятельно применить для целей налогообложения цену, отличающуюся от цены, примененной в указанной сделке, в случае, если цена, фактически примененная в указанной сделке, не соответствует рыночной цене.\n\n1) налога на прибыль организаций, за исключением части налога на прибыль организаций, исчисляемой в отношении прибыли контролируемых иностранных компаний; (В редакции Федерального закона от 28.12.2017 № 436-ФЗ)\n\n2) налога на доходы физических лиц, уплачиваемого в соответствии со статьей 227 настоящего Кодекса;\n\n3) налога на добычу полезных ископаемых (в случае, если одна из сторон сделки является налогоплательщиком указанного налога и предметом сделки является добытое полезное ископаемое, признаваемое для налогоплательщика объектом налогообложения налогом на добычу полезных ископаемых, при добыче которых налогообложение производится по налоговой ставке, установленной в процентах);\n\n4) налога на добавленную стоимость (в случае, если одной из сторон сделки является организация (индивидуальный предприниматель), не являющаяся (не являющийся) налогоплательщиком налога на добавленную стоимость или освобожденная (освобожденный) от исполнения обязанностей налогоплательщика по налогу на добавленную стоимость);\n\n5) налога на дополнительный доход от добычи углеводородного сырья. (Дополнение подпунктом - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nПри этом указанные в настоящем пункте корректировки могут производиться:\n\nорганизациями одновременно с представлением налоговой декларации по налогу на прибыль организаций за соответствующий налоговый период либо, если организация не является налогоплательщиком налога на прибыль организаций, - в сроки, установленные для представления налоговой декларации по налогу на прибыль организаций;\n\nфизическими лицами одновременно с представлением налоговой декларации по налогу на доходы физических лиц.\n\nКорректировки по налогу на добав\n\nленную стоимость и налогу на добычу полезных ископаемых в случаях, предусмотренных пунктом 4 настоящей статьи, отражаются в уточненных налоговых декларациях по каждому налоговому периоду, в котором произошло отклонение цен, представляемых одновременно с налоговой декларацией по налогу на прибыль организаций (налогу на доходы физических лиц).\n\nВ случае применения налогоплательщиком по договору, указанному в пункте 11 статьи 261 настоящего Кодекса, цен (процентных ставок), не соответствующих рыночным ценам (процентным ставкам), если указанное несоответствие повлекло занижение суммы налога на прибыль организаций или завышение суммы убытка, определяемого в соответствии с главой 25 настоящего Кодекса, налогоплательщик вправе самостоятельно произвести корректировку налоговой базы и суммы налога (убытка) по истечении календарного года, в котором доходы по такой сделке признаны в составе доходов в соответствии с абзацами пятым - шестнадцатым пункта 6 статьи 271 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\nСумма недоимки, выявленной налогоплательщиком самостоятельно по результатам произведенной в соответствии с настоящим пунктом корректировки, должна быть погашена в срок не позднее даты уплаты налога на прибыль организаций (налога на доходы физических лиц) за соответствующий налоговый период. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nДатой получения лицом, не являющимся налоговым резидентом Российской Федерации, дохода, указанного в абзаце первом настоящего пункта, признается последний день календарного года, в котором совершена сделка между взаимозависимыми лицами, стороной которой является указанное лицо.\n\nЕсли иное не установлено настоящей статьей, положения настоящего пункта не применяются в случае, если лицо, не являющееся налоговым резидентом Российской Федерации, вернуло указанный в абзаце первом настоящего пункта доход, полученный в результате корректировки налоговой базы по налогам, указанным в пункте 4 настоящей статьи, в соответствии с пунктом 6 настоящей статьи, налогоплательщику, осуществившему такую корректировку, путем перечисления суммы денежных средств, соответствующей размеру такой корректировки, на счет налогоплательщика в банке, находящемся на территории Российской Федерации, не позднее установленного настоящим Кодексом срока уплаты соответствующего налога за налоговый период, в котором совершена сделка между взаимозависимыми лицами, сторонами которой они являются.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n1) возврат указанного дохода в размере суммы такой корректировки осуществлен путем перечисления суммы денежных средств на счет налогоплательщика в банке, находящемся на территории Российской Федерации, до вынесения федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, решения о проведении проверки полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами;\n\n2) налогоплательщиком при определении налоговой базы по налогу на прибыль организаций (налогу на доходы физических лиц) учтены доходы в виде процентов за пользование денежными средствами лицом, не являющимся налоговым резидентом Российской Федерации, рассчитываемые по ставке, равной одной трехсотой ключевой ставки Центрального банка Российской Федерации, установленной на день получения указанного в абзаце первом пункта 61 настоящей статьи дохода, за каждый день пользования денежными средствами таким лицом считая с даты получения указанного дохода до даты, прямо предшествующей дню возврата ему такого дохода (включительно). (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)","article_title":"Статья 105.3. Общие положения о налогообложении в сделках между взаимозависимыми лицами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13026a735e45c8fc465607c16107d1e0397037996f8f5b445f904d9fae460154"},{"code_id":"NK_RF","article_number":"105.30","version_date":"2000-07-31","article_text":"Мотивированное мнение подписывается руководителем (заместителем руководителя) налогового органа.\n\nФорма и требования к составлению мотивированного мнения устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nПри проведении налогового мониторинга в отношении организации, признаваемой налогоплательщиком - участником соглашения о защите и поощрении капиталовложений, мотивированное мнение отражает позицию налогового органа также по вопросам правильности определения размеров фактических затрат, по которым Федеральным законом \"О защите и поощрении капиталовложений в Российской Федерации\" предусмотрено предоставление мер государственной поддержки. (Дополнение абзацем - Федеральный закон от 28.06.2022 № 225-ФЗ)\n\nУказанное мотивированное мнение может быть составлено в течение срока проведения налогового мониторинга. (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\nФорма и формат, в соответствии с которыми составляется запрос о предоставлении мотивированного мнения, а также требования к составлению такого запроса устанавливаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\n1) описание деловой цели, основных условий, в том числе прав и обязанностей сторон, сроков и условий осуществления платежей по совершенной или планируемой сделке (операции) или совокупности взаимосвязанных сделок (операций), а также по иным совершенным фактам хозяйственной жизни организации;\n\n2) информацию о деятельности контрагентов, иных лиц и выполняемых ими функциях по совершенной или планируемой сделке (операции) или совокупности взаимосвязанных сделок (операций), а также по иным совершенным фактам хозяйственной жизни организации с указанием государств и территорий, налоговыми резидентами которых они являются, и иную значимую для порядка исчисления (удержания) и уплаты (перечисления) налогов и сборов информацию по совершенной или планируемой сделке (операции) или совокупности взаимосвязанных сделок (операций), а также по иным совершенным фактам хозяйственной жизни организации;\n\n3) позицию организации по вопросам порядка исчисления (удержания) и уплаты (перечисления) налогов и сборов в отношении совершенной или планируемой сделки (операции) или совокупности взаимосвязанных сделок (операций), а также по иным совершенным фактам хозяйственной жизни организации.\n\n(Дополнение пунктом - Федеральный закон от 01.05.2016 № 130-ФЗ)\n\nЗапрос о предоставлении мотивированного мнения в отношении сделки (операции) или совокупности взаимосвязанных сделок (операций), а также иных фактов хозяйственной жизни может быть направлен организацией не позднее 1 июля года, следующего за периодом, в котором они были совершены.\n\nПри рассмотрении запроса о предоставлении мотивированного мнения налоговый орган вправе истребовать у организации, направившей запрос, документы (информацию), необходимые для подготовки мотивированного мнения, в порядке, установленном статьей 10529 настоящего Кодекса.\n\n(Дополнение пунктом - Федеральный закон от 01.05.2016 № 130-ФЗ)\n\nФорма и формат заявления об отзыве запроса о предоставлении мотивированного мнения утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nОтзыв запроса о предоставлении мотивированного мнения не лишает организацию, направившую соответствующий запрос, права на повторное обращение с запросом о предоставлении мотивированного мнения по тем же обстоятельствам.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nНалоговый орган, рассматривающий запрос о предоставлении мотивированного мнения, принимает решение об оставлении указанного запроса без рассмотрения в течение пяти дней со дня его получения или заявления об отзыве указанного запроса.\n\nФорма и формат решения об оставлении запроса о предоставлении мотивированного мнения без рассмотрения утверждаются федеральным органом исполнительной власти, уполномоченн\n\nым по контролю и надзору в области налогов и сборов.\n\nРешение об оставлении запроса о предоставлении мотивированного мнения без рассмотрения направляется организации в электронной форме по телекоммуникационным каналам связи или через информационные системы организации, к которым предоставлен доступ налоговому органу, в течение трех дней со дня принятия указанного решения.\n\nОставление запроса о предоставлении мотивированного мнения без рассмотрения не препятствует повторному обращению организации с указанным запросом в срок, установленный пунктом 42 настоящей статьи.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nСрок направления мотивированного мнения по запросу организации может быть продлен налоговым органом на один месяц для истребования у этой организации или у иных лиц документов (информации), необходимых для подготовки мотивированного мнения.\n\nО продлении срока направления мотивированного мнения налоговый орган сообщает организации в электронной форме в течение трех дней со дня принятия соответствующего решения. (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\nПри необходимости получения от Министерства финансов Российской Федерации, финансовых органов субъектов Российской Федерации, муниципальных образований, федеральной территории \"Сириус\" разъяснений по вопросам применения соответственно законодательства Российской Федерации о налогах и сборах, законодательства субъектов Российской Федерации о налогах и сборах, нормативных правовых актов муниципальных образований о местных налогах и сборах, нормативных правовых актов представительного органа федеральной территории \"Сириус\" о местных налогах и сборах в целях подготовки мотивированного мнения течение срока направления мотивированного мнения по запросу организации приостанавливается на время, необходимое для получения таких разъяснений, но не более чем на три месяца, о чем уведомляется организация с указанием органа, разъяснения которого необходимы для подготовки мотивированного мнения. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nОрганизация уведомляет налоговый орган, которым составлено мотивированное мнение в отношении планируемых сделок (операций) или совокупности взаимосвязанных сделок (операций), о начале совершения (об отказе от совершения) таких сделок (операций) не позднее месяца со дня начала их совершения (отказа от их совершения). (Дополнение абзацем - Федеральный закон от 01.05.2016 № 130-ФЗ) (В редакции Федерального закона от 29.12.2020 № 470-ФЗ)\n\nУказанное в настоящем пункте уведомление и прилагаемые к нему документы (при их наличии), подтверждающие выполнение указанного мотивированного мнения, представляются в налоговый орган в электронной форме по телекоммуникационным каналам связи либо через информационные системы организации, к которым предоставлен доступ налоговому органу. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\nОрганизация выполняет мотивированное мнение путем учета изложенной в нем позиции налогового органа в налоговом учете, налоговых декларациях (расчетах) (уточненных налоговых декларациях (расчетах) или иным способом.\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\nНалоговый орган, получивший указанные разногласия, обязан в течение трех дней со дня их получения направить эти разногласия со всеми имеющимися у него материалами для инициирования проведения взаимосогласительной процедуры в рамках налогового мониторинга в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n10. При проведении налогового мониторинга налоговый орган не вправе направлять организации мотивированное мнение по вопросам, связанным с осуществлением контроля соответствия цен, примененных организацией в контролируемых сделках, рыночным ценам.","article_title":"Статья 105.30. Мотивированное мнение налогового органа","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"127c603d0425a8a3accc498a1e5e8b172f1f33f7dedad1ea1cb37d5b78952580"},{"code_id":"NK_RF","article_number":"105.31","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nУведомление вручается или направляется организации в течение трех дней со дня его составления.\n\nУказанное в настоящем пункте уведомление и прилагаемые к нему документы (при их наличии), подтверждающие выполнение указанного мотивированного мнения, представляются в налоговый орган в электронной форме по телекоммуникационным каналам связи либо через информационные системы организации, к которым предоставлен доступ налоговому органу. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)","article_title":"Статья 105.31. Взаимосогласительная процедура в рамках налогового мониторинга","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"64c5cbf0b8538dcb8ea14f49c6d0a763076ce3f6c2fccf67ad433b82d591c4ed"},{"code_id":"NK_RF","article_number":"105.4","version_date":"2000-07-31","article_text":"1. При совершении налогоплательщиками сделок, в отношении которых предусмотрено регулирование цен посредством установления цены или согласования с уполномоченным органом исполнительной власти формулы цены, установления максимальных и (или) минимальных предельных цен, надбавок к цене или скидок с цены либо посредством иных ограничений на рентабельность или прибыль в указанных сделках, цены таких сделок признаются рыночными для целей налогообложения с учетом особенностей, установленных настоящей статьей.\n\nУказанные особенности учитываются, если регулирование цен осуществляется в соответствии с законодательством Российской Федерации, актами Правительства Российской Федерации, законодательством субъектов Российской Федерации, муниципальными правовыми актами, нормативными правовыми актами федеральной территории \"Сириус\", нормативными правовыми актами уполномоченных органов, нормативными правовыми актами иностранных государств, а также международными договорами Российской Федерации. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\n2. В случае установления минимальной предельной цены такая цена не учитывается при определении рыночной цены, если минимальное значение интервала рыночных цен, определенного в соответствии с главой 143 настоящего Кодекса без учета указанной минимальной предельной цены, превышает эту минимальную предельную цену. В противном случае интервалом рыночных цен признается интервал, минимальное значение которого равно этой минимальной предельной цене, а максимальное значение принимается равным его максимальному значению, определенному в соответствии с главой 143 настоящего Кодекса.\n\nВ случае установления максимальной предельной цены такая цена не учитывается при определении рыночной цены, если эта максимальная предельная цена превышает максимальное значение интервала рыночных цен, определенного в соответствии с главой 143 настоящего Кодекса без учета указанной максимальной предельной цены. В противном случае интервалом рыночных цен признается интервал, максимальное значение которого равно этой максимальной предельной цене, а минимальное значение принимается равным его минимальному значению, определенному в соответствии с главой 143 настоящего Кодекса.\n\n3. В случае установления одновременно минимальной и максимальной предельных цен такие цены не учитываются при определении рыночной цены, если минимальное значение интервала рыночных цен, определенного в соответствии с главой 143 настоящего Кодекса без учета указанных минимальной и максимальной предельных цен, превышает эту минимальную предельную цену и установленная максимальная предельная цена превышает максимальное значение этого интервала рыночных цен. В противном случае соответственно минимальное и (или) максимальное значения интервала рыночных цен корректируются в порядке, предусмотренном пунктом 2 настоящей статьи.\n\n4. Если для сделки установлены минимальные и (или) максимальные надбавки к ценам или скидки с цен либо установлены иные ограничения на размеры рентабельности или прибыли, то интервалы рыночных цен (интервалы рентабельности), определенные в соответствии с главой 143 настоящего Кодекса, подлежат корректировке в порядке, аналогичном порядку, предусмотренному пунктами 2 и 3 настоящей статьи.","article_title":"Статья 105.4. Особенности признания цен рыночными для целей налогообложения при применении регулируемых цен","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"61a7d2d3c6fc2e063ab739e46e30a81a090ce3385af806faae28bdf8508ea331"},{"code_id":"NK_RF","article_number":"105.5","version_date":"2000-07-31","article_text":"1. Для определения доходов (прибыли, выручки) в сделках, сторонами которых являются взаимозависимые лица, федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в целях применения методов, предусмотренных статьей 1057 настоящего Кодекса, производит сопоставление таких сделок или совокупности таких сделок (далее в настоящем Кодексе - анализируемая сделка) с одной или несколькими сделками, сторонами которых не являются взаимозависимые лица (далее в настоящем Кодексе - сопоставляемые сделки).\n\n2. В целях настоящего Кодекса сопоставляемые сделки признаются сопоставимыми с анализируемой сделкой, если они совершаются в одинаковых коммерческих и (или) финансовых условиях с анализируемой сделкой.\n\n3. Если коммерческие и (или) финансовые условия сопоставляемых сделок отличаются от коммерческих и (или) финансовых условий анализируемой сделки, такие сделки могут быть признаны сопоставимыми с анализируемой сделкой, если различия между указанными условиями анализируемой и сопоставляемых сделок не оказывают существенного влияния на их результаты или если такие различия могут быть учтены с помощью применения для целей налогообложения соответствующих корректировок к условиям и (или) результатам сопоставляемых сделок или анализируемой сделки.\n\n4. При определении сопоставимости сделок, а также для осуществления корректировок коммерческих и (или) финансовых условий сделок производится анализ следующих характеристик анализируемой и сопоставляемых сделок, которые могут оказывать существенное влияние на коммерческие и (или) финансовые условия сделок, сторонами которых не являются лица, признаваемые взаимозависимыми:\n\n1) характеристик товаров (работ, услуг), являющихся предметом сделки;\n\n2) характеристик функций, выполняемых сторонами сделки в соответствии с обычаями делового оборота, включая характеристики активов, используемых сторонами сделки, принимаемых ими рисков, а также распределение ответственности между сторонами сделки и прочие условия сделки (далее в настоящем Кодексе - функциональный анализ);\n\n3) условий договоров (контрактов), заключенных между сторонами сделки, оказывающих влияние на цены товаров (работ, услуг);\n\n4) характеристик экономических условий деятельности сторон сделки, включая характеристики соответствующих рынков товаров (работ, услуг), оказывающих влияние на цены товаров (работ, услуг);\n\n5) характеристик рыночных (коммерческих) стратегий сторон сделки, оказывающих влияние на цены товаров (работ, услуг).\n\n5. Определение сопоставимости коммерческих и (или) финансовых условий сопоставляемых сделок с условиями анализируемой сделки осуществляется с учетом следующих условий:\n\n1) количества товаров, объема выполняемых работ (оказываемых услуг);\n\n2) сроков исполнения обязательств по сделке;\n\n3) условий платежей, применяемых в соответствующих сделках;\n\n4) курса иностранной валюты, примененной в сделке, по отношению к рублю или другой валюте и его изменения;\n\n5) иных условий распределения прав и обязанностей между сторонами сделки (на основании результатов функционального анализа).\n\n6. Учет функций, исполняемых сторонами сделки, при определении сопоставимости коммерческих и (или) финансовых условий сопоставляемых сделок с условиями анализируемой сделки осуществляется с учетом материальных и нематериальных активов, находящихся в распоряжении сторон сделки. При этом под активами в целях настоящей главы понимаются ресурсы (имущество, в том числе денежные средства, имущественные права, в том числе интеллектуальные права), которыми лицо владеет, пользуется или распоряжается в целях получения дохода. К основным функциям сторон сделки, которые учитываются при определении сопоставимости коммерческих и (или) финансовых условий сопоставляемых сделок с условиями анализируемой сделки, в частности, относятся:\n\n1) осуществление дизайна товаров и их технологической разработки;\n\n2) осуществление производства товаров;\n\n3) осуществление сборки товаров или их компонентов;\n\n4) осуществление монтажа и (или) установки оборудования;\n\n5) проведение научно-исследовательских и опытно-конструкторских работ;\n\n6) приобретение товарно-материальных ценностей;\n\n7) осуществление оптовой или розничной торговли товарами;\n\n8) осуществление функций по ремонту, гарантийному обслуживанию;\n\n9) продвижение на новые рынки товаров (работ, услуг), маркетинг, реклама;\n\n10) хранение товаров;\n\n11) транспортировка товаров;\n\n12) страхование;\n\n13) оказание консультаций, информационное обслуживание;\n\n14) ведение бухгалтерского учета;\n\n15) юридическое обслуживание;\n\n16) предоставление труда работников (персонала); (В редакции Федерального закона от 05.05.2014 № 116-ФЗ)\n\n17) выполнение агентских функций, посредничество;\n\n18) финансирование, осуществление финансовых операций;\n\n19) осуществление контроля качества;\n\n20) осуществление стратегического управления, в том числе определение ценовой политики, стратегии производства и реализации товаров (работ, услуг), объема продаж, ассортимента товаров (предлагаемых работ, услуг), их потребительских свойств, а также осуществление оперативного управления;\n\n21) обучение, повышение квалификации сотрудников;\n\n22) организация сбыта и (или) производства товаров с привлечением других лиц, располагающих соответствующими мощностями;\n\n23) разработка, совершенствование, поддержание в силе, защита и использование нематериальных активов, а также контроль за выполнением этих функций. (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n7. При определении сопоставимости коммерческих и (или) финансовых условий сопоставляемых сделок с условиями анализируемой сделки также учитываются следующие риски, принимаемые каждой из сторон сделки при осуществлении своей деятельности и оказывающие влияние на условия сделки:\n\n1) производственные риски, включая риск неполной загрузки производственных мощностей;\n\n2) риск изменения рыночных цен на приобретаемые материалы и выпускаемую продукцию вследствие изменения экономической конъюнктуры, риск изменения прочих рыночных условий;\n\n3) риск обесценения запасов, потерь товарами качества и иных потребительских свойств;\n\n4) риски, связанные с утратой имущества, имущественных прав;\n\n5) риски изменения курса иностранной валюты по отношению к рублю или другой валюте, процентных ставок, кредитные риски;\n\n6) риск, связанный с безрезультатностью осуществления научно-исследовательских и опытно-конструкторских работ;\n\n7) инвестиционные риски, связанные с возможными финансовыми потерями вследствие ошибок, допущенных при осуществлении инвестиций, включая выбор объектов для инвестиций;\n\n8) риск нанесения ущерба окружающей среде;\n\n9) предпринимательские (коммерческие) риски, связанные с осуществлением стратегического управления, включая ценовую политику и стратегию реализации товаров (работ, услуг);\n\n10) риск невостребованности товара (риск по запасам, складской риск);\n\n11) риск потери деловой репутации вследствие утраты товарами качества и иных потребительских свойств по причинам, не зависящим от сторон сделки; (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n12) риск, связанный с разработкой, совершенствованием, поддержанием в силе, защитой и использованием нематериальных активов. (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n8. При определении сопоставимости коммерческих и (или) финансовых условий сопоставляемых сделок с условиями анализируемой сделки учитываются характеристики рынков товаров (работ, услуг), на которых совершаются сопоставляемые и анализируемая сделки. При этом различия в характеристиках рынков товаров (работ, услуг), на которых совершаются сопоставляемые и анализируемая сделки, не должны оказывать существенного влияния на коммерческие и (или) финансовые условия совершаемых на них сделок либо влияние указанных различий возможно устран\n\nить путем осуществления соответствующих корректировок.\n\nРынком товаров (работ, услуг) признается сфера обращения этих товаров (работ, услуг), определяемая исходя из возможности покупателя (продавца) без значительных дополнительных затрат приобрести (реализовать) товар (работу, услугу) на ближайшей по отношению к покупателю (продавцу) территории Российской Федерации или за пределами Российской Федерации.\n\n9. При определении сопоставимости характеристик рынков товаров (работ, услуг) учитываются следующие факторы:\n\n1) географическое место расположения рынков и их величина;\n\n2) наличие конкуренции на рынках и относительная конкурентоспособность продавцов и покупателей на рынке;\n\n3) наличие на рынке однородных товаров (работ, услуг);\n\n4) предложение и спрос на рынке, а также покупательская способность потребителей;\n\n5) уровень государственного вмешательства в рыночные процессы;\n\n6) уровень развития производственной и транспортной инфраструктуры;\n\n7) иные характеристики рынка, влияющие на цену сделки.\n\n10. При определении сопоставимости коммерческих и (или) финансовых условий сопоставляемых сделок с условиями анализируемой сделки учитываются коммерческие стратегии сторон сопоставляемых и анализируемой сделок, к которым, в частности, относятся стратегии, направленные на обновление и совершенствование выпускаемой продукции, выход на новые рынки сбыта продукции.\n\n11. Если при определении сопоставимости коммерческих и (или) финансовых условий сделок требуется определение сопоставимости условий договора займа, кредитного договора, договора поручительства или банковской гарантии, при сопоставлении условий указанных договоров учитываются также кредитная история и платежеспособность соответственно получателя займа, кредита, лица, обязательства которого обеспечиваются поручительством или банковской гарантией, характер и рыночная стоимость обеспечения исполнения обязательства, а также срок, на который предоставляется заем или кредит, валюта, являющаяся предметом договора займа или кредита, порядок определения процентной ставки (фиксированная или плавающая) и иные условия, которые оказывают влияние на величину процентной ставки (вознаграждения) по соответствующему договору.\n\n12. С учетом анализа условий сопоставляемых сделок в соответствии с пунктом 4 настоящей статьи осуществление корректировок для обеспечения необходимой степени сопоставимости условий сопоставляемых сделок с условиями анализируемой сделки производится федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, на основании следующих принципов:\n\n1) доходы (прибыль, выручка) сторон сделки, не являющейся контролируемой, формируются с учетом используемых активов и принимаемых экономических (коммерческих) рисков в сложившихся на рынке товаров (работ, услуг) экономических условиях и отражают функции, выполняемые каждой стороной сделки в соответствии с условиями договора и обычаями делового оборота;\n\n2) осуществление дополнительных функций, использование активов, существенно влияющих на величину доходов (прибыли, выручки), принятие дополнительных коммерческих (экономических) рисков сторонами сделки в соответствии с рыночной (коммерческой) стратегией при прочих равных условиях сопровождается повышением ожидаемых доходов (прибыли, выручки) по такой сделке.","article_title":"Статья 105.5. Сопоставимость коммерческих и (или) финансовых условий сделок и функциональный анализ","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"85d5a82e1592abfec9ef7c94f3e591cfd3065b6c7c8507528f468c09cfb05849"},{"code_id":"NK_RF","article_number":"105.6","version_date":"2000-07-31","article_text":"1. При проведении налогового контроля в связи с совершением сделок, сторонами которых являются взаимозависимые лица (в том числе при сопоставлении коммерческих и (или) финансовых условий анализируемой сделки с коммерческими и (или) финансовыми условиями сопоставимых сделок), федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, использует следующую информацию:\n\n1) сведения о ценах и котировках российских и иностранных бирж;\n\n2) таможенную статистику внешней торговли Российской Федерации, опубликовываемую или представляемую по запросу федеральным органом исполнительной власти, уполномоченным в области таможенного дела;\n\n3) сведения о ценах (пределах колебаний цен) и биржевых котировках, содержащиеся в официальных источниках информации уполномоченных органов государственной власти, органов местного самоуправления и органов публичной власти федеральной территории \"Сириус\" в соответствии с законодательством Российской Федерации, законодательством субъектов Российской Федерации, муниципальными правовыми актами и нормативными правовыми актами федеральной территории \"Сириус\" (в частности, в области регулирования ценообразования и статистики), официальных источниках информации иностранных государств или международных организаций либо в иных опубликованных и (или) общедоступных изданиях и информационных системах; (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\n4) данные информационно-ценовых агентств;\n\n5) информацию о сделках, совершенных налогоплательщиком.\n\n2. При отсутствии (недостаточности) информации, указанной в пункте 1 настоящей статьи, федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, использует следующую информацию:\n\n1) сведения о ценах (пределах колебаний цен) и котировках, содержащиеся в опубликованных и (или) общедоступных изданиях и информационных системах;\n\n2) сведения, полученные из бухгалтерской (финансовой) и статистической отчетности организаций, в том числе указанные сведения, опубликованные в общедоступных российских или иностранных изданиях и (или) содержащиеся в общедоступных информационных системах, а также на официальных сайтах российских и (или) иностранных организаций. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nСведения, полученные из бухгалтерской (финансовой) отчетности иностранных организаций, допускается использовать для определения интервала рентабельности для российских организаций (иностранных организаций, деятельность которых на территории Российской Федерации приводит к образованию постоянного представительства) только при невозможности расчета такого интервала рентабельности на основании данных бухгалтерской (финансовой) отчетности российских организаций, совершавших сопоставимые сделки; (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n3) сведения о рыночной стоимости объектов оценки, определенной в соответствии с законодательством Российской Федерации или иностранных государств об оценочной деятельности;\n\n4) иную информацию, используемую в соответствии с главой 143 настоящего Кодекса.\n\n3. В целях сопоставления для целей налогообложения условий сделок между взаимозависимыми лицами с условиями сделок между лицами, не являющимися взаимозависимыми, не допускается использование информации, составляющей налоговую тайну, а также иной информации, доступ к которой ограничен в соответствии с законодательством Российской Федерации.\n\nУстановленное настоящим пунктом ограничение не распространяется на сведения о налогоплательщике, в отношении которого проводится проверка федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами.\n\n4. При сопоставлении для целей налогообложения условий сделок между взаимозависимыми лицами с условиями сделок между лицами, не являющимися взаимозависимыми, используются исключительно общедоступные источники информации, а также сведения о налогоплательщике.","article_title":"Статья 105.6. Информация, используемая при сопоставлении условий сделок между взаимозависимыми лицами с условиями сделок между лицами, не являющимися взаимозависимыми","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ea74087f99a1e02217ce3d6de431596b736aed7567ffd3f37fa7134115fc86e8"},{"code_id":"NK_RF","article_number":"105.7","version_date":"2000-07-31","article_text":"1) метод сопоставимых рыночных цен;\n\n2) метод цены последующей реализации;\n\n3) затратный метод;\n\n4) метод сопоставимой рентабельности;\n\n5) метод распределения прибыли.\n\nМетод сопоставимых рыночных цен используется для определения соответствия цены, примененной в контролируемой сделке, рыночной цене в порядке, установленном статьей 1059 настоящего Кодекса, при наличии на соответствующем рынке товаров (работ, услуг) хотя бы одной сопоставимой сделки, предметом которой являются идентичные (при их отсутствии - однородные) товары (работы, услуги), а также при наличии достаточной информации о такой сделке.\n\nПри этом для применения метода сопоставимых рыночных цен в целях определения соответствия цены, примененной налогоплательщиком в контролируемой сделке, в качестве сопоставляемой сделки возможно использование сделки, совершенной указанным налогоплательщиком с лицами, не являющимися взаимозависимыми с указанным налогоплательщиком, при условии, что такая сделка является сопоставимой с анализируемой сделкой.\n\nЕсли иное не предусмотрено настоящей главой, используется тот метод, который с учетом фактических обстоятельств и условий контролируемой сделки позволяет наиболее обоснованно сделать вывод о соответствии или несоответствии цены, примененной в сделке, рыночным ценам.\n\nОднородными сделками для целей главы 142 настоящего Кодекса, настоящей главы и глав 144 - 146 настоящего Кодекса признаются сделки, предметом которых могут являться идентичные (однородные) товары (работы, услуги) и которые совершены в сопоставимых коммерческих и (или) финансовых условиях.\n\nПри невозможности обеспечения сопоставимости данных бухгалтерской (финансовой) отчетности для целей расчета интервала рентабельности и определения для целей налогообложения доходов (прибыли, выручки) в сделках, сторонами которых являются взаимозависимые лица, используются методы, указанные в подпунктах 4 и 5 пункта 1 настоящей статьи. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nПри этом под разовой сделкой в целях настоящей статьи понимается сделка, экономическая суть которой отличается от основной деятельности организации и которая осуществляется на разовой основе.\n\n10. Методы, указанные в подпунктах 4 и 5 пункта 1 настоящей статьи, могут применяться без непосредственного расчета значений рыночных цен. При использовании указанных методов федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, сопоставляет финансовые показатели (результаты) анализируемой сделки (группы однородных анализируемых сделок) с интервалом рентабельности (рассчитанными на основе интервала рентабельности финансовыми показателями) по сопоставимым сделкам, на основании чего производит расчет суммы доходов (прибыли, выручки), которая была бы получена в случае, если бы сторонами данной сделки являлись лица, не признаваемые взаимозависимыми.\n\n11. Судом могут быть учтены иные обстоятельства, имеющие значение для определения соответствия цены, примененной в сделке, рыночной цене, без ограничений, предусмотренных главой 142 настоящего Кодекса и настоящей главой.\n\n12. Налогоплательщики при заключении сделок не обязаны руководствоваться методами, указанными в пункте 1 настоящей статьи, для обоснования своей политики в области ценообразования в целях, не предусмотренных настоящим Кодексом.","article_title":"Статья 105.7. Общие положения о методах, используемых при определении для целей налогообложения доходов (прибыли, выручки) в сделках, сторонами которых являются взаимозависимые лица","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1f28e12e07e7ebbbdc64b373d4bfaef538c5c848aaccb9d332e086db02915720"},{"code_id":"NK_RF","article_number":"105.8","version_date":"2000-07-31","article_text":"1. При определении для целей налогообложения доходов (прибыли, выручки) в сделках, сторонами которых являются взаимозависимые лица, могут быть использованы в порядке, предусмотренном статьями 10510 - 10513 настоящего Кодекса, следующие показатели рентабельности:\n\n1) валовая рентабельность, определяемая как отношение валовой прибыли к выручке от продаж, исчисленной без учета акцизов и налога на добавленную стоимость;\n\n2) валовая рентабельность затрат, определяемая как отношение валовой прибыли к себестоимости проданных товаров (работ, услуг);\n\n3) рентабельность продаж, определяемая как отношение прибыли от продаж к выручке от продаж, исчисленной без учета акцизов и налога на добавленную стоимость;\n\n4) рентабельность затрат, определяемая как отношение прибыли от продаж к сумме себестоимости проданных товаров (работ, услуг), коммерческих и управленческих расходов, связанных с продажей товаров (работ, услуг);\n\n5) рентабельность коммерческих и управленческих расходов, определяемая как отношение валовой прибыли к коммерческим и управленческим расходам, связанным с продажей товаров (работ, услуг);\n\n6) рентабельность активов, определяемая как отношение прибыли от продаж к текущей рыночной стоимости активов (внеоборотных и оборотных), прямо или косвенно используемых в анализируемой сделке. В отсутствие необходимой информации о текущей рыночной стоимости активов рентабельность активов может определяться на основании данных бухгалтерской (финансовой) отчетности. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n2. Показатели, указанные в пункте 1 настоящей статьи, и иные\n\nфинансовые показатели для целей настоящей главы определяются для российских организаций на основании данных бухгалтерской (финансовой) отчетности, которая составляется в соответствии с законодательством Российской Федерации о бухгалтерском учете. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nУказанные финансовые показатели для иностранных организаций определяются на основании данных бухгалтерской (финансовой) отчетности, которая составляется в соответствии с законодательством иностранных государств. При этом для целей обеспечения сопоставимости с данными бухгалтерской (финансовой) отчетности, которая составляется в соответствии с законодательством Российской Федерации о бухгалтерском учете, проводится корректировка таких данных. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nВыбор указанных организаций осуществляется с учетом их отраслевой специфики и соответствующих видов деятельности, осуществляемых ими в сопоставимых экономических (коммерческих) условиях относительно анализируемой сделки.\n\nПри отсутствии в отрасли, к которой принадлежит лицо, являющееся стороной анализируемой сделки, организаций, не являющихся взаимозависимыми с указанным лицом, выбор организаций для проведения анализа осуществляется с учетом сопоставимости функций, осуществляемых этими организациями, принимаемых ими рисков и используемых активов.\n\nВ отсутствие информации о четырех и более сопоставимых сделках либо в отсутствие информации о бухгалтерской (финансовой) отчетности четырех и более сопоставимых организаций в целях определения интервала рентабельности может использоваться информация о меньшем количестве сопоставимых сделок (бухгалтерской (финансовой) отчетности меньшего количества организаций). (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n1) совокупность значений рентабельности, которые используются для определения интервала рентабельности, упорядочивается по возрастанию, образуя выборку, используемую для определения этого интервала. При этом каждому значению рентабельности, начиная с минимального, присваивается порядковый номер. В случае, если выборка содержит два и более одинаковых значения рентабельности, в выборку включаются все такие значения. При определении интервала рентабельности не учитывается рентабельность анализируемой сделки;\n\n2) минимальное значение интервала рентабельности определяется в следующем порядке:\n\nесли частное от деления на четыре числа значений рентабельности в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, является целым числом, то минимальным значением интервала рентабельности признается среднее арифметическое значения рентабельности, имеющего в выборке порядковый номер, равный этому целому числу, и значения рентабельности, имеющего следующий по возрастанию порядковый номер в этой выборке;\n\nесли частное от деления на четыре числа значений рентабельности в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, не является целым числом, то минимальным значением интервала рентабельности признается значение рентабельности, имеющее в выборке порядковый номер, равный целой части этого дробного числа, увеличенной на единицу;\n\n3) максимальное значение интервала рентабельности определяется в следующем порядке:\n\nесли произведение 0,75 и числа значений рентабельности в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, является целым числом, то максимальным значением интервала рентабельности признается среднее арифметическое значения рентабельности, имеющего в выборке порядковый номер, равный этому целому числу, и значения рентабельности, имеющего следующий по возрастанию порядковый номер в этой выборке;\n\nесли произведение 0,75 и числа значений рентабельности в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, не является целым числом, то максимальным значением интервала рентабельности признается значение рентабельности, имеющее в выборке порядковый номер, равный целой части этого дробного числа, увеличенной на единицу;\n\n4) медианное значение интервала рентабельности определяется в следующем порядке:\n\nесли частное от деления на два числа значений рентабельности в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, является целым числом, то медианным значением интервала рентабельности признается среднее арифметическое значения рентабельности, имеющего в выборке порядковый номер, равный этому целому числу, и значения рентабельности, имеющего следующий по возрастанию порядковый номер в этой выборке;\n\nесли частное от деления на два числа значений рентабельности в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, не является целым числом, то медианным значением интервала рентабельности признается значение рентабельности, имеющее в выборке порядковый номер, равный целой части этого дробного числа, увеличенной на единицу.\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n1) если организация осуществляет сопоставимую деятельность и выполняет сопоставимые функции, связанные с этой деятельностью. Сопоставимость деятельности может определяться с учетом видов экономической деятельности, предусмотренных Общероссийским классификатором видов экономической деятельности, а также международными и иными классификаторами;\n\n2) если совокупная величина чистых активов организации не является отрицательной по данным бухгалтерской (финансовой) отчетности по состоянию на 31 декабря последнего года из нескольких лет, за которые рассчитывается рентабельность; (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n3) если организация не имеет убытков от продаж по данным бухгалтерской (финансовой) отчетности более чем в одном году из нескольких лет, за которые рассчитывается рентабельность; (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n4) если организация не участвует прямо и (или) косвенно в другой организации с долей такого участия более 25 процентов (за исключением случаев, когда доступны сведения о консолидированной финансовой отчетности организаций, которые используются для расчета интервала рентабельности) или не имеет в качестве участника (акционера) организацию с долей прямого участия более 25 процентов.\n\nК указанной выше информации относится информация налогоплательщика о совершенных им сделках с лицами, не являющимися с ним взаимозависимыми.","article_title":"Статья 105.8. Финансовые показатели и интервал рентабельности","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a6cfa1fa6d8ff33bce2eefa568b4dfe6aa9115bef36009ee14da27b43a88579b"},{"code_id":"NK_RF","article_number":"105.9","version_date":"2000-07-31","article_text":"1) совокупность цен, примененных в сопоставимых сделках, которые используются для определения интервала рыночных цен, упорядочивается по возрастанию, образуя выборку, используемую для определения этого интервала. При этом каждому значению цены, начиная с минимального, присваивается порядковый номер. В случае, если выборка содержит два и более одинаковых значения цены, в выборку включаются все такие значения. При определении интервала рыночных цен не учитывается цена, примененная в анализируемой сделке. При наличии достаточного количества сопоставимых сделок, совершенных налогоплательщиком, сторонами которых не являются взаимозависимые лица, при определении интервала рыночных цен не учитывается информация по прочим сделкам;\n\n2) минимальное значение интервала рыночных цен определяется в следующем порядке:\n\nесли частное от деления на четыре числа значений цен в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, является целым числом, то минимальным значением интервала рыночных цен признается среднее арифметическое значения цены, имеющего в выборке порядковый номер, равный этому целому числу, и значения цены, имеющего следующий по возрастанию порядковый номер в этой выборке;\n\nесли частное от деления на четыре числа значений цен в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, не является целым числом, то минимальным значением интервала рыночных цен признается значение цены, имеющее в выборке порядковый номер, равный целой части этого дробного числа, увеличенной на единицу;\n\n3) максимальное значение интервала рыночных цен определяется в следующем порядке:\n\nесли произведение 0,75 и числа значений цен в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, является целым числом, то максимальным значением интервала рыночных цен признается среднее арифметическое значения цены, имеющего в выборке порядковый номер, равный этому целому числу, и значения цены, имеющего следующий по возрастанию порядковый номер в этой выборке;\n\nесли произведение 0,75 и числа значений цен в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, не является целым числом, то максимальным значением интервала рыночных цен признается значение цены, имеющее в выборке порядковый номер, равный сумме целой части этого дробного числа, увеличенной на единицу;\n\n4) медианное значение интервала рыночных цен определяется в следующем порядке:\n\nесли частное от деления на два числа значений цен в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, является целым числом, то медианным значением интервала рыночных цен признается среднее арифметическое значения цены, имеющего в выборке порядковый номер, равный этому целому числу, и значения цены, имеющего следующий по возрастанию порядковый номер в этой выборке;\n\nесли частное от деления на два числа значений цен в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, не является целым числом, то медианным значением интервала рыночных цен признается значение цены, имеющее в выборке порядковый номер, равный целой части этого дробного числа, увеличенной на единицу.\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n1) обоснованные и подтвержденные документально и (или) источниками информации расходы, необходимые для доставки товаров (работ, услуг) на соответствующий рынок;\n\n2) расходы на уплату вывозных таможенных пошлин;\n\n3) условия платежа;\n\n4) комиссионное (агентское) вознаграждение торгового брокера (комиссионера или агента) за выполнение им торгово-посреднических функций.\n\nВ случае, если цена, примененная в анализируемой сделке, меньше минимального значения интервала рыночных цен, определенного в соответствии с положениями настоящей статьи, или превышает максимальное значение интервала рыночных цен, определенного в соответствии с положениями настоящей статьи, для целей налогообложения принимается цена, которая соответствует медианному значению интервала рыночных цен.\n\nПрименение для целей налогообложения медианного значения интервала рыночных цен в соответствии с настоящим пунктом производится при условии, что это не приводит к уменьшению суммы налога, подлежащего уплате в бюджетную систему Российской Федерации, или увеличению суммы убытка, определяемого в соответствии с главой 25 настоящего Кодекса, если иное не предусмотрено по результатам взаимосогласительной процедуры в соответствии с международным договором Российской Федерации по вопросам налогообложения.\n\n(Пункт в редакции  Федерального закона от 27.11.2023 № 539-ФЗ)","article_title":"Статья 105.9. Метод сопоставимых рыночных цен","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2aa6f2b23470dbd73b192870f25406588175452985404f0d1b065e699c5119ce"},{"code_id":"NK_RF","article_number":"106","version_date":"2000-07-31","article_text":"Налоговым правонарушением признается виновно совершенное противоправное (в нарушение законодательства о налогах и сборах) деяние (действие или бездействие) налогоплательщика, плательщика страховых взносов, налогового агента и иных лиц, за которое настоящим Кодексом установлена ответственность. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 03.07.2016 № 243-ФЗ)","article_title":"Статья 106. Понятие налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"04d6216d03392201b441d1062ca4747a6c9338548bc9f2b5cb668dea92a05391"},{"code_id":"NK_RF","article_number":"108","version_date":"2000-07-31","article_text":"1. Никто не может быть привлечен к ответственности за совершение налогового правонарушения иначе, как по основаниям и в порядке, которые предусмотрены настоящим Кодексом.\n\nОтветственность за неисполнение обязанности по уплате налога на прибыль организаций, налога на доходы физических лиц с прибыли (дохода), приходящейся на долю участника договора инвестиционного товарищества, несет соответствующий участник такого договора, если иное не установлено настоящим Кодексом.\n\n(Дополнение пунктом - Федеральный закон от 28.11.2011 № 336-ФЗ)","article_title":"Статья 108. Общие условия привлечения к ответственности за совершение налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2d8aaad0e1e47442eedda63a36c130424f2d8e9ff3c5b263b82e845532a753e5"},{"code_id":"NK_RF","article_number":"109","version_date":"2000-07-31","article_text":"1) отсутствие события налогового правонарушения;\n\n2) отсутствие вины лица в совершении налогового правонарушения;\n\n3) совершение деяния, содержащего признаки налогового правонарушения, физическим лицом, не достигшим к моменту совершения деяния шестнадцатилетнего возраста;\n\n4) истечение сроков давности привлечения к ответственности за совершение налогового правонарушения.\n\nВ случае, указанном в настоящем пункте, основанием для непривлечения лица к ответственности за совершение налогового правонарушения является представление копии такой специальной декларации и копий прилагаемых к ней документов и (или) сведений с отметкой налогового органа о приеме.\n\n(Дополнение пунктом - Федеральный закон от 08.06.2015 № 150-ФЗ)","article_title":"Статья 109. Обстоятельства, исключающие привлечение лица к ответственности за совершение налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1aa2389ff2159e1e5316861673276067c22e0c2fdd3ffba619ef33970d8eca6e"},{"code_id":"NK_RF","article_number":"11","version_date":"2000-07-31","article_text":"1. Институты, понятия и термины гражданского, семейного и других отраслей законодательства Российской Федерации, используемые в настоящем Кодексе, применяются в том значении, в каком они используются в этих отраслях законодательства, если иное не предусмотрено настоящим Кодексом.\n\nорганизации - юридические лица, образованные в соответствии с законодательством Российской Федерации, международные компании (далее - российские организации), а также иностранные юридические лица, компании и другие корпоративные образования, обладающие гражданской правоспособностью, созданные в соответствии с законодательством иностранных государств, международные организации, филиалы и представительства указанных иностранных лиц и международных организаций, созданные на территории Российской Федерации (далее - иностранные организации); (В редакции Федерального закона от 03.08.2018 № 294-ФЗ)\n\nфизические лица - граждане Российской Федерации, иностранные граждане и лица без гражданства;\n\nиндивидуальные предприниматели - физические лица, зарегистрированные в установленном порядке и осуществляющие предпринимательскую деятельность без образования юридического лица, главы крестьянских (фермерских) хозяйств. Физические лица, осуществляющие предпринимательскую деятельность без образования юридического лица, но не зарегистрировавшиеся в качестве индивидуальных предпринимателей в нарушение требований гражданского законодательства Российской Федерации, при исполнении обязанностей, возложенных на них настоящим Кодексом, не вправе ссылаться на то, что они не являются индивидуальными предпринимателями; (В редакции федеральных законов от 23.12.2003 № 185-ФЗ; от 27.07.2006 № 137-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nлица (лицо) - организации и (или) физические лица;\n\nиностранная структура без образования юридического лица - организационная форма, созданная в соответствии с законодательством иностранного государства (территории) без образования юридического лица (в частности, фонд, партнерство, товарищество, траст, иная форма осуществления коллективных инвестиций и (или) доверительного управления), которая в соответствии со своим личным законом вправе осуществлять деятельность, направленную на извлечение дохода (прибыли) в интересах своих участников (пайщиков, доверителей или иных лиц) либо иных бенефициаров; (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ)\n\nиностранные финансовые посредники - иностранные фондовые биржи и иностранные депозитарно-клиринговые организации, включенные в перечень, утверждаемый Центральным банком Российской Федерации по согласованию с Министерством финансов Российской Федерации; (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ)\n\nпубличные компании - российские и иностранные организации, являющиеся эмитентами ценных бумаг, которые (либо депозитарные расписки на которые) прошли процедуру листинга и (или) были допущены к обращению на одной или нескольких российских биржах, имеющих соответствующую лицензию, или биржах, включенных в перечень иностранных финансовых посредников; (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nбанки (банк) - коммерческие банки и другие кредитные организации, имеющие лицензию Центрального банка Российской Федерации;\n\nсчета (счет) - расчетные (текущие) и иные счета в банках, открытые на основании договора банковского счета, включая счета в банках, открытые на основании договора банковского счета в драгоценных металлах; (В редакции федеральных законов от 28.06.2013 № 134-ФЗ; от 27.11.2017 № 343-ФЗ)\n\nсчет цифрового рубля - счет, открытый оператором платформы цифрового рубля на основании договора счета цифрового рубля; (Дополнение абзацем - Федеральный закон от 19.12.2023 № 610-ФЗ)\n\nлицевые счета - счета, открытые в органах Федерального казначейства (иных органах, осуществляющих открытие и ведение лицевых счетов) в соответствии с бюджетным законодательством Российской Федерации; (Дополнение абзацем - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nсчет Федерального казначейства - казначейский счет для осуществления и отражения операций по учету и распределению поступлений; (Дополнение абзацем - Федеральный закон от 27.07.2006 № 137-ФЗ) (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nисточник выплаты доходов налогоплательщику - организация или физическое лицо, от которых налогоплательщик получает доход;\n\nнедоимка - сумма налога, сумма сбора или сумма страховых взносов, не уплаченная (не перечисленная) в установленный законодательством о налогах и сборах срок; (В редакции  федеральных законов от 03.07.2016 № 243-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nсвидетельство о постановке на учет в налоговом органе - документ, подтверждающий постановку на учет российской организации, иностранной организации, физического лица в налоговом органе соответственно по месту нахождения российской организации, месту нахождения международной организации, по месту осуществления иностранной организацией деятельности на территории Российской Федерации через свое обособленное подразделение, по месту жительства физического лица; (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nуведомление о постановке на учет в налоговом органе - документ, подтверждающий постановку на учет в налоговом органе организации или физического лица, в том числе индивидуального предпринимателя, по основаниям, установленным настоящим Кодексом, за исключением оснований, по которым настоящим Кодексом предусмотрена выдача свидетельства о постановке на учет в налоговом органе; (Дополнение абзацем - Федеральный закон от 23.12.2003 № 185-ФЗ) (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nсезонное производство - производство, осуществление которого непосредственно связано с природными, климатическими условиями и со временем года. Данное понятие применяется в отношении организации и индивидуального предпринимателя, если в определенные налоговые периоды (квартал, полугодие) их производственная деятельность не осуществляется в силу природных и климатических условий;\n\nабзац; (Утратил силу - Федеральный закон от 23.12.2003 № 185-ФЗ)\n\nместо нахождения обособленного подразделения российской организации - место осуществления этой организацией деятельности через свое обособленное подразделение; (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nместо жительства физического лица - адрес (наименование субъекта Российской Федерации, района, города, иного населенного пункта, улицы, номера дома, квартиры), по которому физическое лицо зарегистрировано по месту жительства в порядке, установленном законодательством Российской Федерации. При отсутствии у физического лица места жительства на территории Российской Федерации для целей настоящего Кодекса место жительства может определяться по просьбе этого физического лица по месту его пребывания. При этом местом пребывания физического лица признается место, где физическое лицо проживает временно по адресу (наименование субъекта Российской Федерации, района, города, иного населенного пункта, улицы, номер дома, квартиры), по которому физическое лицо зарегистрировано по месту пребывания в порядке, установленном законодательством Российской Федерации; (В редакции федеральных законов от 23.12.2003 № 185-ФЗ; от 27.07.2010 № 229-ФЗ)\n\nобособленное подразделение организации - любое территориально обособленное от нее подразделение, по месту нахождения которого оборудованы стационарные рабочие места. Признание обособленного подразделения организации таковым производится независимо от того, отражено или не отражено его создание в учредительных или иных организационно-распорядительных документах организации, и от полномочий, которыми наделяется указанное подразделение. При этом рабочее место считается стационарным, если оно создается на срок более одного месяца;\n\nучетная политика для целей налогообложения - выбранная налогоплательщиком совокупность допускаемых настоящим Кодексом способов (методов) определения доходов и (или) расходов, их признания, оценки и распределения, а также учета иных необходимых для целей налогообложения показателей финансово-хозяйственной деятельности налогоплательщика; (Дополнение абзацем - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nтерритория Российской Федерации и иные территории, находящиеся под ее юрисдикцией, - территория Российской Федерации, а также территории искусственных островов, установок и сооружений, над которыми Российская Федерация осуществляет юрисдикцию в соответствии с законодательством Российской Федерации и нормами международного права; (Дополнение абзацем - Федеральный закон от 27.11.2010 № 306-ФЗ)\n\nкоэффициент-дефлятор - коэффициент, устанавливаемый ежегодно на каждый следующий календарный год и рассчитываемый как произведение коэффициента-дефлятора, применяемого для целей соответствующих глав настоящего Кодекса в предшествующем календарном году, и коэффициента, учитывающего изменение потребительских цен на товары (работы, услуги) в Российской Федерации в предшествующем календарном году. Коэффициенты-дефляторы устанавливаются, если иное не предусмотрено законодательством Российской Федерации о налогах и сборах, федеральным органом исполнительной власти, осуществляющим функции по нормативно-правовому регулированию в сфере анализа и прогнозирования социально-экономического развития, в соответствии с данными государственной статистической отчетности и, если иное не предусмотрено законодательством Российской Федерации о налогах и сборах, подлежат официальному опубликованию не позднее 20 ноября года, в котором устанавливаются коэффициенты-дефляторы; (Дополнение абзацем - Федеральный закон от 25.06.2012 № 94-ФЗ) (В редакции федеральных законов  от 29.12.2015 № 386-ФЗ;  от 27.11.2017 № 335-ФЗ)\n\nсовокупная обязанность - общая сумма налогов, авансовых платежей, сборов, страховых взносов, пеней, штрафов, процентов, которую обязан уплатить (перечислить) налогоплательщик, плательщик сбора, плательщик страховых взносов и (или) налоговый агент, и сумма налога, подлежащая возврату в бюджетную систему Российской Федерации в случаях, предусмотренных настоящим Кодексом. При этом в совокупную обязанность не включаются суммы налога на доходы физических лиц, уплачиваемого в порядке, установленном статьей 2271 настоящего Кодекса, и суммы государственной пошлины, за исключением государственной пошлины, в отношении уплаты которой арбитражным судом выдан исполнительный документ; (Дополнение абзацем - Федеральный закон от 14.07.2022 № 263-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nзадолженность по уплате налогов, сборов и страховых взносов в бюджеты бюджетной системы Российской Федерации (далее - задолженность) - общая сумма недоимок, а также не уплаченных налогоплательщиком, плательщиком сборов, плательщиком страховых взносов и (или) налоговым агентом пеней, штрафов и процентов, предусмотренных настоящим Кодексом, и сумм налогов, подлежащих возврату в бюджетную систему Российской Федерации в случаях, предусмотренных настоящим Кодексом, равная размеру отрицательного сальдо единого налогового счета этого лица, а также сумм, не учитываемых в совокупной обязанности в соответствии с подпунктами 10 и 101 пункта 5, подпунктами 2 - 34, 5 и 6 пункта 7 статьи 113 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 14.07.2022 № 263-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 287-ФЗ)\n\n\"Инвестиционный проект\" - ограниченный по времени и затрачиваемым ресурсам комплекс мероприятий, предусматривающих создание и последующую эксплуатацию нового имущественного комплекса и (или) нематериальных активов либо модернизацию (реконструкцию, техническое перевооружение) существующего имущественного комплекса в целях создания нового производства товаров (работ, услуг), увеличения объемов существующего производства товаров (работ, услуг) и (или) предотвращения (минимизации) негативного влияния на окружающую среду. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n(Пункт в редакции Федерального закона от 09.07.1999 № 154-ФЗ)","article_title":"Статья 11. Институты, понятия и термины, используемые в настоящем Кодексе","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4599df59cd5566bef8cc34744172fa2d570096a1a7d9b66ca03ee14124da99b1"},{"code_id":"NK_RF","article_number":"110","version_date":"2000-07-31","article_text":"1. Виновным в совершении налогового правонарушения признается лицо, совершившее противоправное деяние умышленно или по неосторожности.\n\n2. Налоговое правонарушение признается совершенным умышленно, если лицо, его совершившее, осознавало противоправный характер своих действий (бездействия), желало либо сознательно допускало наступление вредных последствий таких действий (бездействия).\n\n3. Налоговое правонарушение признается совершенным по неосторожности, если лицо, его совершившее, не осознавало противоправного характера своих действий (бездействия) либо вредного характера последствий, возникших вследствие этих действий (бездействия), хотя должно было и могло это осознавать.\n\n4. Вина организации в совершении налогового правонарушения определяется в зависимости от вины ее должностных лиц, либо ее представителей, действия (бездействие) которых обусловили совершение данного налогового правонарушения.","article_title":"Статья 110. Формы вины при совершении налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"71dede02a4d7e55719c3e660125af9aa22c1293d623a29a440ef6444a804a115"},{"code_id":"NK_RF","article_number":"111","version_date":"2000-07-31","article_text":"1. Обстоятельствами, исключающими вину лица в совершении налогового правонарушения, признаются:\n\n1) совершение деяния, содержащего признаки налогового правонарушения, вследствие стихийного бедствия или других чрезвычайных и непреодолимых обстоятельств (указанные обстоятельства устанавливаются наличием общеизвестных фактов, публикаций в средствах массовой информации и иными способами, не нуждающимися в специальных средствах доказывания); (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n2) совершение деяния, содержащего признаки налогового правонарушения, физическим лицом, находившимся в момент его совершения в состоянии, при котором это лицо не могло отдавать себе отчета в своих действиях или руководить ими вследствие болезненного состояния (указанные обстоятельства доказываются предоставлением в налоговый орган документов, которые по смыслу, содержанию и дате относятся к тому налоговому (расчетному) периоду, в котором совершено налоговое правонарушение); (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n3) выполнение налогоплательщиком (плательщиком сбора, плательщиком страховых взносов, налоговым агентом) письменных разъяснений о порядке исчисления, уплаты налога (сбора, страховых взносов) или по иным вопросам применения законодательства о налогах и сборах, данных ему либо неопределенному кругу лиц финансовым, налоговым или другим уполномоченным органом государственной власти (уполномоченным должностным лицом этого органа) в пределах его компетенции (указанные обстоятельства устанавливаются при наличии соответствующего документа этого органа, по смыслу и содержанию относящегося к налоговым (расчетным) периодам, в которых совершено налоговое правонарушение, независимо от даты издания такого документа), и (или) выполнение налогоплательщиком (плательщиком сбора, плательщиком страховых взносов, налоговым агентом) мотивированного мнения налогового органа, направленного ему в ходе проведения налогового мониторинга. (В редакции федеральных законов от 04.11.2014 № 348-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nПоложение настоящего подпункта не применяется в случае, если указанные письменные разъяснения, мотивированное мнение налогового органа основаны на неполной или недостоверной информации, представленной налогоплательщиком (плательщиком сбора, плательщиком страховых взносов, налоговым агентом); (В редакции федеральных законов от 04.11.2014 № 348-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n(Подпункт в редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n4) иные обстоятельства, которые могут быть признаны судом или налоговым органом, рассматривающим дело, исключающими вину лица в совершении налогового правонарушения. (Дополнение подпунктом - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n2. При наличии обстоятельств, указанных в пункте 1 настоящей статьи, лицо не подлежит ответственности за совершение налогового правонарушения.","article_title":"Статья 111. Обстоятельства, исключающие вину лица в совершении налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"697e36d7869ed33b8f29e3bcf66847d4d71e7297af6d840a1ea269f99c140532"},{"code_id":"NK_RF","article_number":"112","version_date":"2000-07-31","article_text":"1. Обстоятельствами, смягчающими ответственность за совершение налогового правонарушения, признаются:\n\n1) совершение правонарушения вследствие стечения тяжелых личных или семейных обстоятельств;\n\n2) совершение правонарушения под влиянием угрозы или принуждения либо в силу материальной, служебной или иной зависимости;\n\n21) тяжелое материальное положение физического лица, привлекаемого к ответственности за совершение налогового правонарушения; (Дополнение подпунктом - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n3) иные обстоятельства, которые судом или налоговым органом, рассматривающим дело, могут быть признаны смягчающими ответственность. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 04.11.2005 № 137-ФЗ)\n\n2. Обстоятельством, отягчающим ответственность, признается совершение налогового правонарушения лицом, ранее привлекаемым к ответственности за аналогичное правонарушение.","article_title":"Статья 112. Обстоятельства, смягчающие и отягчающие ответственность за совершение налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ddb6089da47eac7a9c70d28dbb64aeed7e62777babe0f580cb5bcd1b7d2a2c59"},{"code_id":"NK_RF","article_number":"11.3","version_date":"2000-07-31","article_text":"1. Единым налоговым платежом признаются денежные средства, перечисленные налогоплательщиком, плательщиком сбора, плательщиком страховых взносов, налоговым агентом и (или) иным лицом в бюджетную систему Российской Федерации на счет Федерального казначейства, предназначенные для исполнения совокупной обязанности налогоплательщика, плательщика сбора, плательщика страховых взносов, налогового агента, а также денежные средства, взысканные с налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента в соответствии с настоящим Кодексом. Для целей настоящего Кодекса единым налоговым платежом также признаются суммы денежных средств, подлежащие учету на едином налоговом счете:\n\n1) в связи с принятием налоговым органом решения о возмещении (о предоставлении налогового вычета) суммы налога, - в день принятия соответствующего решения;\n\n2) в связи с поступлением от иного лица в результате зачета суммы денежных средств в соответствии со статьей 78 настоящего Кодекса, - в день осуществления налоговым органом такого зачета;\n\n3) в связи с отменой (полностью или частично) зачета денежных средств в счет исполнения предстоящей обязанности по уплате конкретного налога (сбора, страхового взноса) на основании заявления, представленного в соответствии с пунктом 6 статьи 78 настоящего Кодекса, либо в связи с представлением налогоплательщиком - физическим лицом заявления о перерасчете суммы ранее исчисленного налога или жалобы на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, либо в связи с отсутствием на едином налоговом счете денежных средств, необходимых для исполнения обязанности по уплате налогов, сборов, страховых взносов, пеней, штрафов и (или) процентов, - не позднее дня, следующего за днем представления указанного заявления в соответствии с пунктом 6 статьи 78 настоящего Кодекса, или дня, следующего за днем представления налогоплательщиком - физическим лицом заявления о перерасчете суммы ранее исчисленного налога или данной жалобы,, или в день возникновения задолженности. Признание единым налоговым платежом сумм денежных средств, ранее зачтенных в счет исполнения предстоящей обязанности налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента по уплате конкретного налога, осуществляется последовательно начиная с наиболее ранних сроков уплаты налога (сбора, страхового взноса), в счет исполнения обязанности по уплате которого был осуществлен зачет. В случае совпадения сроков уплаты признание единым налоговым платежом указанных денежных средств осуществляется начиная с меньшей суммы; (В редакции  федеральных законов от 29.05.2023 № 196-ФЗ, от 31.07.2023 № 389-ФЗ, от 31.07.2025 № 287-ФЗ)\n\n4) в связи с начислением налоговым органом процентов в соответствии с пунктами 4 и (или) 9 статьи 79 настоящего Кодекса, - со дня их начисления;\n\n5) в связи с представлением налогоплательщиком, плательщиком сбора, плательщиком страховых взносов заявления о возврате излишне уплаченных сумм налога на доходы физических лиц, уплачиваемого в порядке, установленном статьей 2271 настоящего Кодекса, налога на профессиональный доход и сборов за пользование объектами животного мира и за пользование объектами водных биологических ресурсов, налога на сверхприбыль,  страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности, - в размере излишне уплаченной суммы налога (сбора, страхового взноса) не позднее дня, следующего за днем получения указанного заявления. Перечни указанных в настоящем подпункте плательщиков страховых взносов устанавливаются в порядке, предусмотренном соответственно Федеральным законом от 27 ноября 2001 года № 155-ФЗ \"О дополнительном социальном обеспечении членов летных экипажей воздушных судов гражданской авиации\" и Федеральным законом от 10 мая 2010 года № 84-ФЗ \"О дополнительном социальном обеспечении отдельных категорий работников организаций угольной промышленности\". (В редакции  федеральных законов от 08.08.2024 № 259-ФЗ, от 29.10.2024 № 362-ФЗ)\n\n2. Единым налоговым счетом признается форма учета налоговыми органами:\n\n1) денежного выражения совокупной обязанности;\n\n2) денежных средств, перечисленных в качестве единого налогового платежа и (или) признаваемых в качестве единого налогового платежа.\n\n3. Сальдо единого налогового счета представляет собой разницу между общей суммой денежных средств, перечисленных и (или) признаваемых в качестве единого налогового платежа, и денежным выражением совокупной обязанности.\n\nПоложительное сальдо единого налогового счета формируется, если общая сумма денежных средств, перечисленных и (или) признаваемых в качестве единого налогового платежа, больше денежного выражения совокупной обязанности. При формировании положительного сальдо единого налогового счета не учитываются суммы денежных средств, зачтенные в счет исполнения соответствующей обязанности налогоплательщика, плательщика сбора, плательщика страховых взносов и (или) налогового агента. (В редакции  Федерального закона от 29.05.2023 № 196-ФЗ)\n\nОтрицательное сальдо единого налогового счета формируется, если общая сумма денежных средств, перечисленных и (или) признаваемых в качестве единого налогового платежа, меньше денежного выражения совокупной обязанности.\n\nНулевое сальдо единого налогового счета формируется, если общая сумма денежных средств, перечисленных и (или) признаваемых в качестве единого налогового платежа, равна денежному выражению совокупной обязанности.\n\n4. Единый налоговый счет ведется в отношении каждого физического лица и каждой организации, являющихся налогоплательщиками, плательщиками сборов, плательщиками страховых взносов и (или) налоговыми агентами (в том числе при исполнении обязанности управляющего товарища, ответственного за ведение налогового учета в связи с выполнением договора инвестиционного товарищества).\n\n5. Совокупная обязанность формируется и подлежит учету на едином налоговом счете лица, указанного в пункте 4 настоящей статьи, в валюте Российской Федерации на основе:\n\n1) налоговых деклараций (расчетов), которые представлены в налоговый орган (за исключением налоговых деклараций (расчетов) указанных в подпункте 3 настоящего пункта), - со дня их представления в налоговый орган, но не ранее наступления срока уплаты соответствующих налогов (сборов, авансовых платежей по налогам, страховых взносов), если иное не предусмотрено абзацем вторым настоящего подпункта.\n\nВ случае обнаружения налоговым органом факта несоответствия показателей указанных в абзаце первом настоящего подпункта налоговых деклараций (расчетов) (за исключением налоговых деклараций (расчетов), представленных налогоплательщиками, в отношении которых проводится налоговый мониторинг) контрольным соотношениям, свидетельствующего о нарушении порядка их заполнения (за исключением контрольных соотношений, указанных в пункте 53 статьи 174 настоящего Кодекса), указанные налоговые декларации (расчеты) учитываются при определении размера совокупной обязанности со дня вступления в силу решения налогового органа по результатам камеральной налоговой проверки на основе указанных налоговых деклараций (расчетов) либо в течение десяти дней со дня окончания установленного статьей 88 настоящего Кодекса срока проведения камеральной налоговой проверки или со дня, сл\n\nедующего за днем завершения камеральной налоговой проверки указанных налоговых деклараций (расчетов), если при ее проведении не были выявлены нарушения законодательства о налогах и сборах.\n\nПеречень контрольных соотношений, указанных в абзаце втором настоящего подпункта, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов;\n\n(Подпункт в редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n2) уточненных налоговых деклараций (расчетов), которые представлены в налоговый орган и в которых по сравнению с ранее представленными в налоговые органы налоговыми декларациями (расчетами) увеличены причитающиеся к уплате суммы налогов (сборов, авансовых платежей по налогам, страховых взносов), - со дня представления в налоговые органы уточненных налоговых деклараций (расчетов), но не ранее наступления срока уплаты соответствующих налогов (сборов, авансовых платежей по налогам, страховых взносов);\n\n3) налоговых деклараций, в которых заявлены суммы налогов к возмещению либо суммы предусмотренных главой 23 настоящего Кодекса налоговых вычетов, - со дня вступления в силу решения налогового органа по результатам камеральной налоговой проверки на основе указанных налоговых деклараций (расчетов) либо в течение десяти дней со дня окончания установленного статьей 88 настоящего Кодекса срока проведения камеральной налоговой проверки указанных налоговых деклараций (расчетов) или со дня, следующего за днем завершения камеральной налоговой проверки указанных налоговых деклараций (расчетов), если при проведении камеральной налоговой проверки указанной налоговой декларации не были выявлены нарушения законодательства о налогах и сборах, если иное не предусмотрено настоящим пунктом; (В редакции  федеральных законов от 28.12.2022 № 565-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n31) уточненных налоговых деклараций (расчетов) (за исключением уточненных налоговых деклараций (расчетов), указанных в подпункте 4 настоящего пункта), в которых по сравнению с ранее представленными в налоговые органы налоговыми декларациями (расчетами) уменьшены причитающиеся к уплате суммы налогов (сборов, авансовых платежей по налогам, страховых взносов):\n\nв случае их представления не позднее наступления срока уплаты соответствующих налогов (сборов, авансовых платежей по налогам, страховых взносов) - со дня их представления, но не ранее наступления срока уплаты соответствующих налогов (сборов, авансовых платежей по налогам, страховых взносов);\n\nв случае их представления после наступления срока уплаты соответствующих налогов (сборов, авансовых платежей по налогам, страховых взносов) - со дня вступления в силу решения налогового органа по результатам камеральной налоговой проверки на основе указанных налоговых деклараций (расчетов), либо в течение десяти дней со дня окончания установленного статьей 88 настоящего Кодекса срока проведения камеральной налоговой проверки указанных налоговых деклараций (расчетов) или со дня, следующего за днем завершения камеральной налоговой проверки указанных налоговых деклараций (расчетов), если при ее проведении не были выявлены нарушения законодательства о налогах и сборах, либо со дня их представления, если в течение следующего рабочего дня после представления уточненных налоговых деклараций (расчетов), указанных в абзаце первом настоящего подпункта, представлены уточненные декларации (расчеты), в которых по сравнению с ранее представленными уточненными налоговыми декларациями (расчетами) увеличены причитающиеся к уплате суммы налогов (сборов, авансовых платежей по налогам, страховых взносов) в размере, равном суммам налогов (сборов, авансовых платежей по налогам, страховых взносов), на которые они были уменьшены в уточненных налоговых декларациях (расчетах), указанных в абзаце первом настоящего подпункта; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 28.12.2022 № 565-ФЗ)\n\n4) уточненных налоговых деклараций (расчетов), которые представлены организацией, в отношении которой проводится налоговый мониторинг, и в которых по сравнению с ранее представленными в налоговые органы налоговыми декларациями (расчетами) уменьшены причитающиеся к уплате суммы налогов (сборов, авансовых платежей по налогам, страховых взносов), со дня представления в налоговый орган уточненных налоговых деклараций (расчетов), но не ранее наступления срока уплаты соответствующих налогов (сборов, авансовых платежей по налогам, страховых взносов); (В редакции  Федерального закона от 28.12.2022 № 565-ФЗ)\n\n5) уведомлений об исчисленных суммах налогов, сборов, авансовых платежей по налогам, страховых взносов, представленных в налоговый орган, - со дня представления в налоговый орган таких уведомлений, но не ранее наступления срока уплаты соответствующих налогов, сборов, авансовых платежей по налогам, страховых взносов и до дня, с которого подлежит учету совокупная обязанность на основе налоговой декларации (расчета) по соответствующим налогам, сборам, авансовым платежам по налогам, страховым взносам, указанным в уведомлении, или до дня, с которого совокупная обязанность формируется и подлежит учету на едином налоговом счете на основе сообщений об исчисленных налоговым органом суммах налогов; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n6) налоговых уведомлений - со дня наступления установленного законодательством о налогах и сборах срока уплаты соответствующего налога; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n7) сообщений об исчисленных налоговым органом суммах налогов - со дня, следующего за днем информирования налоговым органом налогоплательщика-организации (ее обособленного подразделения) о результатах рассмотрения пояснений и (или) документов, представленных в налоговый орган в соответствии с пунктом 6 статьи 363, пунктом 6 статьи 386, пунктом 5 статьи 397 настоящего Кодекса, либо со дня, следующего за днем истечения одного месяца, в случае непредставления таких пояснений и (или) документов;\n\n8) вступивших в силу решений налогового органа о предоставлении отсрочки, рассрочки по уплате налогов, сборов, страховых взносов, пеней, штрафов и (или) процентов в соответствии с главой 9 настоящего Кодекса - со дня, указанного в соответствующем решении; (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n9) решений налогового органа о привлечении к ответственности за совершение налоговых правонарушений, решений налоговых органов об отказе в привлечении к ответственности за совершение налоговых правонарушений, решений об отмене (полностью или частично) решений о возмещении суммы налога, заявленной к возмещению, в заявительном порядке, решений об отмене (полностью или частично) решений о предоставлении налогового вычета полностью или частично, решений, вынесенных по результатам проверки федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами, - со дня вступления в силу соответствующего решения, если иное не предусмотрено подпунктами 10 и 101 настоящего пункта; (В редакции  федеральных законов от 08.08.2024 № 259-ФЗ, от 31.07.2025 № 287-ФЗ)\n\n10) решений налогового органа о привлечении к ответственности за совершение налоговых правонарушений, решений налоговых органов об отказе в привлечении к ответственности за совершение налоговых правонарушений, решений об отмене (полностью или частично) решений о возмещении суммы налога, заявленной к возмещению, в заявительном порядке, решений об отмене (полностью или частично) решений о предоставлении налогового вычета, которыми установлено неисполнение обязанности по уплате налога в связи с изменением налоговым органом юридической квалификации сделки, совершенной налогоплательщиком, или статуса и характера деятельности налогоплательщика, - со дня вступления в силу соответствующего судебного акта; (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\n101) решения о привлечении к ответственности за совершение налогового правонарушения (решения об отказе в привлечении к ответственности за совершение налогового правонарушения), вынесенного налоговым органом в отношении физического лица, не являющегося индивидуальным предпринимателем, на которое указанным физическим лицом подана апелляционная жалоба, - со дня вступления в законную силу судебного акта о взыскании задолженности; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n11) судебного акта или решения вышестоящего налогового органа, отменяющего (изменяющего) судебный акт или решение налогового органа, на основании которых на едином налоговом счете ранее была учтена обязанность лица по уплате сумм налогов, авансовых платежей по налогам, сборов, страховых взносов, пеней, штрафов и (или) процентов, - на дату вступления в законную силу соответствующего судебного акта или решения;\n\n12) исполнительных документов о взыскании с лица, указанного в пункте 4 настоящей статьи, государственной пошлины - со дня выдачи судом соответствующего исполнительного документа, который для целей учета совокупной обязанности на едином налоговом счете признается установленным сроком уплаты;\n\n13) расчетов суммы налога (перерасчета ранее исчисленных сумм налога), произведенных налоговым органом в соответствии с Федеральным законом от 25 февраля 2022 года № 17-ФЗ \"О проведении эксперимента по установлению специального налогового режима \"Автоматизированная упрощенная система налогообложения\" или в соответствии с Федеральным законом от 27 ноября 2018 года № 422-ФЗ \"О проведении эксперимента по установлению специального налогового режима \"Налог на профессиональный доход\", - со дня уведомления налогоплательщика о сумме налога, подлежащего уплате, но не ранее наступления срока уплаты соответствующих налогов;\n\n14) сведений о разрешениях, выданных органами, выдающими в установленном порядке разрешения на добычу объектов животного мира и (или) разрешения на добычу (вылов) водных биологических ресурсов, - со дня представления сведений указанными органами;\n\n15) решения о признании задолженности безнадежной к взысканию и ее списании - со дня принятия соответствующего решения;\n\n16) уведомлений, представленных плательщиком торгового сбора в налоговый орган в соответствии со статьей 416 настоящего Кодекса, информации уполномоченного органа, представленной в налоговый орган в соответствии с пунктом 4 статьи 418 настоящего Кодекса, - со дня представления в налоговый орган указанных уведомлений, информации;\n\n17) иных документов, предусматривающих возникновение, изменение, прекращение обязанности по уплате налогов, сборов, страховых взносов, пеней, штрафов и (или) процентов, установленной законодательством о налогах и сборах, - не ранее наступления срока уплаты соответствующих налогов, сборов, страховых взносов, пеней, штрафов, процентов. (В редакции  Федерального закона от 28.12.2022 № 565-ФЗ)\n\n6. Сумма пеней, рассчитанная в соответствии со статьей 75 настоящего Кодекса, учитывается в совокупной обязанности со дня учета на едином налоговом счете недоимки, в отношении которой рассчитана данная сумма.\n\nСумма процентов, определяемая в соответствии со статьей 64 настоящего Кодекса, учитывается в совокупной обязанности со дня, следующего за днем уплаты последнего платежа, предусмотренного решением о предоставлении отсрочки, рассрочки, если иное не предусмотрено настоящим пунктом.\n\nВ случае представления налогоплательщиком заявления о досрочном исполнении решения о предоставлении отсрочки, рассрочки в соответствии с главой 9 настоящего Кодекса либо заявления в соответствии с абзацем третьим пункта 4 статьи 78 настоящего Кодекса сумма задолженности, в отношении которой поданы такие заявления, учитывается в совокупной обязанности последовательно начиная с задолженности с наиболее ранним сроком уплаты в размере, не превышающем положительное сальдо единого налогового счета на дату ее учета, со дня, следующего за днем представления заявления.\n\n7. При определении размера совокупной обязанности не учитываются:\n\n1) суммы налогов, сборов, страховых взносов, подлежащих уменьшению на основании налоговых деклараций (расчетов), уточненных налоговых деклараций (расчетов), предусматривающих уменьшение подлежащих уплате сумм налогов, сборов, страховых взносов, если со дня истечения установленного законодательством о налогах и сборах срока уплаты соответствующих налога, сбора, страховых взносов до дня подачи указанных налоговых деклараций (расчетов), уточненных налоговых деклараций (расчетов) прошло более трех лет, за исключением случаев осуществления налоговым органом перерасчета налогов, сборов, страховых взносов по основаниям, предусмотренным настоящим Кодексом, и случаев восстановления судом указанного срока, если причины его пропуска признаны судом уважительными; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n2) суммы налогов, государственной пошлины, в отношении уплаты которой арбитражным судом выдан исполнительный документ, иных сборов, страховых взносов, пеней, штрафов, процентов, по которым истек срок их взыскания, до даты вступления в законную силу судебного акта о восстановлении пропущенного срока либо судебного акта о взыскании таких сумм; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n3) суммы налогов, сборов, страховых взносов, пеней, штрафов, процентов, указанных в вынесенном налоговым органом решении о привлечении к ответственности за совершение налогового правонарушения или решении об отказе в привлечении к ответственности за совершение налогового правонарушения, если судом были приняты меры предварительной защиты (обеспечительные меры), в соответствии с которыми приостановлено полностью или в части действие такого оспариваемого решения налогового органа, либо если вышестоящим налоговым органом было принято решение о приостановлении исполнения такого решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения, - до дня вступления в законную силу судебного акта об отмене (замене) указанных мер предварительной защиты (обеспечительных мер) либо до дня принятия вышестоящим налоговым органом решения по соответствующей жалобе, повлекших прекращение приостановления полностью или в части действия решения налогового органа о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения;\n\n31) обжалуемые суммы налогов, сборов, страховых взносов, пеней, штрафов, процентов, указанные в решении о привлечении к ответственности за совершение налогового правонарушения (решении об отказе в привлечении к ответственности за совершение налогового правонарушения), вынесенном налоговым органом в отношении физического лица, не являющегося индивидуальным предпринимателем, в решении об отмене (полностью или частично) решения о предоставлении налогового вычета полностью или частично, обязанность по уплате которых не исполнена по состоянию на дату получения налоговым органом жалобы, - с даты получения налоговым органом такой жалобы до даты вступления в законную силу судебного акта о взыскании таких сумм; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n32) оспариваемые суммы налогов, указанные в налоговом уведомлении, обязанность по уплате которых не исполнена по состоянию на дату получения налоговым органом представленного налогоплательщиком - физическим лицом заявления о перерасчете суммы ранее исчисленного налога, - с даты получения налоговым органом такого заявления до истечения тридцати дней со дня формирования налоговым органом сообщения об отказе в перерасчете суммы ранее исчисленного налога по такому заявлению (если в течение указанного тридцатидневного срока не была подана жалоба в отношении сумм налогов, указанных в налоговом уведомлении) или до даты вступления в законную силу судебного акта о взыскании этих сумм (если данная жалоба была подана в течение указанного тридцатидневного срока).\n\nПоложения настоящего подпункта не применяются, если в отношении соответствующей суммы налога, указанной в налоговом уведомлении, налогоплательщиком - физическим лицом ранее было представлено заявление о перерасчете суммы ранее исчисленного налога и (или) была рассмотрена жалоба такого налогоплательщика - физического лица и по ней было принято решение, предусмотренное пунктом 3 статьи 140 настоящего Кодекса;\n\n(Дополнение подпунктом - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n33) обжалуемые суммы налогов, указанные в налоговом уведомлении, обязанность по уплате которых не исполнена по состоянию на дату получения налоговым органом жалобы налогоплательщика - физического лица на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, - с даты получения налоговым органом данной жалобы до истечения тридцати дней со дня принятия решения вышестоящего налогового органа об оставлении жалобы на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, без удовлетворения (если в течение указанного тридцатидневного срока налогоплательщиком - физическим лицом не было представлено уведомление о несогласии с решением вышестоящего налогового органа по данной жалобе), или до даты вступления в законную силу судебного акта о взыскании таких сумм (если в течение указанного тридцатидневного срока налогоплательщиком - физическим лицом такое уведомление было представлено), или до даты принятия решения об оставлении жалобы без рассмотрения.\n\nПоложения настоящего подпункта не применяются, если в отношении соответствующей суммы налога, указанной в налоговом уведомлении, ранее была рассмотрена жалоба налогоплательщика - физического лица и по данной жалобе было принято решение, предусмотренное пунктом 3 статьи 140 настоящего Кодекса, и (или) таким налогоплательщиком - физическим лицом было представлено заявление о перерасчете суммы ранее исчисленного налога;\n\n(Дополнение подпунктом - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n34) обжалуемые суммы налогов, сборов, страховых взносов, пеней, штрафов, процентов, указанные в решении о привлечении к ответственности за совершение налогового правонарушения (решении об отказе в привлечении к ответственности за совершение налогового правонарушения), вынесенном налоговым органом в отношении физического лица, не являющегося индивидуальным предпринимателем, в решении об отмене (полностью или частично) решения о предоставлении налогового вычета полностью или частично, и (или) суммы налогов, указанные в налоговом уведомлении, в отношении которых отсутствует судебный акт о взыскании, если налогоплательщиком - физическим лицом была подана жалоба на требование об уплате задолженности или на решение о взыскании задолженности, в размере не более суммы отрицательного сальдо единого налогового счета такого физического лица на дату получения налоговым органом данной жалобы - с даты получения налоговым органом данной жалобы до истечения пятнадцати дней со дня принятия налоговым органом решения по соответствующей жалобе; (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n4) уплаченные налогоплательщиком (плательщиком сборов, плательщиком страховых взносов) не в качестве единого налогового платежа суммы налога на профессиональный доход, сборов за пользование объектами животного мира и за пользование объектами водных биологических ресурсов, налога на сверхприбыль,   страховых взносов на дополнительное социальное обеспечение членов летных экипажей воздушных судов гражданской авиации, а также отдельных категорий работников организаций угольной промышленности. Перечни указанных в настоящем подпункте плательщиков страховых взносов устанавливаются в порядке, предусмотренном соответственно Федеральным законом от 27 нояб\n\nря 2001 года № 155-ФЗ \"О дополнительном социальном обеспечении членов летных экипажей воздушных судов гражданской авиации\" и Федеральным законом от 10 мая 2010 года № 84-ФЗ \"О дополнительном социальном обеспечении отдельных категорий работников организаций угольной промышленности\"; (В редакции  федеральных законов от 08.08.2024 № 259-ФЗ, от 29.10.2024 № 362-ФЗ)\n\n5) суммы налогов, сборов, страховых взносов, пеней, штрафов, процентов, по которым принято решение о временном (на период рассмотрения заявления о предоставлении отсрочки или рассрочки) приостановлении уплаты суммы задолженности в соответствии со статьей 64 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 28.12.2022 № 565-ФЗ)\n\n6) суммы налогов, государственной пошлины, в отношении уплаты которых арбитражным судом выдан исполнительный документ, иных сборов, страховых взносов, пеней, штрафов, процентов в иных случаях, предусмотренных законодательством Российской Федерации о налогах и сборах. (Дополнение подпунктом - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 14.07.2022 № 263-ФЗ)","article_title":"Статья 11.3. Единый налоговый платеж. Единый налоговый счет","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cc5557b12401022d23c95578052d3f17106417ea6e19496c9be896d251ea93ff"},{"code_id":"NK_RF","article_number":"113","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n1. Лицо не может быть привлечено к ответственности за совершение налогового правонарушения, если со дня его совершения либо со следующего дня после окончания налогового (расчетного) периода, в течение которого было совершено это правонарушение, и до момента вынесения решения о привлечении к ответственности истекли три года (срок давности). (В редакции федеральных законов о\n\nИсчисление срока давности со дня совершения налогового правонарушения применяется в отношении всех налоговых правонарушений, кроме предусмотренных статьями 120, 122, 1293 и 1295 настоящего Кодекса. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nИсчисление срока давности со следующего дня после окончания соответствующего налогового периода применяется в отношении налоговых правонарушений, предусмотренных статьями 120, 122, 1293 и 1295 настоящего Кодекса. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nТечение срока давности привлечения к ответственности считается приостановленным со дня составления акта, предусмотренного пунктом 3 статьи 91 настоящего Кодекса. В этом случае течение срока давности привлечения к ответственности возобновляется со дня, когда прекратили действие обстоятельства, препятствующие проведению выездной налоговой проверки, и вынесено решение о возобновлении выездной налоговой проверки.\n\n(Дополнение пунктом - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n2. (Пункт исключен - Федеральный закон от 09.07.1999 № 154-ФЗ)","article_title":"Статья 113. Срок давности привлечения к ответственности за совершение налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"279a54ce3a31f907bca4b84b924bb16575a66c1621bf4895a4221f5333788198"},{"code_id":"NK_RF","article_number":"114","version_date":"2000-07-31","article_text":"1. Налоговая санкция является мерой ответственности за совершение налогового правонарушения.","article_title":"Статья 114. Налоговые санкции","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"72c90a136e9a8ca943f04ffc1ac3cc6fb3eccfe25fd8949d33e74527d0245df4"},{"code_id":"NK_RF","article_number":"115","version_date":"2000-07-31","article_text":"(Статья утратила силу  - Федеральный закон от 14.07.2022 № 263-ФЗ)","article_title":"Статья 115. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0760e08016882ad16f11f2560e12e965f879cb6ecc2ddffa5db2aa47ff1da8b6"},{"code_id":"NK_RF","article_number":"116","version_date":"2000-07-31","article_text":"1. Нарушение налогоплательщиком установленного настоящим Кодексом срока подачи заявления о постановке на учет в налоговом органе по основаниям, предусмотренным настоящим Кодексом,\n\nвлечет взыскание штрафа в размере 10 тысяч рублей.\n\n2. Ведение деятельности организацией или индивидуальным предпринимателем без постановки на учет в налоговом органе по основаниям, предусмотренным настоящим Кодексом,\n\nвлечет взыскание штрафа в размере 10 процентов от доходов, полученных в течение указанного времени в результате такой деятельности, но не менее 40 тысяч рублей.\n\n(Статья в редакции Федерального закона от 27.07.2010 № 229-ФЗ)","article_title":"Статья 116. Нарушение порядка постановки на учет в налоговом органе","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"208f1e3fabd66978df222e0d3ae27689ea0bb4951ae7cea396bc34e0b6604a3d"},{"code_id":"NK_RF","article_number":"117","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 27.07.2010 № 229-ФЗ)","article_title":"Статья 117. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a63b4d25bb84290a5e35497b79db01d71b1135d6ac4ee2810b4bd9a8f1ccc81b"},{"code_id":"NK_RF","article_number":"118","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 02.04.2014 № 52-ФЗ)","article_title":"Статья 118. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"817aa4a29b87f49a3c1b32407aedf3a4b03e196aab8af67dfd055b5f571b5549"},{"code_id":"NK_RF","article_number":"119","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 28.11.2011 № 336-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n1. Непредставление в установленный законодательством о налогах и сборах срок налоговой декларации (расчета по страховым взносам) в налоговый орган по месту учета, расчета сумм выплаченных иностранным организациям доходов и удержанных налогов за прошедший отчетный (налоговый) период в налоговый орган по месту нахождения налогового агента\n\nвлечет взыскание штрафа в размере 5 процентов не уплаченной (не перечисленной) в установленный законодательством о налогах и сборах срок суммы налога (страховых взносов), подлежащей уплате (доплате, перечислению) на основании данной налоговой декларации (расчета), за каждый полный или неполный месяц со дня, установленного для ее представления, но не более 30 процентов указанной суммы и не менее 1000 рублей.\n\n(Пункт в редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n2. Непредставление управляющим товарищем, ответственным за ведение налогового учета, расчета финансового результата инвестиционного товарищества в налоговый орган по месту учета в установленный законодательством о налогах и сборах срок\n\nвлечет взыскание штрафа в размере 1 000 рублей за каждый полный или неполный месяц со дня, установленного для его представления.\n\n(Дополнение пунктом - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2010 № 229-ФЗ)","article_title":"Статья 119. Непредставление налоговой декларации (расчета финансового результата инвестиционного товарищества, расчета по страховым взносам)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bbc4f84083c10fe7bf7df7dbce40047295064bb96af4b48286a0ee697025a254"},{"code_id":"NK_RF","article_number":"119.1","version_date":"2000-07-31","article_text":"Несоблюдение порядка представления налоговой декларации (расчета) в электронной форме в случаях, предусмотренных настоящим Кодексом, (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nвлечет взыскание штрафа в размере 200 рублей.\n\n(Дополнение статьей - Федеральный закон от 27.07.2010 № 229-ФЗ)","article_title":"Статья 119.1. Нарушение установленного способа представления налоговой декларации (расчета)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7793a67c15712aea8da0733135dd9df8ac64848b27eebaad02d7f47a055316b7"},{"code_id":"NK_RF","article_number":"119.2","version_date":"2000-07-31","article_text":"1. Представление в налоговый орган управляющим товарищем, ответственным за ведение налогового учета, расчета финансового результата инвестиционного товарищества, содержащего недостоверные сведения,\n\nвлечет взыскание штрафа в размере сорока тысяч рублей.\n\n2. Те же деяния, совершенные умышленно,\n\nвлекут взыскание штрафа в размере восьмидесяти тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 28.11.2011 № 336-ФЗ)","article_title":"Статья 119.2. Представление в налоговый орган управляющим товарищем, ответственным за ведение налогового учета, расчета финансового результата инвестиционного товарищества, содержащего недостоверные сведения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e202ec49a8bba8b5412e56a42385a4981764ed12959362d8d50a034820559427"},{"code_id":"NK_RF","article_number":"12","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 11.06.2021 № 199-ФЗ, от 08.08.2024 № 259-ФЗ)\n\n1. В Российской Федерации устанавливаются следующие виды налогов и сборов: федеральные, региональные и местные.\n\nРегиональные налоги вводятся в действие и прекращают действовать на территориях субъектов Российской Федерации в соответствии с настоящим Кодексом и законами субъектов Российской Федерации о налогах, если иное не предусмотрено настоящим пунктом. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nПри установлении региональных налогов законодательными органами субъектов Российской Федерации определяются в порядке и пределах, которые предусмотрены настоящим Кодексом, следующие элементы налогообложения: налоговые ставки, порядок и сроки уплаты налогов, если эти элементы налогообложения не установлены настоящим Кодексом. Иные элементы налогообложения по региональным налогам и налогоплательщики определяются настоящим Кодексом. (В редакции  федеральных законов от 27.07.2010 № 229-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nЗаконодательными органами субъектов Российской Федерации законами о налогах в порядке и пределах, которые предусмотрены настоящим Кодексом, могут устанавливаться особенности определения налоговой базы, налоговые льготы, основания и порядок их применения. (В редакции  федеральных законов от 02.11.2013 № 307-ФЗ, от 08.08.2024 № 259-ФЗ)\n\nРегиональные налоги, обязательные к уплате в федеральной территории \"Сириус\", устанавливаются, вводятся в действие и прекращают действовать в указанной территории в соответствии с настоящим Кодексом. Представительным органом федеральной территории \"Сириус\" в порядке и пределах, которые предусмотрены настоящим Кодексом, могут устанавливаться налоговые льготы, основания и порядок их применения. (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nМестные налоги и сборы вводятся в действие и прекращают действовать на территориях муниципальных образований в соответствии с настоящим Кодексом и нормативными правовыми актами представительных органов муниципальных образований о налогах и сборах, если иное не предусмотрено настоящим пунктом. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nМестные налоги и сборы устанавливаются настоящим Кодексом и нормативными правовыми актами представительных органов поселений (муниципальных районов), муниципальных округов, городских округов (внутригородских районов) о налогах и сборах и обязательны к уплате на территориях соответствующих поселений (межселенных территориях), муниципальных округов, городских округов (внутригородских районов), если иное не предусмотрено пунктом 7 настоящей статьи. Местные налоги и сборы вводятся в действие и прекращают действовать на территориях поселений (межселенных территориях), муниципальных округов, городских округов (внутригородских районов) в соответствии с настоящим Кодексом и нормативными правовыми актами представительных органов поселений (муниципальных районов), муниципальных округов, городских округов (внутригородских районов) о налогах и сборах. (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nВ городском округе с внутригородским делением полномочия представительных органов муниципальных образований по установлению, введению в действие и прекращению действия местных налогов на территориях внутригородских районов осуществляются представительными органами городского округа с внутригородским делением либо представительными органами соответствующих внутригородских районов согласно закону субъекта Российской Федерации о разграничении полномочий между органами местного самоуправления городского округа с внутригородским делением и органами местного самоуправления внутригородских районов.\n\nМестные налоги и сборы в городах федерального значения Москве, Санкт-Петербурге и Севастополе устанавливаются настоящим Кодексом и законами указанных субъектов Российской Федерации о налогах и сборах, обязательны к уплате на территориях этих субъектов Российской Федерации, если иное не предусмотрено пунктом 7 настоящей статьи. Местные налоги и сборы вводятся в действие и прекращают действовать на территориях городов федерального значения Москвы, Санкт-Петербурга и Севастополя в соответствии с настоящим Кодексом и законами указанных субъектов Российской Федерации.\n\nМестные налоги и сборы в федеральной территории \"Сириус\" устанавливаются настоящим Кодексом и нормативными правовыми актами представительного органа федеральной территории \"Сириус\" о местных налогах и сборах и обязательны к уплате в указанной территории, если иное не предусмотрено пунктом 7 настоящей статьи. Местные налоги и сборы вводятся в действие и прекращают действовать в федеральной территории \"Сириус\" в соответствии с настоящим Кодексом и нормативными правовыми актами представительного органа федеральной территории \"Сириус\" о местных налогах и сборах. (Дополнение абзацем - Федеральный закон от 11.06.2021 № 199-ФЗ)\n\nПри установлении местных налогов представительными органами муниципальных образований (законодательными (представительными) органами государственной власти городов федерального значения Москвы, Санкт-Петербурга и Севастополя, представительным органом федеральной территории \"Сириус\") определяются в порядке и пределах, которые предусмотрены настоящим Кодексом, следующие элементы налогообложения: налоговые ставки, порядок и сроки уплаты налогов, если эти элементы налогообложения не установлены настоящим Кодексом. Иные элементы налогообложения по местным налогам и налогоплательщики определяются настоящим Кодексом. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nПредставительными органами муниципальных образований (законодательными (представительными) органами государственной власти городов федерального значения Москвы, Санкт-Петербурга и Севастополя, представительным органом федеральной территории \"Сириус\") в порядке и пределах, которые предусмотрены настоящим Кодексом, могут устанавливаться особенности определения налоговой базы, налоговые льготы, основания и порядок их применения. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\nПри установлении местных сборов представительными органами муниципальных образований (законодательными (представительными) органами государственной власти городов федерального значения Москвы, Санкт-Петербурга и Севастополя, представительным органом федеральной территории \"Сириус\") определяются в порядке и пределах, которые предусмотрены настоящим Кодексом, ставки сборов, а также могут устанавливаться льготы по уплате сборов, основания и порядок их применения. (В редакции Федерального закона от 11.06.2021 № 199-ФЗ)\n\n(Пункт в редакции Федерального закона от 29.11.2014 № 382-ФЗ)\n\nСпециальные налоговые режимы могут предусматривать освобождение от обязанности по уплате отдельных федеральных, региональных и местных налогов и сборов, указанных в статьях 13 - 15 настоящего Кодекса.\n\nЗаконодательные органы субъектов Российской Федерации и представительные органы муниципальных образований в случаях, порядке и пределах, которые предусмотрены настоящим Кодексом, вправе устанавливать по специальным налоговым режимам: (Дополнение абзацем - Федеральный закон от 13.07.2015 № 232-ФЗ) (В редакции  Федерального закона от 08.08.2024 № 259-ФЗ)\n\nвиды предпринимательской деятельности, в отношении которых может применяться соответствующий специальный налоговый режим; (Дополнение абзацем - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\nограничения на переход на специальный налоговый режим и на применение специального налогового режима; (Дополнение абзацем - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\nналоговые ставки в зависимости от категорий налогоплательщиков и видов предпринимательской деятельности; (Дополнение абзацем - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\nособенности определения налоговой базы; (Дополнение абзацем - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\nналоговые льготы, а также основания и порядок их применения. (Дополнение абзацем - Федеральный закон от 13.07.2015 № 232-ФЗ)\n\n(Статья в редакции Федерального закона от 29.07.2004 № 95-ФЗ)","article_title":"Статья 12. Виды налогов и сборов в Российской Федерации. Полномочия законодательных органов субъектов Российской Федерации, представительных органов муниципальных образований, представительного органа федеральной территории \"Сириус\" по установлению налогов и сборов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"08f4dd9dc15c143ca7e1aa2dc4046c736f9bc85f6cf67c7d3e52c104a3ab7ab3"},{"code_id":"NK_RF","article_number":"120","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nвлечет взыскание штрафа в размере десяти тысяч рублей. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nвлекут взыскание штрафа в размере тридцати тысяч рублей. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nвлекут взыскание штрафа в размере двадцати процентов от суммы неуплаченного налога (страховых взносов), но не менее сорока тысяч рублей. (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nПод грубым нарушением правил учета доходов и расходов и объектов налогообложения для целей настоящей статьи понимается отсутствие первичных документов, или отсутствие счетов-фактур, или регистров бухгалтерского учета или налогового учета, систематическое (два раза и более в течение календарного года) несвоевременное или неправильное отражение на счетах бухгалтерского учета, в регистрах налогового учета и в отчетности хозяйственных операций, денежных средств, материальных ценностей, нематериальных активов и финансовых вложений. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2010 № 229-ФЗ; от 23.07.2013 № 248-ФЗ)","article_title":"Статья 120. Грубое нарушение правил учета доходов и расходов и объектов налогообложения (базы для исчисления страховых взносов)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e43d8c04ca44a2fbf422088aea9de698abb4bb00094195bb5380ad52b2a390ee"},{"code_id":"NK_RF","article_number":"121","version_date":"2000-07-31","article_text":"(Статья исключена - Федеральный закон от 09.07.1999 № 154-ФЗ)","article_title":"Статья 121. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eae2ab0dd7a6c8944f2c6b85e6302d187e64cbff9e97fe9c4271b2d8c4098eca"},{"code_id":"NK_RF","article_number":"122","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nвлечет взыскание штрафа в размере 20 процентов от неуплаченной суммы налога (сбора, страховых взносов). (В редакции федеральных законов от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nвлекут взыскание штрафа в размере 40 процентов от неуплаченной суммы налога (сбора, страховых взносов). (В редакции федеральных законов от 27.07.2006 № 137-ФЗ; от 03.07.2016 № 243-ФЗ)","article_title":"Статья 122. Неуплата или неполная уплата сумм налога (сбора, страховых взносов)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b631aac9d1d989d5d425c405b98b53d497e8627edcd649a7b188af1206a8c6c3"},{"code_id":"NK_RF","article_number":"122.1","version_date":"2000-07-31","article_text":"1. Сообщение участником консолидированной группы налогоплательщиков ответственному участнику этой группы недостоверных данных (несообщение данных), приведшее к неуплате или неполной уплате налога на прибыль организаций по консолидированной группе налогоплательщиков ее ответственным участником, влечет взыскание штрафа в размере 20 процентов от неуплаченной суммы налога.\n\n2. Деяния, предусмотренные пунктом 1 настоящей статьи, совершенные умышленно, влекут взыскание штрафа в размере 40 процентов от неуплаченной суммы налога.\n\n(Дополнение статьей - Федеральный закон от 16.11.2011 № 321-ФЗ)","article_title":"Статья 122.1. Сообщение участником консолидированной группы налогоплательщиков ответственному участнику этой группы недостоверных данных (несообщение данных), приведшее к неуплате или неполной уплате налога на прибыль организаций ответственным участником","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86a8692dab9ef661afe2f269e4ee80b6089c8b558788ffdd72dff209e1d0e320"},{"code_id":"NK_RF","article_number":"123","version_date":"2000-07-31","article_text":"влечет взыскание штрафа в размере 20 процентов от суммы, подлежащей удержанию и (или) перечислению. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2010 № 229-ФЗ)\n\nналоговый расчет (расчет по налогу) представлен в налоговый орган в установленный срок;\n\nв налоговом расчете (расчете по налогу) отсутствуют факты неотражения или неполноты отражения сведений и (или) ошибки, приводящие к занижению суммы налога, подлежащей перечислению в бюджетную систему Российской Федерации;\n\nналоговым агентом исполнена обязанность по перечислению суммы налога до момента, когда ему стало известно об обнаружении налоговым органом факта несвоевременного перечисления суммы налога или о назначении выездной налоговой проверки по такому налогу за соответствующий налоговый период. (В редакции  федеральных законов от 14.07.2022 № 263-ФЗ, от 28.12.2022 № 565-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 27.12.2018 № 546-ФЗ)","article_title":"Статья 123. Невыполнение налоговым агентом обязанности по удержанию и (или) перечислению налогов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"593dcacb8bab6cc9cb9d13b95c64232913024a1e817ea5a4f32f0f96218c5118"},{"code_id":"NK_RF","article_number":"124","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 30.12.2001 № 196-ФЗ)","article_title":"Статья 124. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cc4ce31e87bfcb0ccac499eed86987b89e67aee9c4cb7fe6607cab50b562b415"},{"code_id":"NK_RF","article_number":"125","version_date":"2000-07-31","article_text":"(Наименование в редакции федеральных законов от 27.07.2010 № 229-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nНесоблюдение установленного настоящим Кодексом порядка владения, пользования и (или) распоряжения имуществом, на которое наложен арест или в отношении которого налоговым органом приняты обеспечительные меры в виде залога либо в виде запрета на отчуждение (передачу в залог) имущества лица без согласия налогового органа, (В редакции  федеральных законов от 09.07.1999 № 154-ФЗ, от 27.07.2010 № 229-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nвлечет взыскание штрафа в размере 30 тысяч рублей. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)","article_title":"Статья 125. Несоблюдение порядка владения, пользования и (или) распоряжения имуществом, на которое наложен арест или в отношении которого налоговым органом приняты обеспечительные меры в виде залога либо в виде запрета на отчуждение (передачу в залог) имущества лица без согласия налогового органа","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0232d13a423d2533639ab045247c67ddd4d5d74b68aacad932a94d3261b700f3"},{"code_id":"NK_RF","article_number":"126","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nвлечет взыскание штрафа в размере 200 рублей за каждый непредставленный документ. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\n11. Непредставление налоговому органу документов, подтверждающих размер прибыли (убытка) контролируемой иностранной компании, в срок, установленный пунктом 5 статьи 2515 настоящего Кодекса, либо представление таких документов с заведомо недостоверными сведениями\n\nвлечет взыскание штрафа с контролирующего лица в размере 500 000 рублей.\n\n(Дополнение пунктом - Федеральный закон от 24.11.2014 № 376-ФЗ) (В редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\n11-1. Непредставление налоговому органу документов, истребуемых в соответствии с пунктом 1 статьи 2514-1 настоящего Кодекса, в срок, установленный пунктом 2 статьи 2514-1 настоящего Кодекса, либо представление таких документов с заведомо недостоверными сведениями\n\nвлечет взыскание штрафа с контролирующего лица в размере 1 миллиона рублей.\n\n(Дополнение пунктом - Федеральный закон от 09.11.2020 № 368-ФЗ)\n\n12. Непредставление налоговым агентом в установленный срок расчета сумм налога на доходы физических лиц, исчисленных и удержанных налоговым агентом, в налоговый орган по месту учета\n\nвлечет взыскание штрафа с налогового агента в размере 1 000 рублей за каждый полный или неполный месяц со дня, установленного для его представления.\n\n(Дополнение пунктом - Федеральный закон от 02.05.2015 № 113-ФЗ)\n\nвлечет взыскание штрафа с организации или индивидуального предпринимателя в размере десяти тысяч рублей, с физического лица, не являющегося индивидуальным предпринимателем, - в размере одной тысячи рублей. (В редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\n1) в отношении налогоплательщика, являющегося контролирующим лицом указанной иностранной компании, действовали введенные иностранными государствами, экономическими, политическими, военными или иными объединениями стран, международными финансовыми и иными организациями запретительные, ограничительные и (или) иные аналогичные меры, заключающиеся в установлении запретов и (или) ограничений на предоставление такому налогоплательщику в отношении указанной иностранной компании документов, предусмотренных подпунктом 1 пункта 5 статьи 2515 настоящего Кодекса;\n\n2) постоянным местонахождением указанной иностранной компании являлось иностранное государство, включенное в соответствии с законодательством Российской Федерации в перечень иностранных государств и территорий, совершающих в отношении Российской Федерации, российских юридических и физических лиц недружественные действия.\n\n(Дополнение пунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)","article_title":"Статья 126. Непредставление налоговому органу сведений, необходимых для осуществления налогового контроля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eddb13ebe97f16eba1a0e56faa7a36efa98cfead6c8bac59f82d0575d21cb438"},{"code_id":"NK_RF","article_number":"126.1","version_date":"2000-07-31","article_text":"у документов, содержащих недостоверные сведения\n\nвлечет взыскание штрафа в размере 500 рублей за каждый представленный документ, содержащий недостоверные сведения.\n\n(Дополнение статьей - Федеральный закон от 02.05.2015 № 113-ФЗ)","article_title":"Статья 126.1. Представление налоговым агентом налоговому орган","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e1283e26c9d38fe3c3e246509e35d42644f421010999f561703c85e385f8ab5b"},{"code_id":"NK_RF","article_number":"126.2","version_date":"2000-07-31","article_text":"1. Представление налоговым агентом и (или) негосударственным пенсионным фондом налоговому органу недостоверных сведений о факте открытия индивидуального инвестиционного счета налогоплательщика, о факте заключения договора негосударственного пенсионного обеспечения и (или) договора долгосрочных сбережений, о суммах денежных средств, внесенных налогоплательщиком на такой индивидуальный инвестиционный счет за соответствующий налоговый период, о суммах фактических взносов налогоплательщика по договору негосударственного пенсионного обеспечения, договору долгосрочных сбережений в рамках процедуры получения налогоплательщиком инвестиционных налоговых вычетов и (или) налоговых вычетов на долгосрочные сбережения граждан в порядке, установленном статьей 2211 настоящего Кодекса,\n\nвлечет взыскание штрафа в размере 20 процентов от суммы налога, неправомерно полученного налогоплательщиком в связи с предоставлением инвестиционного налогового вычета и (или) налогового вычета на долгосрочные сбережения граждан в упрощенном порядке на основании представленных налоговым агентом и (или) негосударственным пенсионным фондом недостоверных сведений.\n\n2. Налоговый агент и (или) негосударственный пенсионный фонд освобождаются от ответственности, предусмотренной пунктом 1 настоящей статьи, в случае, если ими самостоятельно выявлены ошибки и уточненные сведения представлены налоговому органу до момента, когда налоговый агент и (или) негосударственный пенсионный фонд узнали об обнаружении налоговым органом недостоверности представленных налоговым агентом и (или) негосударственным пенсионным фондом сведений.\n\n(Дополнение статьей - Федеральный закон от 20.04.2021 № 100-ФЗ) (В редакции  Федерального закона от 23.03.2024 № 58-ФЗ)","article_title":"Статья 126.2. Представление налоговым агентом и (или) негосударственным пенсионным фондом налоговому органу недостоверных сведений в рамках процедуры получения налогоплательщиками инвестиционных налоговых вычетов и (или) налоговых вычетов на долгосрочные сбережения граждан в упрощенном порядке","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0c6335416633bbdbebed6636465166044beba686995922b3f8845b792176c03"},{"code_id":"NK_RF","article_number":"126.3","version_date":"2000-07-31","article_text":"1. Представление организациями и индивидуальными предпринимателями, указанными в абзаце первом пункта 31 статьи 2211 настоящего Кодекса, налоговому органу недостоверных сведений о фактических произведенных налогоплательщиком расходах за оказанные услуги, содержащихся в документах, указанных в абзаце четвертом подпункта 2, абзацах восьмом и десятом подпункта 3, абзаце втором подпункта 4 и абзаце девятом подпункта 7 пункта 1 статьи 219 настоящего Кодекса, в рамках процедуры получения налогоплательщиком социальных налоговых вычетов в порядке, установленном статьей 2211 настоящего Кодекса,\n\nвлечет взыскание штрафа в размере 20 процентов от суммы налога, неправомерно полученного налогоплательщиком в связи с предоставлением социального налогового вычета в упрощенном порядке на основании представленных организациями и индивидуальными предпринимателями недостоверных сведений.\n\n2. Организации и индивидуальные предприниматели освобождаются от ответственности, предусмотренной пунктом 1 настоящей статьи, в случае, если ими самостоятельно выявлены ошибки и уточненные документы, указанные в абзаце четвертом подпункта 2, абзацах восьмом и десятом подпункта 3, абзаце втором подпункта 4 и абзаце девятом подпункта 7 пункта 1 статьи 219 настоящего Кодекса, представлены налоговому органу до момента, когда соответствующие организации и индивидуальные предприниматели узнали об обнаружении налоговым органом недостоверности представленных сведений.\n\n(Дополнение статьей - Федеральный закон от 31.07.2023 № 389-ФЗ)","article_title":"Статья 126.3. Представление организациями (индивидуальными предпринимателями) налоговому органу недостоверных сведений для целей получения налогоплательщиками социальных налоговых вычетов в упрощенном порядке","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd45ee2d86efe542501b5ee8bdec8a9f68315927456a2a2e32d8b9de2ede51db"},{"code_id":"NK_RF","article_number":"127","version_date":"2000-07-31","article_text":"(Статья исключена - Федеральный закон от 09.07.1999 № 154-ФЗ)","article_title":"Статья 127. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eae2ab0dd7a6c8944f2c6b85e6302d187e64cbff9e97fe9c4271b2d8c4098eca"},{"code_id":"NK_RF","article_number":"128","version_date":"2000-07-31","article_text":"Неявка либо уклонение от явки без уважительных причин лица, вызываемого по делу о налоговом правонарушении в качестве свидетеля,\n\nвлечет взыскание штрафа в размере тысячи рублей. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\nНеправомерный отказ свидетеля от дачи показаний, а равно дача заведомо ложных показаний (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\nвлечет взыскание штрафа в размере трех тысяч рублей. (В редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 128. Ответственность свидетеля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a9f76889437825b75c894733a29a4403c17fb6514f7f38b503bd2fcbba4068d2"},{"code_id":"NK_RF","article_number":"129","version_date":"2000-07-31","article_text":"влечет взыскание штрафа в размере 500 рублей.\n\nвлечет взыскание штрафа в размере 5000 рублей. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)","article_title":"Статья 129. Отказ эксперта, переводчика или специалиста от участия в проведении налоговой проверки, дача заведомо ложного заключения или осуществление заведомо ложного перевода","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5cdb299b7f14caf171c6f788f15ab08bf4b8ec09ccc2a1e5d3e5c35164b31cc8"},{"code_id":"NK_RF","article_number":"129.1","version_date":"2000-07-31","article_text":"влечет взыскание штрафа в размере 5000 рублей. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nвлекут взыскание штрафа в размере 20000 рублей. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nвлечет взыскание штрафа в размере 50 000 рублей.\n\n(Дополнение пунктом - Федеральный закон от 24.11.2014 № 376-ФЗ) (В редакции Федерального закона от 20.04.2021 № 100-ФЗ)\n\nвлечет взыскание штрафа в размере 20 процентов от неуплаченной суммы налога в отношении объекта недвижимого имущества и (или) транспортного средства, по которым не представлено (несвоевременно представлено) сообщение, предусмотренное пунктами 21 и 22 статьи 23 настоящего Кодекса. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 02.04.2014 № 52-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ)","article_title":"Статья 129.1. Неправомерное несообщение сведений налоговому органу","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0dac129d2f6c33bad7d188184a6b220aba51af9c02fa3efed41a293e4373d43b"},{"code_id":"NK_RF","article_number":"129.10","version_date":"2000-07-31","article_text":"Неправомерное непредставление в установленный срок странового отчета или представление странового отчета, содержащего недостоверные сведения,\n\nвлечет взыскание штрафа в размере 1 000 000 рублей. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 27.11.2017 № 340-ФЗ)","article_title":"Статья 129.10. Непредставление странового отчета, представление странового отчета, содержащего недостоверные сведения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4a2b77bab6968c36be1d52ef96ad14d038757e4cfe7364c1d56f148fae135173"},{"code_id":"NK_RF","article_number":"129.11","version_date":"2000-07-31","article_text":"ельщика страховых взносов или налогового агента, но не более суммы задолженности, а при отсутствии задолженности - в размере 20 тысяч рублей. (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nвлечет взыскание штрафа в размере одной стопятидесятой ставки рефинансирования Центрального банка Российской Федерации, но не более 0,2 процента за каждый календарный день просрочки.\n\nвлечет взыскание штрафа в размере 30 процентов не поступившей в результате таких действий суммы.\n\nвлекут взыскание штрафа в размере 10 тысяч рублей.\n\n(Дополнение статьей - Федеральный закон от 27.06.2011 № 162-ФЗ)","article_title":"Статья 129.11. Непредставление документации в отношении  международной группы компаний,  документации относительно конкретной сделки  (группы однородных сделок), непредставление сведений (представление недостоверных сведений) из консолидированной финансовой отчетности международной группы компаний, финансовой отчетности участника международной группы компаний","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b4aa2e8c6261e9a20f3d8a33fccbc06026f957201e5216f0362d44349172f776"},{"code_id":"NK_RF","article_number":"129.2","version_date":"2000-07-31","article_text":"влечет взыскание штрафа в трехкратном размере ставки налога на игорный бизнес, установленной для соответствующего объекта налогообложения.\n\nвлекут взыскание штрафа в шестикратном размере ставки налога на игорный бизнес, установленной для соответствующего объекта налогообложения.\n\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 129.2. Нарушение порядка регистрации объектов игорного бизнеса","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"84f226beb122e516ccd895b6863191d37874cd9f63dd33486c9ae899f694c944"},{"code_id":"NK_RF","article_number":"129.3","version_date":"2000-07-31","article_text":"влечет взыскание штрафа в размере неуплаченной суммы налога с дохода, указанного в абзаце первом пункта 61 статьи 1053 настоящего Кодекса, но не менее 500 000 рублей. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n12. Неуплата или неполная уплата налогоплательщиком сумм налога в результате применения в целях налогообложения в сделках, признаваемых контролируемыми сделками в соответствии с пунктом 2 статьи 10514 настоящего Кодекса, коммерческих и (или) финансовых условий, не сопоставимых с коммерческими и (или) финансовыми условиями сделок между лицами, не являющимися взаимозависимыми,\n\nвлечет взыскание штрафа в размере 40 процентов от неуплаченной суммы налога, но не менее 30 000 рублей.\n\n(Дополнение пунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 18.07.2011 № 227-ФЗ)","article_title":"Статья 129.3. Неуплата или неполная уплата сумм налога в результате применения в целях налогообложения в контролируемых сделках коммерческих и (или) финансовых условий, не сопоставимых с коммерческими и (или) финансовыми условиями сделок между лицами, не являющимися взаимозависимыми","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"afab4ed55a0f23788ddab1e5e2c6a9d383ad739c496d7da261f17d23c87a6fdf"},{"code_id":"NK_RF","article_number":"129.4","version_date":"2000-07-31","article_text":"Неправомерное непредставление в установленный срок налогоплательщиком в налоговый орган уведомления о контролируемых сделках, совершенных в календарном году, или представление налогоплательщиком в налоговый орган уведомления о контролируемых сделках, содержащего недостоверные сведения,\n\nвлечет взыскание штрафа в размере 100 000 рублей. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 18.07.2011 № 227-ФЗ)","article_title":"Статья 129.4. Неправомерное непредставление уведомления о контролируемых сделках, представление недостоверных сведений в уведомлении о контролируемых сделках","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"75ccd69ae3ad544fc68d588b67276f77e9726fd6db4eb77339b8242e82762def"},{"code_id":"NK_RF","article_number":"129.5","version_date":"2000-07-31","article_text":"Неуплата или неполная уплата контролирующим лицом, являющимся налогоплательщиком - физическим лицом или организацией, сумм налога в результате невключения в налоговую базу доли прибыли контролируемой иностранной компании\n\nвлечет взыскание штрафа в размере 20 процентов от суммы неуплаченного налога в отношении прибыли контролируемой иностранной компании, подлежащей включению в налоговую базу по налогу на доходы физических лиц для контролирующих лиц, являющихся налогоплательщиками - физическими лицами, налоговую базу по налогу на прибыль организаций для контролирующих лиц, являющихся налогоплательщиками - организациями, но не менее 100 000 рублей.\n\n(Дополнение статьей - Федеральный закон от 24.11.2014 № 376-ФЗ)","article_title":"Статья 129.5. Неуплата или неполная уплата сумм налога в результате невключения в налоговую базу доли прибыли контролируемой иностранной компании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ad5064105af2cf6a8cf8a7d9e9400543d197b23ad9cd09a7de6f96b32790416"},{"code_id":"NK_RF","article_number":"129.6","version_date":"2000-07-31","article_text":"1. Неправомерное непредставление в установленный срок контролирующим лицом в налоговый орган уведомления о контролируемых иностранных компаниях за календарный год или представление контролирующим лицом в налоговый орган уведомления о контролируемых иностранных компаниях, содержащего недостоверные сведения,\n\nвлечет взыскание штрафа в размере 500 000 рублей по каждой контролируемой иностранной компании, сведения о которой не представлены либо в отношении которой представлены недостоверные сведения. (В редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\n2. Неправомерное непредставление в установленный срок налогоплательщиком в налоговый орган уведомления об участии в иностранных организациях или представление уведомления об участии в иностранных организациях, содержащего недостоверные сведения,\n\nвлечет взыскание штрафа в размере 50 000 рублей в отношении каждой иностранной организации, сведения о которой не представлены либо в отношении которой представлены недостоверные сведения.\n\n(Дополнение статьей - Федеральный закон от 24.11.2014 № 376-ФЗ)","article_title":"Статья 129.6. Неправомерное непредставление уведомления о контролируемых иностранных компаниях, уведомления об участии в иностранных организациях, представление недостоверных сведений в уведомлении о контролируемых иностранных компаниях, уведомлении об участии в иностранных организациях","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2dcafaa185a16d34c36406f374c95b68e4596f2684758302b13f2b28c7b2bc83"},{"code_id":"NK_RF","article_number":"129.7","version_date":"2000-07-31","article_text":"1. Непредставление в установленный срок организацией финансового рынка информации, предусмотренной пунктом 1 статьи 1422 настоящего Кодекса,\n\nвлечет взыскание штрафа в размере 300 000 рублей.\n\n2. Невключение организацией финансового рынка информации в отношении отдельного клиента, выгодоприобретателя и (или) лиц, прямо или косвенно их контролирующих, предусмотренной абзацем первым пункта 1 статьи 1422 настоящего Кодекса, в состав информации, представляемой в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов,\n\nвлечет взыскание штрафа в размере 50 000 рублей за каждый факт такого нарушения.\n\n3. Представление организацией финансового рынка неполной или недостоверной информации, предусмотренной абзацем первым пункта 1 статьи 1422 настоящего Кодекса,\n\nвлечет взыскание штрафа в размере 25 000 рублей за каждый факт такого нарушения.\n\n4. Деяние, предусмотренное пунктом 2 или 3 настоящей статьи, совершенное умышленно (в том числе в результате нарушения запретов, установленных пунктом 21 статьи 1422 и пунктом 21 статьи 1424 настоящего Кодекса),\n\nвлечет взыскание штрафа в размере 100 000 рублей за каждый факт такого нарушения.\n\n5. Организация финансового рынка освобождается от ответственности, предусмотренной пунктами 2 и 3 настоящей статьи, если совершение ею налогового правонарушения обусловлено совершением клиентом организации финансового рынка деяния, предусмотренного статьей 1297-1 настоящего Кодекса. Положения настоящего пункта применяются при отсутствии признаков налогового правонарушения, предусмотренного статьей 1298 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 27.11.2017 № 340-ФЗ) (В редакции Федерального закона от 29.11.2021 № 380-ФЗ)","article_title":"Статья 129.7. Непредставление (невключение) организацией финансового рынка информации либо представление ею неполной или недостоверной информации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"69d4ad91c9ba271a2b54de7a19d1982b1793c617f7b0651eddb16c46a5b92fdf"},{"code_id":"NK_RF","article_number":"129.7-1","version_date":"2000-07-31","article_text":"1. Представление клиентом организации финансового рынка неполной или недостоверной информации в отношении самого себя, выгодоприобретателя и (или) лиц, прямо или косвенно их контролирующих, запрашиваемой организацией финансового рынка в соответствии со статьей 1424 настоящего Кодекса,\n\nвлечет взыскание штрафа с клиента организации финансового рынка - физического лица в размере 10 000 рублей, с клиента организации финансового рынка - юридического лица в размере 25 000 рублей за каждый факт такого нарушения в отношении каждого заключенного между клиентом и организацией финансового рынка договора, предусматривающего оказание финансовых услуг.\n\n2. Деяние, предусмотренное пунктом 1 настоящей статьи, совершенное умышленно,\n\nвлечет взыскание штрафа с клиента организации финансового рынка - физического лица в размере 20 000 рублей, с клиента организации финансового рынка - юридического лица в размере 50 000 рублей за каждый факт такого нарушения в отношении каждого заключенного между клиентом и организацией финансового рынка договора, предусматривающего оказание финансовых услуг.\n\n(Дополнение статьей - Федеральный закон от 29.11.2021 № 380-ФЗ)","article_title":"Статья 129.7-1. Представление клиентом организации финансового рынка неполной или недостоверной информации, запрашиваемой организацией финансового рынка","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"728b04f7520b6bd2291a13e18d417942b279651a10a76075ad5da751028c7bc1"},{"code_id":"NK_RF","article_number":"129.8","version_date":"2000-07-31","article_text":"Нарушение организацией финансового рынка порядка установления налогового резидентства клиентов организации финансового рынка, выгодоприобретателей и лиц, прямо или косвенно их контролирующих, путем непринятия мер, установленных статьей 1424 настоящего Кодекса,\n\nвлечет взыскание штрафа в размере 50 000 рублей за непринятие мер в отношении каждого клиента, выгодоприобретателя либо лица, прямо или косвенно их контролирующего.\n\n(Дополнение статьей - Федеральный закон от 27.11.2017 № 340-ФЗ)","article_title":"Статья 129.8. Нарушение организацией финансового рынка порядка установления налогового резидентства клиентов организаций финансового рынка, выгодоприобретателей и лиц, прямо или косвенно их контролирующих","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c19a447cccd87f8c78c07b0450bd24f8087e8cc8fb24acf2e425f6d3206c1de0"},{"code_id":"NK_RF","article_number":"129.9","version_date":"2000-07-31","article_text":"Неправомерное непредставление в установленный срок уведомления об участии в международной группе компаний или представление уведомления об участии в международной группе компаний, содержащего недостоверные сведения,\n\nвлечет взыскание штрафа в размере 500 000 рублей за каждый факт такого нарушения. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 27.11.2017 № 340-ФЗ)","article_title":"Статья 129.9. Непредставление уведомления об участии в международной группе компаний, представление уведомления об участии в международной группе компаний, содержащего недостоверные сведения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"41a836b2e48bf3a8f0b38c147e7e0fac73d952b4c8680b3e3499f987cfa9ebb3"},{"code_id":"NK_RF","article_number":"13","version_date":"2000-07-31","article_text":"К федеральным налогам и сборам относятся:\n\n1) налог на добавленную стоимость;\n\n2) акцизы;\n\n3) налог на доходы физических лиц;\n\n4) (Пункт утратил силу - Федеральный закон от 24.07.2009 № 213-ФЗ)\n\n5) налог на прибыль организаций;\n\n6) налог на добычу полезных ископаемых;\n\n7) (Пункт утратил силу - Федеральный закон от 01.07.2005 № 78-ФЗ)\n\n8) водный налог;\n\n9) сборы за пользование объектами животного мира и за пользование объектами водных биологических ресурсов;\n\n10) государственная пошлина;\n\n11) налог на дополнительный доход от добычи углеводородного сырья; (Дополнение пунктом - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\n12) налог на сверхприбыль. (Дополнение пунктом - Федеральный закон от 04.08.2023 № 415-ФЗ)\n\n(Статья в редакции Федерального закона от 29.07.2004 № 95-ФЗ)","article_title":"Статья 13. Федеральные налоги и сборы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"edf2611947f417c598339145075fbc29a579f6a2c9129ec95b1f0e2d800651f0"},{"code_id":"NK_RF","article_number":"135.3","version_date":"2000-07-31","article_text":"1. Представление банком налоговому органу недостоверных сведений о фактически произведенных налогоплательщиком расходах на новое строительство либо приобретение на территории Российской Федерации одного или нескольких объектов недвижимого имущества, указанных в подпункте 3 пункта 1 статьи 220 настоящего Кодекса, и (или) на погашение процентов, предусмотренных подпунктом 4 пункта 1 статьи 220 настоящего Кодекса, в рамках процедуры получения налогоплательщиком имущественных налоговых вычетов в порядке, установленном статьей 2211 настоящего Кодекса,\n\nвлечет взыскание штрафа в размере 20 процентов от суммы налога, неправомерно полученного налогоплательщиком в связи с предоставлением имущественного налогового вычета в упрощенном порядке на основании представленных банком недостоверных сведений.\n\n2. Банк освобождается от ответственности, предусмотренной пунктом 1 настоящей статьи, в случае, если им самостоятельно выявлены ошибки и уточненные сведения представлены налоговому органу до момента, когда банк узнал об обнаружении налоговым органом недостоверности представленных банком сведений.\n\n(Дополнение статьей - Федеральный закон от 20.04.2021 № 100-ФЗ)","article_title":"Статья 135.3. Представление банком налоговому органу недостоверных сведений в рамках процедуры получения налогоплательщиками имущественных налоговых вычетов в упрощенном порядке","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aa6462ef131585d0de99e5bf5bb7aad92273aadf35a24186c444cacd1fc92c6f"},{"code_id":"NK_RF","article_number":"135.4","version_date":"2000-07-31","article_text":"Непредставление банком, находящимся на территории Российской Федерации, либо Центральным банком Российской Федерации, либо государственной корпорацией \"Агентство по страхованию вкладов\" в отношении банков (в случае, если указанная государственная корпорация осуществляет функции временной администрации или полномочия конкурсного управляющего (ликвидатора) банка) налоговому органу в установленный срок информации о суммах выплаченных процентов по вкладам (остаткам на счетах), предусмотренной статьей 2142 настоящего Кодекса, в отношении каждого физического лица\n\nвлечет взыскание штрафа в размере 1000 рублей за каждый случай непредставления информации в отношении физического лица в установленный срок.\n\n(Дополнение статьей - Федеральный закон от 08.08.2024 № 259-ФЗ)","article_title":"Статья 135.4. Непредставление банком, находящимся на территории Российской Федерации, либо Центральным банком Российской Федерации, либо государственной корпорацией \"Агентство по страхованию вкладов\" в отношении банков (в случае, если указанная государственная корпорация осуществляет функции временной администрации или полномочия конкурсного управляющего (ликвидатора) банка) информации о суммах выплаченных процентов по вкладам (остаткам на счетах)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f40fb04ef5ccdc9991b85c0baae3f2977d8b4456cc2649f059fabaa6a924bd39"},{"code_id":"NK_RF","article_number":"136","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 19.12.2023 № 610-ФЗ)\n\nШтрафы, указанные в статьях 132 - 1353, взыскиваются в порядке, аналогичном предусмотренному настоящим Кодексом порядку взыскания санкций за налоговые правонарушения. (В редакции Федерального закона от 20.04.2021 № 100-ФЗ)\n\n(Статья в редакции Федерального закона от 27.06.2011 № 162-ФЗ)","article_title":"Статья 136. Порядок взыскания с банков, оператора платформы цифрового рубля штрафов и пеней","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"545f081c3d8f5843ed4a6f4ac1f06bd46542700c23ae64dc676761827ea07b6c"},{"code_id":"NK_RF","article_number":"137","version_date":"2000-07-31","article_text":"Каждое лицо имеет право обжаловать акты налоговых органов ненормативного характера, действия или бездействие их должностных лиц, если, по мнению этого лица, такие акты, действия или бездействие нарушают его права. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2006 № 137-ФЗ; от 23.07.2013 № 248-ФЗ)\n\nНормативные правовые акты налоговых органов могут быть обжалованы в порядке, предусмотренном федеральным законодательством.","article_title":"Статья 137. Право на обжалование","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"af46bfa9868c5922bffa207c8f1828a0fe860dc01a898a4c21e358e184ab5b0f"},{"code_id":"NK_RF","article_number":"138","version_date":"2000-07-31","article_text":"1. Акты налоговых органов ненормативного характера, действия или бездействие их должностных лиц могут быть обжалованы в вышестоящий налоговый орган и (или) в суд в порядке, предусмотренном настоящим Кодексом и соответствующим процессуальным законодательством Российской Федерации.\n\nЖалобой признается обращение лица в налоговый орган, предметом которого является обжалование вступивших в силу актов налогового органа ненормативного характера, действий или бездействия его должностных лиц, если, по мнению этого лица, обжалуемые акты, действия или бездействие должностных лиц налогового органа нарушают его права.\n\nАпелляционной жалобой признается обращение лица в налоговый орган, предметом которого является обжалование не вступившего в силу решения налогового органа о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения, вынесенного в соответствии со статьей 101 настоящего Кодекса, если, по мнению этого лица, обжалуемое решение нарушает его права.\n\n2. Акты налоговых органов ненормативного характера, действия или бездействие их должностных лиц (за исключением актов ненормативного характера, принятых по итогам рассмотрения жалоб, апелляционных жалоб, актов ненормативного характера федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, действий или бездействия его должностных лиц) могут быть обжалованы в судебном порядке только после их обжалования в вышестоящий налоговый орган в порядке, предусмотренном настоящим Кодексом.\n\nВ случае, если решение по жалобе (апелляционной жалобе) не принято вышестоящим налоговым органом в сроки, установленные пунктом 6 статьи 140 настоящего Кодекса, акты налоговых органов ненормативного характера, действия или бездействие их должностных лиц могут быть обжалованы в судебном порядке.\n\nАкты налоговых органов ненормативного характера, принятые по итогам рассмотрения жалоб (апелляционных жалоб), могут быть обжалованы в вышестоящий налоговый орган и (или) в судебном порядке.\n\nАкты ненормативного характера федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, действия или бездействие его должностных лиц обжалуются в судебном порядке.\n\nИсковое заявление, содержащее требование имущественного характера, возникшее в результате реализации актов налоговых органов (за исключением федерального органа исполнительной власти, уполномоченного по контролю и надзору в сфере налогов и сборов) ненормативного характера, в результате действий или бездействия их должностных лиц, может быть подано в суд только после обжалования указанных актов, действий или бездействия в вышестоящий налоговый орган в порядке, предусмотренном настоящим Кодексом. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n3. В случае обжалования в судебном порядке актов налоговых органов ненормативного характера, действий или бездействия их должностных лиц (за исключением актов ненормативного характера, принятых по итогам рассмотрения жалоб, апелляционных жалоб, актов ненормативного характера федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, действий или бездействия его должностных лиц) срок для обращения в суд исчисляется со дня, когда лицу стало известно о принятом вышестоящим налоговым органом решении по соответствующей жалобе, или со дня истечения срока принятия решения по жалобе (апелляционной жалобе), установленного пунктом 6 статьи 140 настоящего Кодекса.\n\n4. Обжалование организациями и физическими лицами в судебном порядке актов (в том числе нормативных) налоговых органов, действий или бездействия их должностных лиц производится в порядке, предусмотренном соответствующим процессуальным законодательством Российской Федерации.\n\nВ случае обжалования в судебном порядке актов налоговых органов, действий их должностных лиц исполнение обжалуемых актов, совершение обжалуемых действий могут быть приостановлены судом в порядке, предусмотренном соответствующим процессуальным законодательством Российской Федерации.\n\nЗаявление о приостановлении исполнения обжалуемого решения полностью или частично подается одновременно с жалобой на вступившее в силу решение о привлечении к ответственности за совершение налогового правонарушения или решение об отказе в привлечении к ответственности за совершение налогового правонарушения. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nНалоговый орган, вынесший обжалуемое решение, обязан в течение трех дней со дня поступления банковской гарантии уведомить о данном факте вышестоящий налоговый орган, рассматривающий жалобу. Требования к банковской гарантии и порядок ее представления гарантом устанавливаются в соответствии со статьей 741 настоящего Кодекса с учетом следующих особенностей: (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nсрок действия банковской гарантии должен истекать не ранее чем через шесть месяцев со дня подачи лицом заявления о приостановлении исполнения обжалуемого решения; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nсумма, на которую выдана банковская гарантия, должна обеспечивать исполнение гарантом обязанности по уплате денежной суммы, указанной в заявлении о приостановлении исполнения обжалуемого решения. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nВышестоящий налоговый орган, рассматривающий жалобу, в течение пяти дней со дня получения заявления о приостановлении исполнения обжалуемого решения полностью или частично принимает одно из следующих решений: (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nо приостановлении исполнения полностью решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nо приостановлении частично исполнения решения о привлечении к ответственности за совершение налогового правонарушения и (или) об отказе в приостановлении частично исполнения решения о привлечении к ответственности за совершение налогового правонарушения либо о приостановлении частично исполнения решения об отказе в привлечении к ответственности за совершение налогового правонарушения и (или) об отказе в приостановлении частично исполнения решения об отказе в привлечении к ответственности за совершение налогового правонарушения; (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nоб отказе в приостановлении исполнения полностью решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nОснованием для принятия решения об отказе в приостановлении полностью или частично исполнения решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения является несоответствие банковской гарантии требованиям, установленным настоящей статьей и статьей 741 настоящего Кодекса. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nО принятом решении в течение трех дней со дня его принятия налоговый орган сообщает в письменной форме лицу, подавшему жалобу. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nРешение о приостановлении полностью или частично исполнения решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения действует до дня принятия вышестоящим налоговым органом решения по жалобе. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nВ случае неисполнения (неполного исполнения) обязанности по уплате денежной суммы по обжалуемому решению, обеспеченной банковской гарантией, лицом, подавшим жалобу, налоговый орган в срок не позднее пяти дней со дня принятия вышестоящим налоговым органом решения по жалобе направляет гаранту требование об уплате денежной суммы по банковской гарантии в части суммы налога, сбора, страховых взносов, пеней, штрафа, не уплаченной на день принятия вышестоящим налоговым органом решения по жалобе. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nНалоговый орган, вынесший обжалуемое решение, в соответствии со статьей 741 настоящего Кодекса уведомляет гаранта, выдавшего банковскую гарантию, о его освобождении от обязательств по этой гарантии в срок не позднее пяти дней со дня исполнения лицом, подавшим жалобу, обязанности по уплате суммы налога, сбора, страховых взносов, пеней, штрафа, которая была обеспечена такой банковской гарантией, либо не позднее пяти дней со дня принятия решения по жалобе, в соответствии с которым у лица, подавшего жалобу, отсутствует обязанность по уплате суммы налога, сбора, страховых взносов, пеней, штрафа, обеспеченная такой банковской гарантией. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\n52. В случае подачи физическим лицом, не являющимся индивидуальным предпринимателем, жалобы исполнение обжалуемого решения о привлечении к ответственности за совершение налогового правонарушения (решения об отказе в привлечении к ответственности за совершение налогового правонарушения), решения об отмене (полностью или частично) решения о предоставлении налогового вычета полностью или частично приостанавливается в части обжалуемых сумм налогов, сборов, страховых взносов, пеней, штрафов, процентов, обязанность по уплате которых не исполнена по состоянию на дату получения налоговым органом жалобы, до даты вступления в законную силу судебного акта о взыскании таких сумм.\n\nВ случае подачи физическим лицом, не являющимся индивидуальным предпринимателем, жалобы на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, исполнение обязанности налогоплательщика по уплате налога, указанного в налоговом уведомлении, приостанавливается в части обжалуемых сумм налогов, обязанность по уплате которых не исполнена по состоянию на дату получения налоговым органом жалобы, до даты истечения тридцати дней со дня принятия решения вышестоящего налогового органа об оставлении данной жалобы без удовлетворения (если в течение указанного тридцатидневного срока не было представлено уведомление о несогласии с решением вышестоящего налогового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении) или до даты вступления в законную силу судебного акта о взыскании таких сумм (если в течение указанного тридцатидневного срока такое уведомление было представлено) либо до принятия решения об оставлении жалобы без рассмотрения.\n\nВ случае подачи физическим лицом, не являющимся индивидуальным предпринимателем, жалобы на требование об уплате задолженности, на решение о взыскании задолженности исполнение обжалуемого акта налогового органа ненормативного характера приостанавливается в части обжалуемых сумм налогов, сборов, страховых взносов, пеней, штрафов, процентов, которые указаны в решении о привлечении к ответственности за совершение налогового правонарушения (решении об отказе в привлечении к ответственности за совершение налогового правонарушения), решении об отмене (полностью или частично) решения о предоставлении налогового вычета полностью или частично и (или) в налоговом уведомлении, обязанность по уплате которых не исполнена по состоянию на дату поступления в налоговый орган жалобы и в отношении которых отсутствует судебный акт о взыскании задолженности, до истечения пятнадцати дней со дня принятия решения по соответствующей жалобе.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\nОтзыв жалобы (апелляционной жалобы) лишает лицо, подавшее соответствующую жалобу, права на повторное обращение с жалобой (апелляционной жалобой) по тем же основаниям и в том же порядке. (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\n(Статья в редакции Федерального закона от 02.07.2013 № 153-ФЗ)","article_title":"Статья 138. Порядок обжалования","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a4c29367521f32bd360a16deede2f3afa0051aca9f8f5edc410f1834955ed272"},{"code_id":"NK_RF","article_number":"139","version_date":"2000-07-31","article_text":"1. Жалоба подается в вышестоящий налоговый орган через налоговый орган, акты ненормативного характера, действия или бездействие должностных лиц которого обжалуются. Налоговый орган, акты ненормативного характера, действия или бездействие должностных лиц которого обжалуются, обяз\n\nан в течение трех дней со дня поступления такой жалобы направить ее со всеми материалами в вышестоящий налоговый орган.\n\n2. Жалоба в вышестоящий налоговый орган может быть подана, если иное не установлено настоящим Кодексом, в течение одного года со дня, когда лицо узнало или должно было узнать о нарушении своих прав.\n\nЖалоба на вступившее в силу решение о привлечении к ответственности за совершение налогового правонарушения или решение об отказе в привлечении к ответственности за совершение налогового правонарушения, которое не было обжаловано в апелляционном порядке, может быть подана в течение одного года со дня вынесения обжалуемого решения.\n\nЖалоба в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, может быть подана в течение трех месяцев со дня принятия вышестоящим налоговым органом решения по жалобе (апелляционной жалобе).\n\nВ случае пропуска по уважительной причине срока подачи жалобы этот срок по ходатайству лица, подающего жалобу, может быть восстановлен вышестоящим налоговым органом.\n\n3. Вступившее в силу решение налогового органа, вынесенное по результатам рассмотрения материалов налоговой проверки консолидированной группы налогоплательщиков и не обжалованное в апелляционном порядке, может быть обжаловано ответственным участником этой группы либо самостоятельно иным участником этой группы в части привлечения такого участника к ответственности за совершение налогового правонарушения. Такая жалоба может быть подана в течение одного года со дня вынесения обжалуемого решения.\n\n(Статья в редакции Федерального закона от 02.07.2013 № 153-ФЗ)","article_title":"Статья 139. Порядок и сроки подачи жалобы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d9dcad5d1247a8156b4c8daefc25ffac0d10760f865417463ae7e9c68c07ec5"},{"code_id":"NK_RF","article_number":"139.1","version_date":"2000-07-31","article_text":"1. Апелляционная жалоба на решение о привлечении к ответственности за совершение налогового правонарушения или решение об отказе в привлечении к ответственности за совершение налогового правонарушения подается через вынесший соответствующее решение налоговый орган. Налоговый орган, решение которого обжалуется, обязан в течение трех дней со дня поступления такой жалобы направить ее со всеми материалами в вышестоящий налоговый орган.\n\n2. Апелляционная жалоба на решение о привлечении к ответственности за совершение налогового правонарушения или решение об отказе в привлечении к ответственности за совершение налогового правонарушения в вышестоящий налоговый орган может быть подана до дня вступления в силу обжалуемого решения.\n\n3. Апелляционная жалоба на решение налогового органа, вынесенное по результатам рассмотрения материалов налоговой проверки консолидированной группы налогоплательщиков, может быть подана до дня вступления в силу обжалуемого решения ответственным участником этой группы либо самостоятельно иным участником этой группы в части привлечения такого участника к ответственности за совершение налогового правонарушения.\n\n4. Не могут быть обжалованы в апелляционном порядке решение о привлечении к ответственности за совершение налогового правонарушения и решение об отказе в привлечении к ответственности за совершение налогового правонарушения, вынесенные федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение статьей - Федеральный закон от 02.07.2013 № 153-ФЗ)","article_title":"Статья 139.1. Порядок и сроки подачи апелляционной жалобы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f90efc1818aa7ce4364888d9008d1145b17c8941dbe4ca9991431cc494ef456"},{"code_id":"NK_RF","article_number":"139.2","version_date":"2000-07-31","article_text":"1. Жалоба подается в письменной форме. Жалоба подписывается лицом, ее подавшим, или его представителем.\n\nЖалоба может быть направлена в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика. (Дополнение абзацем - Федеральный закон от 01.05.2016 № 130-ФЗ)\n\nФорматы и порядок представления жалобы в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 01.05.2016 № 130-ФЗ)\n\n2. В жалобе указываются:\n\n1) фамилия, имя, отчество и место жительства физического лица, подающего жалобу, или наименование и адрес организации, подающей жалобу;\n\n2) обжалуемые акт налогового органа ненормативного характера, действия или бездействие его должностных лиц;\n\n3) наименование налогового органа, акт ненормативного характера которого, действия или бездействие должностных лиц которого обжалуются;\n\n4) основания, по которым лицо, подающее жалобу, считает, что его права нарушены;\n\n5) требования лица, подающего жалобу;\n\n6) способ получения решения по жалобе: на бумажном носителе, в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика. (Дополнение подпунктом - Федеральный закон от 01.05.2016 № 130-ФЗ)\n\n3. В жалобе могут быть указаны номера телефонов, факсов, адреса электронной почты и иные необходимые для своевременного рассмотрения жалобы сведения.\n\n4. В случае подачи жалобы уполномоченным представителем лица, обжалующего акт налогового органа ненормативного характера, действия или бездействие его должностных лиц, к жалобе прилагаются документы, подтверждающие полномочия этого представителя.\n\n5. К жалобе могут быть приложены документы, подтверждающие доводы лица, подающего жалобу.\n\n6. Положения настоящей статьи применяются также к апелляционной жалобе.\n\n(Дополнение статьей - Федеральный закон от 02.07.2013 № 153-ФЗ)","article_title":"Статья 139.2. Форма и содержание жалобы (апелляционной жалобы)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f35779a7fcaab968d7db319cb35bc929be68cf15f4180c338aa050456e0ebba0"},{"code_id":"NK_RF","article_number":"139.3","version_date":"2000-07-31","article_text":"1. Вышестоящий налоговый орган оставляет без рассмотрения жалобу полностью или в части, если установит, что:\n\n1) жалоба подана с нарушением порядка, установленного пунктом 1 статьи 1392 настоящего Кодекса, или в жалобе не указаны акты налогового органа ненормативного характера, действия или бездействие его должностных лиц, которые привели к нарушению прав лица, подавшего жалобу; (В редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\n2) жалоба подана после истечения срока подачи жалобы, установленного настоящим Кодексом, и не содержит ходатайства о его восстановлении или в восстановлении пропущенного срока на подачу жалобы отказано;\n\n3) до принятия решения по жалобе от лица, ее подавшего, поступило заявление об отзыве жалобы полностью или в части;\n\n4) ранее подана жалоба по тем же основаниям, за исключением случая, если после ее рассмотрения разрешен спор о том же предмете и по тем же основаниям в порядке, предусмотренном главой 203 настоящего Кодекса; (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\n5) до принятия решения по жалобе налоговый орган сообщил об устранении нарушения прав лица, подавшего жалобу, в порядке, установленном пунктом 11 статьи 139 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 01.05.2016 № 130-ФЗ)\n\n6) до принятия решения по жалобе налоговый спор о том же предмете и по тем же основаниям был разрешен судом; (Дополнение подпунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n7) жалоба не подписана лицом, подавшим жалобу, или его представителем либо не представлены оформленные в установленном порядке документы, подтверждающие полномочия представителя лица на ее подписание; (Дополнение подпунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n8) до принятия решения по жалобе организация, подавшая жалобу, исключена из Единого государственного реестра юридических лиц по решению регистрирующего органа или ликвидирована либо получены сведения о смерти или об объявлении умершим физического лица, подавшего жалобу, и при этом спорное правоотношение не допускает правопреемства. (Дополнение подпунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nВ случае, предусмотренном подпунктом 5 пункта 1 настоящей статьи, налоговый орган, рассматривающий жалобу, принимает решение об оставлении жалобы без рассмотрения полностью или в части в течение пяти дней со дня получения информации или документов об устранении нарушения прав лица, подавшего жалобу.\n\nВ случаях, предусмотренных подпунктами 6 и 8 пункта 1 настоящей статьи, налоговый орган, рассматривающий жалобу, принимает решение об оставлении жалобы без рассмотрения полностью или в части в течение пяти дней со дня получения информации о наличии указанных в данных подпунктах обстоятельств. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nРешение об оставлении жалобы без рассмотрения вручается или направляется лицу, подавшему жалобу, в течение трех дней со дня его принятия.\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 02.07.2013 № 153-ФЗ)","article_title":"Статья 139.3. Оставление жалобы (апелляционной жалобы) без рассмотрения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"26db0d7d130e178ce71eee80fbd817f68aac9e5c4fb68c8fa59df221e13745f4"}]$law7v022$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
